    data = _read_abinfo()
    if not data:
        h.send_json({"ok": False, "running": False,
                     "mode": "", "last_tune": "", "mute": "",
                     "rx_port": "", "tx_port": "", "version": "",
                     "callsign": "", "tg": "", "ts": ""})
        return
    tlv     = data.get("tlv",     {})
    digital = data.get("digital", {})
    ab_meta = data.get("ab",      {})
