def _con_meminfo() -> dict:
    out = {}
    try:
        for ln in Path("/proc/meminfo").read_text().splitlines():
            parts = ln.split()
            if len(parts) >= 2 and parts[1].isdigit():
                out[parts[0].rstrip(":")] = int(parts[1])
    except OSError:
        pass
    return out

def _con_vmstat_swap() -> "tuple[int, int]":
    vi = vo = 0
    for ln in Path("/proc/vmstat").read_text().splitlines():
        k, _, v = ln.partition(" ")
        if k == "pswpin":
            vi = int(v)
        elif k == "pswpout":
            vo = int(v)
    return vi, vo

def _con_sys_swap_now(secs: int = 5) -> "tuple[str, str, dict]":
    cmd = f"/proc/vmstat swap counters over {secs} s"
    try:
        i1, o1 = _con_vmstat_swap()
        time.sleep(secs)
        i2, o2 = _con_vmstat_swap()
    except (OSError, ValueError) as exc:
        return cmd, str(exc), {"status": "info", "headline": "Couldn't read /proc/vmstat"}
    pg = (os.sysconf("SC_PAGE_SIZE") if hasattr(os, "sysconf") else 4096) // 1024 or 4
    pin, pout = (i2 - i1) / secs, (o2 - o1) / secs
    mi = _con_meminfo()
    av, tot = mi.get("MemAvailable", 0), mi.get("MemTotal", 0)
    st_, sf = mi.get("SwapTotal", 0), mi.get("SwapFree", 0)
    raw = (f"pswpin  {i1} -> {i2}  ({pin:.1f} pages/s)\n"
           f"pswpout {o1} -> {o2}  ({pout:.1f} pages/s)\n"
           f"page size {pg} KB, watched {secs} s\n"
           f"MemAvailable {av} kB of {tot} kB, swap used {st_ - sf} kB of {st_} kB")
    total = pin + pout
    if total == 0:
        status, head = "pass", ("Not swapping -- the swap is just parked, nothing to do" if st_ - sf > 0
                                else "Not swapping")
    elif total < 10:
        status, head = "info", "A little swapping -- normal now and then"
    else:
        status, head = "warn", "Swapping now -- short on memory, things will feel slow"
    return cmd, raw, {"status": status, "headline": head, "rows": [
        ["Coming back from the SD card", f"{pin * pg:.0f} KB/s"],
        ["Going out to the SD card", f"{pout * pg:.0f} KB/s"],
        ["Memory free", f"{av // 1024} of {tot // 1024} MB"],
        ["Swap used", f"{(st_ - sf) // 1024} of {st_ // 1024} MB" if st_ else "no swap"]],
        "note": "" if status == "pass" else "Press Programs in swap to see which program is using it"}

def _con_sys_swap_progs(top: int = 8) -> "tuple[str, str, dict]":
    cmd = "/proc/*/status VmSwap"
    rows = []
    for d in Path("/proc").iterdir():
        if not d.name.isdigit():
            continue
        try:
            txt = (d / "status").read_text(errors="replace")
        except OSError:
            continue
        f = {}
        for ln in txt.splitlines():
            k, _, v = ln.partition(":")
            if k in ("Name", "VmSwap", "VmRSS"):
                f[k] = v.strip()
        try:
            sw = int(f.get("VmSwap", "0 kB").split()[0])
            rss = int(f.get("VmRSS", "0 kB").split()[0])
        except (ValueError, IndexError):
            continue
        if sw > 0:
            rows.append((sw, rss, f.get("Name", "?"), d.name))
    rows.sort(reverse=True)
    raw = "\n".join(f"{n:<20} swap {sw:>8} kB  memory {rss:>8} kB  pid {pid}" for sw, rss, n, pid in rows) \
        or "No program has anything in swap"
    if not rows:
        return cmd, raw, {"status": "pass", "headline": "Nothing is in swap"}
    tot = sum(r[0] for r in rows)
    big = rows[0]
    return cmd, raw, {"status": "info",
        "headline": f"Most swap: {big[2]} ({big[0] // 1024} MB of {tot // 1024} MB in swap)",
        "table": {"head": ["Program", "In swap", "In memory", "Process"],
                  "rows": [[n, f"{sw // 1024} MB" if sw >= 1024 else f"{sw} KB",
                            f"{rss // 1024} MB" if rss >= 1024 else f"{rss} KB", pid]
                           for sw, rss, n, pid in rows[:top]]},
        "note": "Restarting the program at the top frees its swap; a reboot clears it all"}

_PH_NODE_MIN, _PH_NODE_MAX = 1000, 1999

def _ph_node_ok(v: str) -> bool:
    return v.isdigit() and _PH_NODE_MIN <= int(v) <= _PH_NODE_MAX

def _ph_hand_nodes(ctx: dict) -> set:
    return {s["name"] for s in ctx["conf"]["rpt.conf"]
            if s["name"].isdigit() and not s["is_template"] and not s["managed"]}

def _ph_expected_nodes(dash: dict, hand: "set | None" = None) -> "tuple[list, str, set]":
    base = dash.get("phone_node") or "1001"
    bn = dash.get("bridge_nodes") or []
    reserved = {x for i, x in enumerate(bn) if x and i != 2}
    if dash.get("asl_node"):
        reserved.add(dash["asl_node"])
    nets = [dict(n) for n in dash.get("networks", [])]
    used: set = set()
    for n in nets:
        v = n.get("node", "")
        n["saved"] = bool(v)
        if _ph_node_ok(v) and v not in reserved and v not in used:
            used.add(v)
        else:
            n["node"] = ""
    start = int(base) if _ph_node_ok(base) else 1001
    span = _PH_NODE_MAX - _PH_NODE_MIN + 1
    for n in nets:
        if n["node"]:
            continue
        n["saved"] = False
        for k in range(span):
            c = str(_PH_NODE_MIN + (start - _PH_NODE_MIN + k) % span)
            if c not in used and c not in reserved and c not in (hand or ()):
                n["node"] = c
                used.add(c)
                break
    for n in nets:
        n["picked"] = n["id"] == dash.get("active")
    return nets, base, reserved

def _ph_main_links(main: str) -> "list | None":
    out = _ph_cli(f"rpt show variables {main}", 4)
    m = re.search(r"RPT_LINKS\s*=\s*(.+)", out or "", re.I)
    if not m:
        return None
    raw = m.group(1).strip()
    if "," in raw:
        raw = raw[raw.index(",") + 1:]
    return [t[1:] if t[:1] in "TR" and t[1:].isdigit() else t for t in re.split(r"[,\s]+", raw) if t]

def _con_sys_phone_nodes() -> "tuple[str, str, dict]":
    cmd = "phone.json + rpt.conf + rpt localnodes + rpt show variables"
    ctx = _ph_load_ctx()
    dash = ctx["dash"]
    nets, base, _res = _ph_expected_nodes(dash, _ph_hand_nodes(ctx))
    secs = {s["name"]: s for s in ctx["conf"]["rpt.conf"] if s["name"].isdigit() and not s["is_template"]}
    running = _ph_ast_running()
    local = set()
    links = None
    if running:
        local = {ln.strip() for ln in _ph_cli("rpt localnodes", 4).splitlines() if ln.strip().isdigit()}
        links = _ph_main_links(dash["asl_node"]) if dash.get("asl_node") else None
    rows, raw, bad = [], [], 0
    owned = {n["node"] for n in nets}
    items = [(n["name"] + (" (picked)" if n["picked"] else ""), n["node"], n["saved"], n["picked"]) for n in nets]
    if base not in owned:
        items.append(("Phone Bridge (no network)", base, True, not nets))
    for name, node, saved, picked in items:
        sec = secs.get(node)
        in_conf = ("yes, dashboard" if sec and sec["managed"] else "hand-made" if sec else "no")
        run_ = "?" if not running else ("yes" if node in local else "no")
        lk = "?" if links is None else ("yes" if node in links else "no")
        conf_cls = "pass" if in_conf == "yes, dashboard" else "fail"
        run_cls = "" if run_ == "?" else ("pass" if run_ == "yes" else "fail")
        lk_cls = "" if lk != "yes" else ("pass" if picked else "warn")
        if conf_cls == "fail" or run_cls == "fail":
            bad += 1
        rows.append([name, node + ("" if saved else " (new)"), [in_conf, conf_cls], [run_, run_cls], [lk, lk_cls]])
        raw.append(f"{name:<32} node {node:<6}{'' if saved else ' (not saved yet)'}  rpt.conf: {in_conf:<15}"
                   f" running: {run_:<4} linked to radio: {lk}")
    extra = [i[1] for i in items if not i[3] and links and i[1] in links]
    if not nets:
        return cmd, "No phone networks in /etc/asl_dvs/phone.json", {
            "status": "info", "headline": "No phone networks yet", "table": {"head": ["Network", "Node", "In rpt.conf", "Running", "Linked to radio"], "rows": rows}}
    if bad:
        status, head = "fail", f"{bad} phone node{'s are' if bad != 1 else ' is'} not set up"
        note = ("On the dashboard: Edit page -> Phone -> Save Phone writes them (tick 'Restart Asterisk "
                "if needed' if a node doesn't start).  Before dashboard v9.3.42 only 1001 exists -- that is expected")
    elif extra:
        status, head = "warn", "More than one phone node is linked"
        note = "Only the picked network's node should be linked; the dashboard drops the others within a few seconds"
    else:
        status, head = "pass", f"{len(nets)} phone network{'s' if len(nets) != 1 else ''}, each with its own node"
        note = "Only the picked network's node is linked to your radio, and only while the Phone tab is open"
    if not running:
        note += ".  Asterisk isn't running, so Running and Linked show ?"
        if status == "pass":
            status, head = "info", "rpt.conf is set up; Asterisk isn't running"
    return cmd, "\n".join(raw), {"status": status, "headline": head,
                                 "table": {"head": ["Network", "Node", "In rpt.conf", "Running", "Linked to radio"],
                                           "rows": rows}, "note": note}

def _con_sys_phone_clash() -> "tuple[str, str, dict]":
    cmd = "phone.json + asl_dvs.conf + rpt.conf"
    ctx = _ph_load_ctx()
    dash = ctx["dash"]
    hand = _ph_hand_nodes(ctx)
    nets, base, reserved = _ph_expected_nodes(dash, hand)
    raw_saved: dict = {}
    for n in dash.get("networks", []):
        if n.get("node"):
            raw_saved.setdefault(n["node"], []).append(n["name"])
    rows, problems = [], 0
    start = int(base) if _ph_node_ok(base) else 1001
    look = [n["node"] for n in nets] + [str(start + k) for k in range(6) if start + k <= _PH_NODE_MAX]
    for v in list(raw_saved):
        if v not in look:
            look.append(v)
    for node in sorted(dict.fromkeys(look), key=lambda x: (len(x), x)):
        who = [n["name"] for n in nets if n["node"] == node]
        issues = []
        if node in hand:
            issues.append("rpt.conf already has a hand-made [" + node + "]")
        if node in reserved:
            issues.append("this is your radio node or another bridge")
        if len(raw_saved.get(node, [])) > 1:
            issues.append("saved on two networks: " + ", ".join(raw_saved[node]))
        if not _ph_node_ok(node):
            issues.append("outside 1000-1999 (private nodes)")
        if issues and who:
            problems += 1
        cls = "fail" if issues and who else ("warn" if issues else "pass")
        rows.append([node, ", ".join(who) or "not used", ["; ".join(issues) or "OK", cls]])
    raw = "\n".join(f"{r[0]:<6} {r[1]:<30} {r[2][0]}" for r in rows)
    if problems:
        status, head = "fail", f"{problems} phone node number{'s clash' if problems != 1 else ' clashes'}"
        note = "Pick another number for that network on the dashboard Edit page (Phone, the network's Node number box)"
    elif any(r[2][1] == "warn" for r in rows):
        status, head = "warn", "No clash now, but a free number is taken"
        note = "A network added later skips it automatically; nothing to do"
    else:
        status, head = "pass", "No clashes"
        note = f"Numbers count up from the Phone Bridge ({base}); 1000-1999 are private nodes"
    return cmd, raw, {"status": status, "headline": head,
                      "table": {"head": ["Node", "Network", "Check"], "rows": rows}, "note": note}

_CON_SYS = {"@swap_now": _con_sys_swap_now, "@swap_progs": _con_sys_swap_progs,
            "@phone_nodes": _con_sys_phone_nodes, "@phone_clash": _con_sys_phone_clash}

def _con_sip_host() -> str:
    try:
        nets = [n_ for n_ in _phone_sec_networks(_ph_load_ctx()).get("networks", [])
                if n_.get("type", "").startswith("sip") and n_.get("host")]
    except Exception as exc:
        _log(f"console: phone network lookup failed: {exc}")
        return ""
    pid = _ph_signin_choice()[1]
    pick = next((n_ for n_ in nets if n_.get("id") == pid), None) or (nets[0] if nets else None)
    host = str(pick.get("host", "")) if pick else ""
    return host if re.fullmatch(r"[A-Za-z0-9.\-]{1,253}", host) else ""

_CON_DEBUG = {"rtp": False, "sip": False, "timer": None}

_CON_DEBUG_SEC = 300

def _con_nodes() -> list:
    try:
        return [n["id"] for n in _dvsm_read_rpt_conf().get("nodes", [])]
    except Exception:
        return []

def _con_debug_off(which: str = "both") -> None:
    if which in ("both", "rtp") and _CON_DEBUG["rtp"]:
        _ph_cli("rtp set debug off", timeout=4)
        _CON_DEBUG["rtp"] = False
    if which in ("both", "sip") and _CON_DEBUG["sip"]:
        _ph_cli("pjsip set logger off", timeout=4)
        _CON_DEBUG["sip"] = False

def _con_debug_arm() -> None:
    tm = _CON_DEBUG.get("timer")
    if tm:
        tm.cancel()
    tm = threading.Timer(_CON_DEBUG_SEC, _con_debug_off)
    tm.daemon = True
    _CON_DEBUG["timer"] = tm
    tm.start()

def _con_cleanup() -> None:
    tm = _CON_DEBUG.get("timer")
    if tm:
        tm.cancel()
        _CON_DEBUG["timer"] = None
    _con_debug_off()

_CON_SUMS: dict = {}

def _con_sum(*ids):
    def deco(fn):
        for i in ids:
            _CON_SUMS[i] = fn
        return fn
    return deco

def _con_dots(raw: str) -> dict:
    out = {}
    for line in raw.splitlines():
        m = re.match(r"^\s*([A-Za-z][^:.]*?)\s*\.{2,}\s*:\s*(.*)$", line) or \
            re.match(r"^\s*([A-Za-z][^:]{0,60}?):\s+(.*)$", line)
        if m:
            out[m.group(1).strip()] = m.group(2).strip()
    return out

def _con_summary(bid: str, raw: str, node: str) -> "dict | None":
    fn = _CON_SUMS.get(bid)
    if fn is None or not raw.strip():
        return None if raw.strip() else {"status": "info", "headline": "No output"}
    return fn(raw, node)

@_con_sum("rpt_stats")
def _cs_rpt_stats(raw: str, node: str):
    kv = _con_dots(raw)
    if "Uptime" not in kv and "System" not in kv:
        return None
    links = kv.get("Nodes currently connected to us", "")
    links = "" if links.strip().lower() in ("<none>", "none", "") else links
    rows = [["Receiving now", "yes" if kv.get("Signal on input", "").upper() == "YES" else "no"],
            ["System", kv.get("System", "?").lower()],
            ["Links", links or "none"],
            ["Autopatch", kv.get("Autopatch state", "?").lower()],
            ["Time-out timer", kv.get("Time out timer state", "?").lower()],
            ["Time-outs since start", kv.get("Time outs since system initialization", "?")],
            ["Key-ups today", kv.get("Keyups today", "?")],
            ["Transmit time today", kv.get("TX time today", "?")],
            ["Last command", kv.get("Last DTMF command executed", "")],
            ["Node uptime", kv.get("Uptime", "?")]]
    st = "pass"
    note = ""
    if kv.get("System", "").upper() == "DISABLED":
        st, note = "fail", "The node is disabled"
    elif kv.get("Time outs since system initialization", "0") not in ("0", ""):
        st, note = "warn", "The transmitter has hit its time-out limit since Asterisk started"
    n_links = len([x for x in re.split(r"[,\s]+", links) if x])
    return {"status": st, "headline": f"Node {node}: {n_links} link{'s' if n_links != 1 else ''}"
                                     + (", receiving" if rows[0][1] == "yes" else ""), "rows": rows, "note": note}

@_con_sum("rpt_lstats")
def _cs_rpt_lstats(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        tok = line.split()
        if len(tok) >= 6 and tok[0] not in ("NODE", "----") and tok[3] in ("IN", "OUT"):
            state = " ".join(tok[5:])
            rows.append([tok[0], tok[3].lower(), tok[4].rsplit(":", 1)[0] if tok[4].count(":") == 3 else tok[4],
                         tok[2], [state.lower(), "pass" if state.upper() == "ESTABLISHED" else "warn"]])
    if not rows and "NODE" not in raw:
        return None
    bad = [r for r in rows if r[4][1] != "pass"]
    return {"status": "warn" if bad else ("pass" if rows else "info"),
            "headline": f"{len(rows)} link{'s' if len(rows) != 1 else ''}" + (f", {len(bad)} not connected" if bad else ""),
            "table": {"head": ["Node", "Direction", "Connected", "Reconnects", "State"], "rows": rows}}

def _con_vars(raw: str) -> dict:
    return {m.group(1): m.group(2) for m in re.finditer(r"(RPT_[A-Z_]+|[a-z_]+_ena)=([^\s~]*)", raw)}

def _con_alinks(val: str) -> list:
    out = []
    for item in val.split(",")[1:]:
        m = re.match(r"^(\S+?)([TRC])([KU])$", item.strip())
        if m:
            out.append((m.group(1), {"T": "talk + listen", "R": "listen only", "C": "local monitor"}[m.group(2)],
                        m.group(3) == "K"))
    return out

@_con_sum("rpt_vars")
def _cs_rpt_vars(raw: str, node: str):
    v = _con_vars(raw)
    if not v:
        return None
    yes = lambda k: "yes" if v.get(k, "0") == "1" else "no"
    rows = [["Transmitting", yes("RPT_TXKEYED")], ["Receiving", yes("RPT_RXKEYED")],
            ["Autopatch", "up" if v.get("RPT_AUTOPATCHUP", "0") == "1" else "down"],
            ["Links", v.get("RPT_NUMLINKS", "?")],
            ["Linked nodes", ", ".join(n for n, _m, _k in _con_alinks(v.get("RPT_ALINKS", ""))) or "none"]]
    busy = v.get("RPT_TXKEYED") == "1" or v.get("RPT_RXKEYED") == "1"
    return {"status": "info", "headline": "Busy right now" if busy else "Idle", "rows": rows}

@_con_sum("rpt_xnode")
def _cs_rpt_xnode(raw: str, node: str):
    v = _con_vars(raw)
    al = _con_alinks(v.get("RPT_ALINKS", ""))
    times = {}
    for line in re.split(r"[~\n]", raw):
        tok = line.split()
        if len(tok) >= 6 and tok[3] in ("IN", "OUT"):
            times[tok[0]] = (tok[3].lower(), tok[4])
    if not al and not times:
        return None if "RPT_" not in raw else {"status": "info", "headline": "No links"}
    rows = []
    for n, mode, keyed in al:
        d, ct = times.get(n, ("", ""))
        rows.append([n, mode, d, ct, ["talking" if keyed else "quiet", "warn" if keyed else ""]])
    for n, (d, ct) in times.items():
        if n not in [r[0] for r in rows]:
            rows.append([n, "", d, ct, ""])
    return {"status": "info", "headline": f"{len(rows)} link{'s' if len(rows) != 1 else ''}",
            "table": {"head": ["Node", "Mode", "Direction", "Connected", "Now"], "rows": rows}}

@_con_sum("rpt_local")
def _cs_rpt_local(raw: str, node: str):
    nodes = [ln.strip() for ln in raw.splitlines() if re.fullmatch(r"\s*\d{3,7}\s*", ln)]
    if not nodes:
        return None
    labels = {"1999": "DV Bridge", "1917": "M17 Bridge", "1001": "Phone Bridge"}
    try:
        for nd_, nm in (_ph_dash_info().get("phone_nodes") or {}).items():
            labels[nd_] = f"Phone node ({nm})"
    except Exception:
        pass
    return {"status": "pass", "headline": f"{len(nodes)} node{'s' if len(nodes) != 1 else ''} running on this Pi",
            "table": {"head": ["Node", "What"], "rows": [[n, labels.get(n, "radio / private node")] for n in nodes]}}

@_con_sum("rpt_regs")
def _cs_rpt_regs(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        tok = line.split()
        if len(tok) >= 4 and tok[0] != "Host" and re.search(r"[a-z]", tok[0], re.I) and "." in tok[0]:
            state = next((x for x in reversed(tok) if not x.isdigit()), "?")
            ok = state.lower() == "registered"
            user = tok[1] if len(tok) > 1 else ""
            seen = next((x for x in tok if re.fullmatch(r"\d+\.\d+\.\d+\.\d+:\d+", x)), "")
            rows.append([user, seen, ["Registered" if ok else state, "pass" if ok else "fail"]])
    if not rows:
        return None
    bad = [r for r in rows if r[2][1] != "pass"]
    return {"status": "fail" if bad else "pass",
            "headline": "All nodes registered" if not bad else f"{len(bad)} not registered",
            "table": {"head": ["Node", "Seen from", "State"], "rows": rows}}

@_con_sum("uptime")
def _cs_uptime(raw: str, node: str):
    kv = _con_dots(raw)
    up, rl = kv.get("System uptime", ""), kv.get("Last reload", "")
    if not up:
        return None
    return {"status": "info", "headline": f"Running for {up}", "rows": [["Last reload", rl]]}

@_con_sum("version")
def _cs_version(raw: str, node: str):
    m = re.search(r"Asterisk\s+(\S+)", raw)
    if not m:
        return None
    full = m.group(1)
    asl = re.search(r"asl3-([\d.]+)", full)
    ast = full.split("+", 1)[0]
    return {"status": "info", "headline": f"ASL3 {asl.group(1) if asl else '?'} · Asterisk {ast}",
            "rows": [["Full version", full]],
            "note": "Compare with the latest AllStarLink v3 release; update with sudo apt update && sudo apt upgrade"}

_CON_KEY_MODS = (("app_rpt.so", "AllStar (app_rpt)", "fail"), ("chan_iax2.so", "AllStar links (IAX2)", "fail"),
                 ("chan_simpleusb.so", "USB radio (SimpleUSB)", "info"), ("chan_usbradio.so", "USB radio (usbradio)", "info"),
                 ("chan_usrp.so", "DVSwitch / M17 bridges (USRP)", "warn"),
                 ("chan_pjsip.so", "Phone (SIP)", "warn"), ("res_pjsip.so", "Phone (SIP core)", "warn"),
                 ("res_rtp_asterisk.so", "Call audio (RTP)", "warn"), ("chan_echolink.so", "EchoLink", "info"))

@_con_sum("modules")
def _cs_modules(raw: str, node: str):
    run = {}
    for line in raw.splitlines():
        tok = line.split()
        if tok and tok[0].endswith(".so"):
            run[tok[0]] = "Running" in line
    if not run:
        return None
    rows, worst = [], "pass"
    rank = {"pass": 0, "info": 1, "warn": 2, "fail": 3}
    for mod, what, miss in _CON_KEY_MODS:
        if run.get(mod):
            rows.append([what, mod, ["running", "pass"]])
        else:
            rows.append([what, mod, ["not loaded", miss if miss != "info" else ""]])
            if rank[miss] > rank[worst]:
                worst = miss
    return {"status": worst, "headline": f"{len(run)} modules loaded",
            "table": {"head": ["Feature", "Module", "State"], "rows": rows},
            "note": "Only the modules the node, bridges and phone need are listed; Show full output has them all"}

@_con_sum("sip_regs")
def _cs_sip_regs(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        m = re.match(r"^\s*(\S+?)/(sip:\S+)\s+(\S+)\s+(Registered|Unregistered|Rejected|Stopped|Retry Wait|Retrying)\b(.*)$", line)
        if m:
            ok = m.group(4) == "Registered"
            acct = m.group(1)
            if _ph_signin_choice()[1] and acct == _ph_signin_choice()[1] + "-reg":
                acct += " (picked)"
            rows.append([acct, m.group(2), [m.group(4) + m.group(5).strip().replace("(exp. ", " · renews in ").rstrip(")"),
                                            "pass" if ok else "fail"]])
    if not rows:
        return None if "Objects found" not in raw and "No objects" not in raw else \
            {"status": "info", "headline": "No phone accounts sign in"}
    bad = [r for r in rows if r[2][1] != "pass"]
    return {"status": "fail" if bad else "pass", "headline": "Signed in" if not bad else f"{len(bad)} not signed in",
            "table": {"head": ["Account", "Server", "State"], "rows": rows}}

def _cs_contact_rows(raw: str) -> list:
    rows = []
    for line in raw.splitlines():
        m = re.match(r"^\s*Contact:\s+(\S+?)/(sip:\S+)\s+\S+\s+(Avail|Unavail|NonQual|Unknown|Created|Removed|Updated)\s*([\d.]+)?", line)
        if m:
            st = m.group(3)
            rows.append([m.group(1), m.group(2), [st if st != "NonQual" else "not checked",
                                                  {"Avail": "pass", "Unavail": "fail"}.get(st, "")],
                         (m.group(4) + " ms") if m.group(4) and m.group(4) != "nan" else ""])
    return rows

@_con_sum("sip_contacts")
def _cs_sip_contacts(raw: str, node: str):
    rows = _cs_contact_rows(raw)
    if not rows:
        return None if "Contact:" not in raw else {"status": "info", "headline": "No contacts"}
    bad = [r for r in rows if r[2][1] == "fail"]
    return {"status": "fail" if bad else "pass",
            "headline": "Reachable" if not bad else f"{len(bad)} unreachable",
            "table": {"head": ["Account", "Address", "State", "Response"], "rows": rows}}

@_con_sum("sip_endpoints")
def _cs_sip_endpoints(raw: str, node: str):
    eps, cur = [], None
    for line in raw.splitlines():
        m = re.match(r"^\s*Endpoint:\s+(\S+)\s+(Not in use|In use|Unavailable|Busy|Ringing|Invalid|On Hold|Unknown)\b", line)
        if m and not m.group(1).startswith("<"):
            cur = {"name": m.group(1), "state": m.group(2), "contact": "", "rtt": ""}
            eps.append(cur)
            continue
        if cur is not None:
            c = _cs_contact_rows(line)
            if c and not cur["contact"]:
                cur["contact"], cur["rtt"] = c[0][2][0], c[0][3]
    if not eps:
        return None
    rows = []
    for e in eps:
        st = "fail" if e["state"] == "Unavailable" else ("pass" if e["contact"] in ("Avail", "") else "warn")
        rows.append([e["name"], [e["state"].lower(), st], e["contact"] or "—", e["rtt"]])
    bad = [r for r in rows if r[1][1] == "fail"]
    return {"status": "fail" if bad else "pass",
            "headline": f"{len(rows)} endpoint{'s' if len(rows) != 1 else ''}" + (f", {len(bad)} unavailable" if bad else ""),
            "table": {"head": ["Endpoint", "State", "Contact", "Response"], "rows": rows}}

@_con_sum("sip_transports")
def _cs_sip_transports(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        m = re.match(r"^\s*Transport:\s+(\S+)\s+(udp|tcp|tls|ws|wss)\s+\d+\s+\d+\s+(\S+)", line, re.I)
        if m and not m.group(1).startswith("<"):
            rows.append([m.group(1), m.group(2).upper(), m.group(3)])
    if not rows:
        return None
    return {"status": "info", "headline": f"{len(rows)} transport{'s' if len(rows) != 1 else ''}",
            "table": {"head": ["Name", "Type", "Listening on"], "rows": rows},
            "note": "The outside address is in the full output of: pjsip show transport <name>"}

_CON_KIND = (("pjsip/", "phone call"), ("iax2/", "AllStar link / IAX call"), ("sip/", "phone call"),
             ("local/", "internal"), ("dahdi/", "internal"), ("recorder/", "internal"), ("announcer/", "internal"),
             ("usrp/", "bridge"), ("simpleusb/", "radio"), ("usbradio/", "radio"), ("echolink/", "EchoLink"))

@_con_sum("calls")
def _cs_calls(raw: str, node: str):
    rows, phone = [], 0
    for line in raw.splitlines():
        f = line.split("!")
        if len(f) < 12:
            continue
        kind = next((k for p, k in _CON_KIND if f[0].lower().startswith(p)), "other")
        if kind == "phone call":
            phone += 1
        try:
            secs = int(f[11])
            dur = f"{secs // 60}:{secs % 60:02d}"
        except ValueError:
            dur = f[11]
        rows.append([f[0], kind, f[7] or "", f[4], dur])
    if not rows:
        return {"status": "info", "headline": "Nothing up right now"} if raw.strip() == "" or "!" not in raw else None
    hidden = [r for r in rows if r[1] == "internal"]
    rows = [r for r in rows if r[1] != "internal"]
    order = {"phone call": 0, "AllStar link / IAX call": 1, "EchoLink": 2, "bridge": 3, "radio": 4}
    rows.sort(key=lambda r: (order.get(r[1], 9), r[0]))
    return {"status": "info", "headline": f"{phone} phone call{'s' if phone != 1 else ''} · {len(rows)} shown",
            "table": {"head": ["Channel", "What", "Caller", "State", "Time"], "rows": rows},
            "note": f"{len(hidden)} internal app_rpt channels hidden -- Show full output has them" if hidden else ""}

@_con_sum("sip_quality")
def _cs_sip_quality(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        tok = line.split()
        idx = next((i for i, x in enumerate(tok) if re.fullmatch(r"\d+:\d\d:\d\d", x)), None)
        if idx is None or idx < 1 or len(tok) < idx + 10:
            continue
        try:
            n = [float(x) for x in tok[idx + 2:idx + 10]]
        except ValueError:
            continue
        worst = max(n[2], n[6])
        st = "fail" if worst >= 10 else ("warn" if worst >= 3 else "pass")
        rows.append([tok[idx - 1], tok[idx + 1], f"{int(n[0])} / {n[2]:g}% / {n[3]:g}",
                     f"{int(n[4])} / {n[6]:g}% / {n[7]:g}", [("good" if st == "pass" else "choppy likely" if st == "warn" else "bad"), st]])
    if not rows:
        return None if "UpTime" not in raw and "Objects found" not in raw else \
            {"status": "info", "headline": "No call is up", "note": "Start a call, then press Call quality"}
    st = "fail" if any(r[4][1] == "fail" for r in rows) else ("warn" if any(r[4][1] == "warn" for r in rows) else "pass")
    return {"status": st, "headline": f"{len(rows)} call{'s' if len(rows) != 1 else ''}",
            "table": {"head": ["Channel", "Codec", "In: packets / lost / jitter", "Out: packets / lost / jitter", "Quality"],
                      "rows": rows},
            "note": "Lost above 3% usually sounds choppy. Jitter is in seconds."}

@_con_sum("dialplan")
def _cs_dialplan(raw: str, node: str):
    if "no existence" in raw.lower() or "doesn't exist" in raw.lower():
        return {"status": "fail", "headline": "Phone dialing rules are not loaded",
                "note": "Press Save Phone on the dashboard Edit page, then Dialplan reload"}
    m = re.search(r"-=\s*(\d+)\s+extensions?\s*\((\d+)\s+priorit", raw)
    if not m:
        return None
    inc = re.findall(r"Include =>\s*'([^']+)'", raw)
    rows = [["Rules", m.group(1)], ["Steps", m.group(2)]]
    if inc:
        rows.append(["Also uses", ", ".join(inc)])
    return {"status": "pass", "headline": "Phone dialing rules are loaded", "rows": rows}

@_con_sum("phone_db")
def _cs_phone_db(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        m = re.match(r"^\s*/dvsphone/(\S+)\s*:\s*(.*)$", line)
        if m:
            k, v = m.group(1), m.group(2).strip()
            if k == "open":
                v = "open (calls can come in)" if v == "1" else "closed"
            elif v:
                v = "set (hidden)"
            rows.append([k, v])
    if not rows:
        return {"status": "info", "headline": "Nothing stored"} if "0 results" in raw else None
    return {"status": "info", "headline": f"{len(rows)} setting{'s' if len(rows) != 1 else ''} stored",
            "rows": rows, "note": "Tone values are hidden here -- Show full output has them"}

@_con_sum("iax_peers")
def _cs_iax_peers(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        tok = line.split()
        if len(tok) < 3 or tok[0] in ("Name/Username",) or re.match(r"^\d+ iax2 peers", line):
            continue
        sm = re.search(r"(OK \(\d+ ms\)|UNREACHABLE|LAGGED \(\d+ ms\)|Unmonitored|UNKNOWN)", line)
        if not sm:
            continue
        s = sm.group(1)
        st = "pass" if s.startswith("OK") else ("fail" if s == "UNREACHABLE" else "warn" if s.startswith("LAGGED") else "")
        host = tok[1] if tok[1] not in ("(Unspecified)", "(null)") else "dynamic"
        rows.append([tok[0], host, [s.replace("Unmonitored", "not checked"), st]])
    if not rows:
        return None
    bad = [r for r in rows if r[2][1] == "fail"]
    checked = any(r[2][1] == "pass" for r in rows)
    return {"status": "fail" if bad else ("warn" if any(r[2][1] == "warn" for r in rows) else ("pass" if checked else "info")),
            "headline": f"{len(rows)} peer{'s' if len(rows) != 1 else ''}" + (f", {len(bad)} unreachable" if bad else "")
                        + ("" if checked or bad else ", none checked"),
            "table": {"head": ["Name", "Address", "State"], "rows": rows}}

@_con_sum("iax_registry")
def _cs_iax_registry(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        tok = line.split()
        if len(tok) >= 5 and tok[0] != "Host" and re.match(r"^[\w.-]+:\d+$", tok[0]):
            state = tok[-1]
            rows.append([tok[0], tok[2] if len(tok) > 2 else "", [state, "pass" if state == "Registered" else "fail"]])
    if not rows:
        return {"status": "info", "headline": "No IAX2 sign-ins",
                "note": "Normal on ASL3 -- nodes register over HTTP (see Nodes · Registrations)"} \
            if re.search(r"\b0 IAX2 registrations", raw) or "Host" in raw else None
    bad = [r for r in rows if r[2][1] != "pass"]
    return {"status": "fail" if bad else "pass", "headline": "Registered" if not bad else f"{len(bad)} not registered",
            "table": {"head": ["Server", "User", "State"], "rows": rows}}

@_con_sum("iax_channels")
def _cs_iax_channels(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        tok = line.split()
        if tok and tok[0].startswith("IAX2/") and len(tok) >= 9:
            rows.append([tok[0], tok[1], tok[2], tok[5], tok[6], tok[8]])
    if not rows:
        return {"status": "info", "headline": "No IAX2 channels"} if re.search(r"\b0 active IAX", raw) else None
    return {"status": "info", "headline": f"{len(rows)} IAX2 channel{'s' if len(rows) != 1 else ''}",
            "table": {"head": ["Channel", "Address", "User", "Lag", "Jitter", "Codec"], "rows": rows},
            "note": "Asterisk cuts these columns short; All calls and Link quality show the full channel names"}

@_con_sum("iax_netstats")
def _cs_iax_netstats(raw: str, node: str):
    rows = []
    for line in raw.splitlines():
        tok = line.split()
        if not tok or not tok[0].startswith("IAX2/") or len(tok) < 15:
            continue
        try:
            rtt, ljit, lpct, rjit, rpct = int(tok[1]), int(tok[2]), int(tok[5]), int(tok[9]), int(tok[12])
        except ValueError:
            continue
        worst = max(lpct, rpct)
        st = "fail" if worst >= 10 or rtt > 800 else ("warn" if worst >= 3 or rtt > 300 else "pass")
        rows.append([tok[0], f"{rtt} ms", f"{lpct}% / {ljit} ms", f"{rpct}% / {rjit} ms",
                     [{"pass": "good", "warn": "watch", "fail": "poor"}[st], st]])
    if not rows:
        return {"status": "info", "headline": "No IAX2 links up"} if "Channel" in raw or not raw.strip() else None
    st = "fail" if any(r[4][1] == "fail" for r in rows) else ("warn" if any(r[4][1] == "warn" for r in rows) else "pass")
    return {"status": st, "headline": f"{len(rows)} link{'s' if len(rows) != 1 else ''}",
            "table": {"head": ["Channel", "Round trip", "Here: lost / jitter", "Far end: lost / jitter", "Quality"],
                      "rows": rows}}

@_con_sum("translation")
def _cs_translation(raw: str, node: str):
    lines = [ln for ln in raw.splitlines() if ln.strip()]
    hdr_i = next((i for i, ln in enumerate(lines) if re.match(r"^\s+(ulaw|slin|gsm|alaw)\b", ln) and len(ln.split()) > 3), None)
    if hdr_i is None:
        return None
    cols = lines[hdr_i].split()
    table = {}
    for ln in lines[hdr_i + 1:]:
        tok = ln.split()
        if len(tok) == len(cols) + 1:
            table[tok[0]] = dict(zip(cols, tok[1:]))
    rows = []
    for a, b in (("ulaw", "slin"), ("slin", "ulaw"), ("alaw", "slin"), ("slin", "alaw"), ("gsm", "slin"),
                 ("slin", "gsm"), ("g722", "slin16"), ("slin16", "g722"), ("opus", "slin48")):
        v = table.get(a, {}).get(b)
        if v and v != "-":
            rows.append([f"{a} → {b}", v])
    return {"status": "info", "headline": f"{len(table)} audio formats available",
            "table": {"head": ["Conversion", "Cost (µs per second of audio)"], "rows": rows},
            "note": "Lower is cheaper. ulaw is the lightest on a Pi; the radio side is always slin."}

_TS: list = []

_TS_BY: dict = {}

_TS_GROUPS = ("Links", "Bridges", "Phone", "Asterisk", "Pi health", "Network", "Dashboard", "Sysmon")

def _ts(group: str, tid: str, label: str, kind: str = ""):
    def deco(fn):
        _TS.append((group, tid, label, fn, kind))
        _TS_BY[tid] = (group, tid, label, fn, kind)
        return fn
    return deco

def _ts_cmd(argv: list, timeout: int = 8) -> "tuple[str, str]":
    if not shutil.which(argv[0]):
        return "", f"{argv[0]} is not installed on this Pi"
    try:
        r = subprocess.run(argv, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return "", f"{argv[0]} took longer than {timeout} s"
    except OSError as exc:
        return "", f"{argv[0]} could not run: {exc}"
    return (r.stdout or "") + (("\n" + r.stderr) if r.stderr and not r.stdout else ""), ""

def _ts_missing(cmd: str, why: str) -> dict:
    return {"cmd": cmd, "raw": why, "summary": {"status": "info", "headline": "Can't check this here", "note": why}}

def _ts_journal(unit: str, since: str, lines: int = 20000) -> "tuple[str, str]":
    return _ts_cmd(["journalctl", "-u", unit, "--since", since, "-n", str(lines), "--no-pager", "-o", "short-iso"], 15)

def _ts_ast_log(since_min: int = 60) -> "tuple[str, str, str]":
    out, prob = _ts_journal("asterisk", f"{since_min} minutes ago")
    if not prob and out.strip() and "-- No entries --" not in out:
        return out, f"journalctl -u asterisk --since '{since_min} minutes ago'", ""
    for f in ("/var/log/asterisk/messages.log", "/var/log/asterisk/messages", "/var/log/asterisk/full"):
        try:
            with open(f, "rb") as fh:
                fh.seek(0, 2)
                size = fh.tell()
                fh.seek(max(0, size - 2_000_000))
                txt = fh.read().decode("utf-8", "replace")
            cutoff = datetime.now() - timedelta(minutes=since_min)
            keep = []
            for ln in txt.splitlines():
                m = re.match(r"^\[(\w{3}\s+\d+\s+\d\d:\d\d:\d\d|\d{4}-\d\d-\d\d \d\d:\d\d:\d\d)", ln)
                if m:
                    try:
                        s = m.group(1)
                        ts = (datetime.strptime(s, "%Y-%m-%d %H:%M:%S") if "-" in s else
                              datetime.strptime(f"{datetime.now().year} {s}", "%Y %b %d %H:%M:%S"))
                        if ts < cutoff:
                            continue
                    except ValueError:
                        pass
                keep.append(ln)
            return "\n".join(keep), f"{f} (last {since_min} min)", ""
        except OSError:
            continue
    return "", "", prob or "No Asterisk log found (journal or /var/log/asterisk)"

def _ts_time(ln: str) -> str:
    m = re.search(r"(?<!\d)(\d\d:\d\d:\d\d)(?!\d)", ln)
    return m.group(1) if m else ""

def _ts_msg(ln: str) -> str:
    i = ln.rfind("]: ")
    if i >= 0:
        return ln[i + 3:]
    m = re.match(r"^\S+\s+\S+\s+[^:\s]+:\s(.*)$", ln)
    return m.group(1) if m else ln

_TS_DROP_RE = re.compile(r"(?i)(no link messages|forcing reconnect|one way audio|link .*(?:dropped|lost)|"
                         r"disconnect(?:ed|ing)?\b|reconnect(?:ing)?\b|retries exceeded|hung ?up)")

_TS_LINKEV_RE = re.compile(r"(?i)\b(connect(?:ed|ing)?|disconnect(?:ed|ing)?|established|reconnect(?:ed|ing)?|"
                           r"link (?:up|down)|hung ?up)\b")

_TS_NODE_RE = re.compile(r"(?<![\d.:])(\d{4,7})(?![\d.:])")

def _ts_rpt_sections() -> "dict[str, dict]":
    try:
        txt = _RPT_CONF.read_text(errors="replace")
    except OSError:
        return {}
    out, cur, in_block = {}, None, False
    for raw in txt.splitlines():
        bare = raw.strip()
        if in_block:
            if "--;" in bare:
                in_block = False
            continue
        if bare.startswith(";--"):
            in_block = "--;" not in bare[3:]
            continue
        ln = raw.split(";", 1)[0].strip()
        if not ln:
            continue
        m = re.match(r"^\[([^\]]+)\]\s*(?:\(([^)]*)\))?", ln)
        if m:
            cur = m.group(1).strip()
            out.setdefault(cur, {"__tmpl": (m.group(2) or "").strip()})
            continue
        if cur and "=" in ln:
            k, v = ln.split("=", 1)
            out[cur][k.strip().lower()] = v.strip()
    return out

def _ts_dns_servers() -> "tuple[list, str]":
    def read(f):
        try:
            return [ln.split()[1] for ln in Path(f).read_text(errors="replace").splitlines()
                    if ln.strip().startswith("nameserver") and len(ln.split()) > 1]
        except OSError:
            return None
    main = read("/etc/resolv.conf")
    if main is None:
        return [], "/etc/resolv.conf is missing"
    if main and all(s.startswith("127.0.0.53") for s in main):
        real = read("/run/systemd/resolve/resolv.conf")
        if real is not None:
            return real, "/run/systemd/resolve/resolv.conf (via systemd-resolved)"
    return main, "/etc/resolv.conf"

def _ts_ipv6_off() -> bool:
    try:
        if Path("/proc/sys/net/ipv6/conf/all/disable_ipv6").read_text().strip() == "1":
            return True
    except OSError:
        pass
    return not Path("/proc/net/if_inet6").exists()

def _ts_net_basics() -> dict:
    raw, inet = [], None
    ping_row = ["Internet by IP", "ping 8.8.8.8 / 1.1.1.1", ["ping is not installed", "info"]]
    if shutil.which("ping"):
        inet = False
        for ip in ("8.8.8.8", "1.1.1.1"):
            out, prob = _ts_cmd(["ping", "-n", "-c", "2", "-W", "2", ip], 8)
            m = re.search(r"(\d+)\s+(?:packets\s+)?received", out)
            got = int(m.group(1)) if m else 0
            raw.append(f"$ ping -c 2 {ip}: " + (f"{got} of 2 replies" if m else (prob or "no answer")))
            if got:
                inet = True
                ping_row = ["Internet by IP", f"ping {ip}", [f"{got} of 2 replies", "pass"]]
                break
        if not inet:
            ping_row = ["Internet by IP", "ping 8.8.8.8 / 1.1.1.1", ["no replies -- no route to the internet", "fail"]]
    servers, where = _ts_dns_servers()
    v6off = _ts_ipv6_off()
    raw.append(f"DNS servers ({where}): {', '.join(servers) or 'none'}" + ("  [IPv6 is off]" if v6off else ""))
    v4 = [s for s in servers if ":" not in s]
    if not servers:
        dns_row = ["DNS servers", where, ["none set -- the Pi can't look up any name", "fail"]]
    elif v6off and not v4:
        dns_row = ["DNS servers", where, [", ".join(servers) + " -- IPv6 only, but IPv6 is off", "fail"]]
    else:
        txt = ", ".join(servers[:4]) + (" (IPv6 ones unused, IPv6 is off)" if v6off and len(v4) < len(servers) else "")
        dns_row = ["DNS servers", where, [txt, "pass"]]
    return {"ping": ping_row, "dns": dns_row, "inet": inet, "servers": servers, "v6off": v6off,
            "dns_ok": dns_row[2][1] == "pass", "raw": raw}

_TS_RANK = {"fail": 0, "warn": 1, "pass": 2, "info": 3}

def _ts_worst(statuses: list) -> str:
    st = [s for s in statuses if s in _TS_RANK]
    if not st:
        return "info"
    return min(st, key=lambda s: _TS_RANK[s])

_DPX_INC_RE = re.compile(r'^#\s*(try)?include\s+"?([^"\s>]+)"?', re.I)

_DPX_SEC_RE = re.compile(r"^\[([^\]]+)\]\s*(?:\(([^)]*)\))?\s*$")

_DPX_KV_RE = re.compile(r"^([A-Za-z_][\w\-]*)\s*=>?\s*(.*)$")

_DPX_PRIO_RE = re.compile(r"^(\d+|n|next|s|same|hint|[A-Za-z_]\w*[+-]\d+)(\(([^)]*)\))?$", re.I)

_DPX_APP_RE = re.compile(r"^([A-Za-z_]\w*)\s*(.*)$", re.S)

_DPX_MAX_FILES = 30

def _dpx_strip(line: str) -> str:
    out, i = [], 0
    while i < len(line):
        c = line[i]
        if c == "\\" and i + 1 < len(line):
            out.append(line[i:i + 2])
            i += 2
            continue
        if c == ";":
            break
        out.append(c)
        i += 1
    return "".join(out).strip()

def _dpx_split(s: str, sep: str = ",") -> list:
    parts, depth, cur, i = [], 0, [], 0
    while i < len(s):
        c = s[i]
        if c == "\\" and i + 1 < len(s):
            cur.append(s[i:i + 2])
            i += 2
            continue
        if c in "({[":
            depth += 1
        elif c in ")}]":
            depth = max(0, depth - 1)
        if c == sep and depth == 0:
            parts.append("".join(cur).strip())
            cur = []
        else:
            cur.append(c)
        i += 1
    parts.append("".join(cur).strip())
    return parts

def _dpx_scan(ast_dir=None) -> dict:
    base = Path(ast_dir or _AST_DIR)
    res = {"stmts": [], "files": [], "missing": [], "errors": [], "base": base}
    state = {"ctx": None, "managed": False}

    def read(fname: str, depth: int, from_where: str, optional: bool, managed: bool):
        if depth > 4 or len(res["files"]) >= _DPX_MAX_FILES:
            return
        if ".." in fname or not re.fullmatch(r"[\w.\-/]+", fname):
            res["errors"].append(f"{from_where}: include name {fname!r} skipped")
            return
        path = Path(fname) if fname.startswith("/") else base / fname
        try:
            if path.stat().st_size > _PH_MAX_BYTES:
                res["errors"].append(f"{fname}: too large to read")
                return
            text = path.read_text(errors="replace")
        except FileNotFoundError:
            res["missing"].append({"file": fname, "where": from_where, "optional": optional})
            return
        except OSError as e:
            res["errors"].append(f"{fname}: {e}")
            return
        if fname in res["files"]:
            return
        res["files"].append(fname)
        whole = managed or fname.startswith("dvs_phone_") or Path(fname).name.startswith("dvs_phone_")
        in_block = in_cmt = False
        for n, raw in enumerate(text.splitlines(), 1):
            s = raw.strip()
            if in_cmt:
                if "--;" in s:
                    in_cmt = False
                continue
            if s.startswith(_PH_BEGIN):
                in_block = True
                continue
            if s.startswith(_PH_END):
                in_block = False
                continue
            if s.startswith(";--"):
                in_cmt = "--;" not in s[3:]
                continue
            m = _DPX_INC_RE.match(s)
            if m:
                read(m.group(2), depth + 1, f"{fname}:{n}", bool(m.group(1)), whole or in_block)
                continue
            line = _dpx_strip(s)
            if not line:
                continue
            st = {"file": fname, "line": n, "ctx": state["ctx"], "managed": whole or in_block, "text": line}
            if line.startswith("#"):
                st["kind"] = "directive"
            elif line.startswith("["):
                sm = _DPX_SEC_RE.match(line)
                if not sm:
                    st["kind"] = "bad"
                    st["why"] = "section line Asterisk can't read (missing ']'?)"
                else:
                    opts = [o.strip() for o in (sm.group(2) or "").split(",") if o.strip()]
                    state["ctx"] = sm.group(1).strip()
                    st.update(kind="section", ctx=state["ctx"], plus="+" in opts, template="!" in opts)
            else:
                km = _DPX_KV_RE.match(line)
                if not km:
                    st["kind"] = "bad"
                    st["why"] = "line Asterisk can't read (no => or =)"
                else:
                    st.update(kind="kv", key=km.group(1).lower(), value=km.group(2).strip())
            res["stmts"].append(st)

    read("extensions.conf", 0, "", False, False)
    return res

def _dpx_model(scan: dict) -> dict:
    ctxs: dict = {}
    issues: list = []
    glb: dict = {}
    steps: list = []
    includes: list = []
    last_ext, last_pri, cur = None, None, None
    for st in scan["stmts"]:
        if st["kind"] == "section":
            cur = st["ctx"]
            last_ext, last_pri = None, None
            if st.get("template"):
                continue
            c = ctxs.setdefault(cur, {"places": [], "exts": {}, "plus": []})
            (c["plus"] if st.get("plus") else c["places"]).append(st)
            continue
        if st["kind"] == "bad":
            issues.append((st, st["why"], "fail"))
            continue
        if st["kind"] != "kv" or cur is None:
            continue
        key, val = st["key"], st["value"]
        if cur.lower() == "globals":
            glb[key if key.isupper() else st["text"].split("=")[0].strip()] = val
            continue
        if cur.lower() == "general":
            continue
        if key == "include":
            includes.append((st, val.split(",")[0].strip()))
            continue
        if key not in ("exten", "same"):
            continue
        if key == "exten":
            parts = val.split(",", 2)
            if len(parts) < 3:
                issues.append((st, "no priority or no app -- Asterisk ignores this line", "fail"))
                continue
            ext, prio, rest = (p.strip() for p in parts)
        else:
            parts = val.split(",", 1)
            if last_ext is None:
                issues.append((st, "'same =>' with no exten line above it -- Asterisk ignores it", "fail"))
                continue
            if len(parts) < 2:
                issues.append((st, "no priority or no app -- Asterisk ignores this line", "fail"))
                continue
            ext, prio, rest = last_ext, parts[0].strip(), parts[1].strip()
        if "(" in prio and ")" not in prio:
            issues.append((st, f"label missing its ')' in '{prio}' -- is the priority number missing?", "fail"))
            continue
        pm = _DPX_PRIO_RE.match(prio)
        if not pm:
            issues.append((st, f"bad priority '{prio}'", "fail"))
            continue
        word, label = pm.group(1).lower(), (pm.group(3) or "").strip()
        if word == "hint":
            last_ext = ext
            continue
        if word in ("n", "next", "s", "same"):
            if last_pri is None:
                issues.append((st, f"'{word}' on the first line of [{cur}] -- there is no step before it", "fail"))
                continue
            ipri = last_pri + 1 if word in ("n", "next") else last_pri
        elif word.isdigit():
            ipri = int(word)
        else:
            ipri = None
        am = _DPX_APP_RE.match(rest)
        tail = am.group(2).strip() if am else ""
        if not rest or not am or (tail and tail[0] not in "(,"):
            issues.append((st, "no app name" if not rest else f"can't read the app in '{rest[:40]}'", "fail"))
            continue
        app = am.group(1)
        if tail.startswith("("):
            args = tail[1:-1] if tail.endswith(")") else tail[1:]
        else:
            args = tail[1:]
        last_ext = ext
        if ipri is not None:
            last_pri = ipri
        e = ctxs[cur]["exts"].setdefault(ext, {"prios": {}, "labels": {}, "first": st})
        if ipri is not None:
            if ipri in e["prios"]:
                o = e["prios"][ipri]
                issues.append((st, f"'{ext}' priority {ipri} is already used at {o['file']}:{o['line']} "
                                   "-- Asterisk keeps the first", "warn"))
            else:
                e["prios"][ipri] = st
        if label:
            if label in e["labels"]:
                o = e["labels"][label]
                issues.append((st, f"label '{label}' is already used at {o['file']}:{o['line']}", "warn"))
            else:
                e["labels"][label] = st
        steps.append({"stmt": st, "ctx": cur, "ext": ext, "prio": ipri, "label": label, "app": app, "args": args})
    return {"ctxs": ctxs, "issues": issues, "globals": glb, "steps": steps, "includes": includes}

def _dpx_glb_expand(s: str, glb: dict) -> str:
    return re.sub(r"\$\{(\w+)\}", lambda m: glb.get(m.group(1), m.group(0)), s)

def _dpx_ext_match(model: dict, ctx: str, ext: str) -> list:
    out = []
    for pat in model["ctxs"].get(ctx, {}).get("exts", {}):
        p = _dpx_glb_expand(pat, model["globals"]).split("/")[0]
        if p == ext or (p.startswith("_") and _ph_pat_match(p, ext)):
            out.append(pat)
    return out

def _dpx_jumps(step: dict) -> list:
    app, args = step["app"].lower(), step["args"]
    out = []

    def goto_style(spec: str, sub: bool):
        p = _dpx_split(spec)
        if sub and p and "(" in p[-1]:
            p[-1] = p[-1].split("(")[0]
        p = [x.strip() for x in p]
        if len(p) == 1 and p[0]:
            out.append(("", "", p[0]))
        elif len(p) == 2:
            out.append(("", p[0], p[1]))
        elif len(p) >= 3:
            out.append((p[0], p[1], p[2]))

    if app in ("goto", "gosub"):
        goto_style(args, app == "gosub")
    elif app in ("gotoif", "gosubif"):
        halves = _dpx_split(args, "?")
        if len(halves) >= 2:
            for br in _dpx_split("?".join(halves[1:]), ":")[:2]:
                if br.strip():
                    goto_style(br.strip(), app == "gosubif")
    elif app == "dial":
        for ext, ctx in re.findall(r"Local/([^@/,&)\s]+)@([\w\-]+)", args):
            out.append((ctx, ext, "1"))
    return out

def _dpx_conf_refs(ctx: dict) -> list:
    refs = []
    for top in ("echolink.conf", "sip.conf"):
        if top not in ctx["conf"]:
            ctx["conf"][top] = []
            _ph_parse_file(ctx, top, top, {"sec": None}, 0, False)
    for top, what in (("pjsip.conf", "SIP account"), ("iax.conf", "IAX2 account"),
                      ("echolink.conf", "EchoLink"), ("sip.conf", "chan_sip account")):
        for s in ctx["conf"].get(top, []):
            if s["is_template"]:
                continue
            kv = {k.strip().lower(): (v.strip(), n) for k, v, n, _m in s["kv"]}
            if top == "pjsip.conf" and kv.get("type", ("", 0))[0].lower() != "endpoint":
                continue
            if "context" in kv:
                v, n = kv["context"]
                refs.append((s["file"], n, s["name"] or "(top)", v.split()[0] if v else "",
                             what + (" default" if s["name"].lower() == "general" else "")))
    secs = ctx["conf"]["rpt.conf"]
    for name in dict.fromkeys(s["name"] for s in secs if s["name"].isdigit() and not s["is_template"]):
        kv, _m, _f = _ph_resolve(secs, name)
        lists = [kv[k].split()[0] for k in ("functions", "phone_functions", "link_functions") if kv.get(k)]
        for st_name in dict.fromkeys(lists or ["functions"]):
            table, _m2, _f2 = _ph_resolve(secs, st_name)
            hit = next(((c, v) for c, v in sorted(table.items()) if v.strip().lower().startswith("autopatchup")), None)
            if not hit:
                continue
            opts = _ph_parse_autopatch(hit[1])
            cname = opts.get("context") or (kv.get("context", "").split()[0] if kv.get("context") else "") or "radio"
            how = ("autopatch line" if opts.get("context") else "node's context=" if kv.get("context")
                   else "default -- no context= set")
            holder = next(((s["file"], n) for s in reversed(secs) for k, v, n, _x in s["kv"]
                           if k.strip() == hit[0] and v.strip() == hit[1].strip()), ("rpt.conf", 0))
            refs.append((holder[0], holder[1], f"{name} *{hit[0]}", cname, f"autopatch ({how})"))
            break
    return refs

def _ts_iax_port() -> int:
    try:
        p_ = int(str(_dvsm_read_iax_conf().get("bindport", "4569")).strip() or 4569)
        return p_ if 1 <= p_ <= 65535 else 4569
    except (ValueError, TypeError):
        return 4569

def _ts_dash_paths():
    yield from ("/opt/asl_dvs/asl_dvs_dashboard.py", "/usr/local/bin/asl_dvs_dashboard.py",
                "/opt/asl_dvs_dashboard/asl_dvs_dashboard.py")
    try:
        out = _run(["systemctl", "show", "-p", "ExecStart", "--value", "asl_dvs_dashboard"], timeout=4)
    except OSError:
        return
    m = re.search(r"(/\S+\.py)", out or "")
    if m:
        yield m.group(1)

def _ts_dash_version_of(head: str) -> str:
    m = re.search(r'VERSION\s*=\s*"([\d.]+)"', head) or re.search(r"asl_dvs_dashboard\.py\s+\S+\s+v([\d.]+)", head)
    return m.group(1) if m else ""

def _ts_dash_version() -> str:
    for f in _ts_dash_paths():
        try:
            with open(f, encoding="utf-8", errors="replace") as fh:
                v = _ts_dash_version_of(fh.read(4000))
        except OSError:
            continue
        if v:
            return v
    return ""

def _route_console_tcatalog(h: "Handler") -> None:
    groups = {g: [] for g in _TS_GROUPS}
    for g, tid, label, _fn, kind in _TS:
        groups.setdefault(g, []).append({"id": tid, "label": label, "kind": kind})
    h.send_json({"ok": True, "groups": [{"name": g, "checks": c} for g, c in groups.items() if c],
                 "order": [x[1] for x in _TS if not x[4]], "host": get_hostname(),
                 "sysmon": VERSION, "dashboard": _ts_dash_version()})

def _route_console_trun(h: "Handler", data: dict) -> None:
    if os.geteuid() != 0:
        h.send_json({"ok": False, "message": "sysmon is not running as root"}, 403)
        return
    tid = str(data.get("id", ""))
    c = _TS_BY.get(tid)
    if c is None:
        h.send_json({"ok": False, "message": "Unknown check"}, 400)
        return
    group, _tid, label, fn, kind = c
    if kind == "act" and data.get("confirm") is not True:
        h.send_json({"ok": False, "message": "This needs confirming first"}, 400)
        return
    try:
        res = fn()
    except Exception as exc:
        _log(f"troubleshoot: {tid} failed: {exc}")
        res = {"cmd": label, "raw": f"Check failed: {exc}", "summary": {"status": "info", "headline": "Check failed",
                                                                      "note": str(exc)}}
    if kind == "act":
        _log(f"troubleshoot: action '{label}' run from {h._client_ip()}")
    h.send_json({"ok": True, "id": tid, "group": group, "title": label, "cmd": res.get("cmd", ""),
                 "raw": res.get("raw", ""), "summary": res.get("summary"),
                 "time": datetime.now().strftime("%H:%M:%S")})

def _route_console_catalog(h: "Handler") -> None:
    groups: dict = {}
    for g, bid, label, cmd, kind in _CON_BTNS:
        groups.setdefault(g, []).append({"id": bid, "label": label, "kind": kind,
                                         "needs_node": "{node}" in cmd})
    h.send_json({"ok": True, "groups": [{"name": g, "buttons": b} for g, b in groups.items()],
                 "nodes": _con_nodes(), "debug_sec": _CON_DEBUG_SEC})

def _route_console_run(h: "Handler", data: dict) -> None:
    if os.geteuid() != 0:
        h.send_json({"ok": False, "message": "sysmon is not running as root"}, 403)
        return
    bid = str(data.get("id", ""))
    b = _CON_BTN.get(bid)
    if b is None:
        h.send_json({"ok": False, "message": "Unknown button"}, 400)
        return
    group, _bid, label, tmpl, kind = b
    node = str(data.get("node", "")).strip()
    if "{node}" in tmpl:
        if node not in _con_nodes():
            h.send_json({"ok": False, "message": "Pick a node from the list"}, 400)
            return
    cmd = tmpl.replace("{node}", node)
    if "{sip_host}" in cmd:
        host = _con_sip_host()
        if not host:
            h.send_json({"ok": False, "message": "No phone network server found"}, 409)
            return
        cmd = cmd.replace("{sip_host}", host)
    if kind == "act" and data.get("confirm") is not True:
        h.send_json({"ok": False, "message": "This needs confirming first"}, 400)
        return
    if kind == "sys":
        try:
            cmd, raw, summary = _CON_SYS[tmpl]()
        except Exception as exc:
            _log(f"console: {bid} failed: {exc}")
            h.send_json({"ok": False, "message": f"{label} failed: {exc}"}, 500)
            return
        h.send_json({"ok": True, "id": bid, "group": group, "title": label, "cmd": cmd, "raw": raw,
                     "summary": summary, "time": datetime.now().strftime("%H:%M:%S")})
        return
    if not _ph_ast_running():
        h.send_json({"ok": False, "message": "Asterisk is not running"}, 409)
        return
    if kind == "live":
        with _CON_LOCK:
            live = _CON_ACTIVE["open"]
        if not live:
            h.send_json({"ok": False, "message": "Open the live console first -- debug output only shows there"}, 409)
            return
    raw = _ph_cli(cmd, timeout=10)
    if bid == "rtp_on":
        _CON_DEBUG["rtp"] = True
        _con_debug_arm()
    elif bid in ("sip_log_on", "sip_log_host"):
        _CON_DEBUG["sip"] = True
        _con_debug_arm()
    elif bid == "sip_reregister":
        time.sleep(4)
        regs = _ph_cli("pjsip show registrations", timeout=8)
        raw = (raw.rstrip() + "\n\n" if raw.strip() else "") + "$ pjsip show registrations\n" + regs
    elif bid == "rtp_off":
        _CON_DEBUG["rtp"] = False
    elif bid == "sip_log_off":
        _CON_DEBUG["sip"] = False
    if kind == "act":
        _log(f"console: button '{label}' ({cmd}) run from {h._client_ip()}")
    try:
        summary = _con_summary("sip_regs" if bid == "sip_reregister" else bid, raw, node)
    except Exception as exc:
        _log(f"console: summary for {bid} failed: {exc}")
        summary = None
    h.send_json({"ok": True, "id": bid, "group": group, "title": label + (f" · {node}" if node and "{node}" in tmpl else "")
                 + (f" · {cmd.rsplit(' ', 1)[-1]}" if "{sip_host}" in tmpl else ""),
                 "cmd": cmd, "raw": _ph_mask(raw) if bid == "phone_db" else raw, "summary": summary,
                 "time": datetime.now().strftime("%H:%M:%S")})

def _route_console_status(h: "Handler") -> None:
    h.send_json(_con_status(h._client_ip(), h.headers))

def _route_console_ws(h: "Handler") -> None:
    def refuse(code: int, msg: str) -> None:
        h.send_json({"ok": False, "message": msg}, code)
    ip = h._client_ip()
    enabled, why = _con_enabled()
    if not enabled:
        refuse(403, why)
        return
    client_ok, cwhy = _con_client_ok(ip, h.headers)
    if not client_ok:
        refuse(403, cwhy)
        return
    origin = h.headers.get("Origin", "")
    host = h.headers.get("Host", "")
    o = urlparse(origin)
    if not origin or o.scheme not in ("http", "https") or not host or o.netloc.lower() != host.lower():
        _log(f"console: refused WebSocket from {ip} -- Origin {origin!r} does not match Host {host!r}")
        refuse(403, "Refused: the request did not come from this page.")
        return
    key = h.headers.get("Sec-WebSocket-Key", "")
    if (h.headers.get("Upgrade", "").lower() != "websocket"
            or "upgrade" not in h.headers.get("Connection", "").lower()
            or h.headers.get("Sec-WebSocket-Version", "") != "13" or not key):
        refuse(400, "Not a WebSocket request.")
        return
    token = h._session_token()
    ticket = parse_qs(urlparse(h.path).query).get("ticket", [""])[0]
    if not _con_take_ticket(ticket, token):
        refuse(403, "Console ticket missing, used or expired -- re-enter the root password.")
        return
    if not _con_claim():
        refuse(409, "A console is already open (one at a time).")
        return
    try:
        h.close_connection = True
        h.connection.settimeout(None)
        h.protocol_version = "HTTP/1.1"
        h.send_response(101, "Switching Protocols")
        h.send_header("Upgrade", "websocket")
        h.send_header("Connection", "Upgrade")
        h.send_header("Sec-WebSocket-Accept", _ws_accept_key(key))
        h.end_headers()
        h.wfile.flush()
        _con_session(h.connection, lambda: _check_session(token), ip, on_close=_con_cleanup)
    except (BrokenPipeError, ConnectionResetError, OSError):
        pass
    finally:
        _con_release()

def _con_password_ok(h: "Handler", data: dict, what: str) -> bool:
    ip = h._client_ip()
    locked_until = _login_is_locked(ip)
    if locked_until is not None:
        h.send_json({"ok": False, "message": f"Too many failed attempts -- try again in "
                                             f"{max(0, int(locked_until - time.time()))}s"}, 429)
        return False
    if not _verify_root_password(str(data.get("password", ""))):
        _login_record_failure(ip)
        _log(f"console: wrong root password from {ip} ({what})", stderr=True)
        h.send_json({"ok": False, "message": "Wrong root password."}, 403)
        return False
    _login_record_success(ip)
    return True

def _route_console_enable(h: "Handler", data: dict) -> None:
    ip = h._client_ip()
    ok, why = _con_client_ok(ip, h.headers)
    if not ok:
        h.send_json({"ok": False, "message": why}, 403)
        return
    if os.geteuid() != 0:
        h.send_json({"ok": False, "message": "sysmon is not running as root"}, 403)
        return
    if not _con_password_ok(h, data, "switching the console on"):
        return
    ok, msg = _con_switch(True, ip)
    h.send_json({"ok": ok, "message": msg}, 200 if ok else 500)

def _route_console_disable(h: "Handler", data: dict) -> None:
    ok, msg = _con_switch(False, h._client_ip())
    h.send_json({"ok": ok, "message": msg}, 200 if ok else 500)

def _route_console_open(h: "Handler", data: dict) -> None:
    ip = h._client_ip()
    enabled, why = _con_enabled()
    if not enabled:
        h.send_json({"ok": False, "message": why}, 403)
        return
    ok, cwhy = _con_client_ok(ip, h.headers)
    if not ok:
        h.send_json({"ok": False, "message": cwhy}, 403)
        return
    if not _con_password_ok(h, data, "opening the console"):
        return
    with _CON_LOCK:
        busy = _CON_ACTIVE["open"]
    if busy:
        h.send_json({"ok": False, "message": "A console is already open (one at a time). Close it first."}, 409)
        return
    if not _ph_ast_running():
        h.send_json({"ok": False, "message": "Asterisk is not running, so there is no console to open."}, 409)
        return
    h.send_json({"ok": True, "ticket": _con_issue_ticket(h._session_token())})

