_CON_ASSETS: dict = {}

def _con_asset(name: str):
    if name not in _CON_ASSETS_B64:
        return None
    if name not in _CON_ASSETS:
        ctype, sha, b64 = _CON_ASSETS_B64[name]
        raw = gzip.decompress(base64.b64decode("".join(b64.split())))
        if hashlib.sha256(raw).hexdigest() != sha:
            _log(f"console: embedded {name} failed its checksum -- not served", stderr=True)
            return None
        _CON_ASSETS[name] = (ctype + "; charset=utf-8", raw)
    return _CON_ASSETS[name]

def _route_console_static(h: "Handler") -> None:
    name = urlparse(h.path).path.rsplit("/", 1)[-1]
    asset = _con_asset(name)
    if asset is None:
        h.send_response(404)
        h.end_headers()
        return
    ctype, raw = asset
    h.send_response(200)
    h.send_header("Content-Type", ctype)
    h.send_header("Cache-Control", "private, max-age=86400")
    h.send_header("X-Content-Type-Options", "nosniff")
    if h._accepts_gzip():
        body = gzip.compress(raw, compresslevel=6)
        h.send_header("Content-Encoding", "gzip")
    else:
        body = raw
    h.send_header("Content-Length", str(len(body)))
    h.end_headers()
    h.wfile.write(body)

@_ts("Links", "ts_drops", "Why did a link drop?")
def _ts_drops():
    txt, where, prob = _ts_ast_log(60)
    if prob:
        return _ts_missing("Asterisk log, last hour", prob)
    rows = []
    for ln in txt.splitlines():
        m = _TS_DROP_RE.search(ln)
        if not m or "pjsip" in ln.lower() or "sip/" in ln.lower():
            continue
        msg = re.sub(r"^\S+\.c:\d+\s+", "", _ts_msg(ln))
        node = next((x for x in _TS_NODE_RE.findall(msg) if x not in ("4569", "5060")), "")
        rows.append([_ts_time(ln), node, m.group(1).lower(), msg[-110:]])
    rows = rows[-25:]
    if not rows:
        return {"cmd": where, "raw": txt[-4000:], "summary": {"status": "pass", "headline": "No link drops in the last hour"}}
    nodes = sorted({r[1] for r in rows if r[1]})
    return {"cmd": where, "raw": "\n".join(r[3] for r in rows),
            "summary": {"status": "warn", "headline": f"{len(rows)} drop / reconnect line{'s' if len(rows) != 1 else ''}"
                                                       + (f" · nodes {', '.join(nodes)}" if nodes else ""),
                        "table": {"head": ["Time", "Node", "What", "Log line"], "rows": rows[::-1]},
                        "note": "\"No link messages ... forcing reconnect\" means link keep-alives stopped -- "
                                "usually the internet or WiFi dropped for a moment"}}

@_ts("Links", "ts_history", "Link history")
def _ts_history():
    txt, where, prob = _ts_ast_log(24 * 60)
    if prob:
        return _ts_missing("Asterisk log, last 24 hours", prob)
    rows = []
    for ln in txt.splitlines():
        m = _TS_LINKEV_RE.search(ln)
        if not m or "pjsip" in ln.lower():
            continue
        msg = re.sub(r"^\S+\.c:\d+\s+", "", _ts_msg(ln))
        nodes = [x for x in _TS_NODE_RE.findall(msg) if x not in ("4569", "5060")]
        if not nodes:
            continue
        ev = m.group(1).lower()
        kind = "down" if ("dis" in ev or "down" in ev or "hung" in ev) else ("again" if "reconnect" in ev else "up")
        rows.append([_ts_time(ln), ", ".join(dict.fromkeys(nodes))[:40],
                     [ev, {"down": "warn", "again": "warn", "up": "pass"}[kind]]])
    if not rows:
        return {"cmd": where, "raw": "", "summary": {"status": "info", "headline": "No link events in the last 24 hours",
                                                     "note": "Asterisk may log link changes only at higher verbose levels"}}
    downs = sum(1 for r in rows if r[2][1] == "warn")
    return {"cmd": where, "raw": "", "summary": {
        "status": "warn" if downs >= 10 else "info",
        "headline": f"{len(rows)} link events in 24 h · {downs} down / reconnect",
        "table": {"head": ["Time", "Node(s)", "Event"], "rows": rows[::-1][:40]},
        "note": "Many downs in a row for the same node is the bounce pattern -- run Why did a link drop?" if downs >= 10 else ""}}

@_ts("Links", "ts_stuck", "Stuck link check")
def _ts_stuck():
    if not _ph_ast_running():
        return _ts_missing("rpt lstats / rpt xnode", "Asterisk is not running")
    rows, raw, bad = [], [], 0
    for node in _con_nodes():
        ls = _ph_cli(f"rpt lstats {node}", timeout=8)
        xn = _ph_cli(f"rpt xnode {node}", timeout=8)
        raw += [f"$ rpt lstats {node}", ls.strip(), f"$ rpt xnode {node}", xn.strip()[:1500], ""]
        a = {ln.split()[0] for ln in ls.splitlines()
             if len(ln.split()) >= 6 and ln.split()[3] in ("IN", "OUT")}
        b = {n for n, _m, _k in _con_alinks(_con_vars(xn).get("RPT_ALINKS", ""))}
        if not a and not b:
            continue
        only_a, only_b = sorted(a - b), sorted(b - a)
        if only_a or only_b:
            bad += 1
            note = "; ".join(x for x in (f"in lstats only: {', '.join(only_a)}" if only_a else "",
                                         f"in link list only: {', '.join(only_b)}" if only_b else "") if x)
            rows.append([node, ", ".join(sorted(a | b)), [note, "warn"]])
        else:
            rows.append([node, ", ".join(sorted(a)), ["match", "pass"]])
    if not rows:
        return {"cmd": "rpt lstats + rpt xnode (each node)", "raw": "\n".join(raw),
                "summary": {"status": "info", "headline": "No links on any node"}}
    return {"cmd": "rpt lstats + rpt xnode (each node)", "raw": "\n".join(raw), "summary": {
        "status": "warn" if bad else "pass",
        "headline": "No stuck links" if not bad else f"{bad} node{'s' if bad != 1 else ''} disagree",
        "table": {"head": ["Node", "Links", "Check"], "rows": rows},
        "note": "A link listed one way but not the other is a phantom link; if it won't clear, restart Asterisk" if bad else ""}}

@_ts("Links", "ts_tot", "Time-out hits")
def _ts_tot():
    if not _ph_ast_running():
        return _ts_missing("rpt stats", "Asterisk is not running")
    rows, raw, hits, offs = [], [], 0, []
    for node in _con_nodes():
        out = _ph_cli(f"rpt stats {node}", timeout=8)
        raw += [f"$ rpt stats {node}", out.strip(), ""]
        kv = _con_dots(out)
        n = kv.get("Time outs since system initialization", "")
        try:
            k = int(n)
        except ValueError:
            k = 0
        hits += k
        xm = re.search(r"\btot_ena\s*=\s*(\d)", _ph_cli(f"rpt xnode {node}", timeout=8))
        ena = None if not xm else xm.group(1) == "1"
        if ena is False:
            offs.append(node)
        rows.append([node, ["on" if ena else ("off" if ena is False else "?"), "pass" if ena else ("warn" if ena is False else "")],
                     [n or "?", ("warn" if k else "pass") if n else ""], kv.get("Time out timer state", "").lower(), kv.get("TX time today", "")])
    txt, _where, _prob = _ts_ast_log(24 * 60)
    times = [_ts_time(ln) for ln in txt.splitlines() if re.search(r"(?i)\btime ?out timer\b|\bTIMEOUT\b", ln)
             and "sip" not in ln.lower()][-10:]
    if not rows:
        return {"cmd": "rpt stats (each node)", "raw": "\n".join(raw), "summary": {
            "status": "info", "headline": "No nodes to check", "note": "No local nodes were found to ask"}}
    notes = []
    if offs:
        notes.append(f"The time-out timer is OFF on {', '.join(offs)}. Dashboard v9.3.28+ turns it off only while its "
                     "Phone tab is open and back on when you leave; if the Phone tab isn't open, it should come back on "
                     "within a minute")
    return {"cmd": "rpt stats + rpt xnode (each node) + log", "raw": "\n".join(raw), "summary": {
        "status": "warn" if (hits or offs) else "pass",
        "headline": ((f"Time-out timer off on {', '.join(offs)} · " if offs else "")
                     + ("No time-outs since Asterisk started" if not hits else f"{hits} time-out{'s' if hits != 1 else ''} since Asterisk started")),
        "table": {"head": ["Node", "Timer", "Time-outs", "Timer state", "Transmit time today"], "rows": rows},
        "rows": [["Seen in the log at", ", ".join(times)]] if times else [],
        "note": " ".join(notes + (["A time-out cuts the transmitter after its limit (often 3 minutes). On phone calls, pauses "
                                    "let it reset; or raise totime for that node in rpt.conf"] if hits else []))}}

@_ts("Links", "ts_localnodes", "Local node entries")
def _ts_localnodes():
    iaxp = _ts_iax_port()
    try:
        txt = _RPT_CONF.read_text(errors="replace")
    except OSError as exc:
        return _ts_missing(str(_RPT_CONF), str(exc))
    rows, bad, sec = [], 0, ""
    for raw in txt.splitlines():
        ln = raw.split(";", 1)[0].strip()
        m = re.match(r"^\[([^\]]+)\]", ln)
        if m:
            sec = m.group(1).strip().lower()
            continue
        if sec != "nodes" or "=" not in ln:
            continue
        k, v = (x.strip() for x in ln.split("=", 1))
        mm = re.match(r"^(\w+)@(127\.0\.0\.1|localhost)(?::(\d+))?/(\S+?)(,.*)?$", v)
        if not mm:
            continue
        port = int(mm.group(3) or 4569)
        if port == iaxp:
            rows.append([k, v, ["ok", "pass"]])
        else:
            bad += 1
            fixed = f"{mm.group(1)}@{mm.group(2)}" + (f":{iaxp}" if iaxp != 4569 else "") + f"/{mm.group(4)}{mm.group(5) or ''}"
            rows.append([k, v, [f"uses {port}, Asterisk listens on {iaxp} -- should be: {k} = {fixed}", "fail"]])
    if not rows:
        return {"cmd": "rpt.conf [nodes]", "raw": "", "summary": {"status": "info", "headline": "No local node entries in [nodes]"}}
    return {"cmd": f"rpt.conf [nodes] vs iax.conf bindport ({iaxp})", "raw": "", "summary": {
        "status": "fail" if bad else "pass",
        "headline": f"All local entries use port {iaxp}" if not bad else f"{bad} entr{'ies' if bad != 1 else 'y'} on the wrong port",
        "table": {"head": ["Node", "Entry", "Check"], "rows": rows},
        "note": "A wrong port leaves links between nodes on this Pi stuck in CONNECTING. Lines inside the dashboard's "
                "own block are fixed by dashboard v9.3.27+ on Save Phone" if bad else ""}}

_TS_TPL_READ_KEYS = ("callsign", "idrecording", "idtalkover", "rxchannel", "statpost_url",
                     "propagate_dtmf", "propagate_phonedtmf", "remote_dtmf_allowed", "phonesendlinks")

@_ts("Links", "ts_tplvals", "Template values")
def _ts_tplvals():
    try:
        txt = _RPT_CONF.read_text(errors="replace")
    except OSError as exc:
        return _ts_missing(str(_RPT_CONF), str(exc))
    scan = _rpt_scan_full(txt)
    rows, raw, flagged = [], [], 0
    for node in sorted(scan["nodes"], key=int):
        kv, org = scan["nodes"][node], scan["origins"].get(node, {})
        for key in sorted(kv):
            src = org.get(key, node)
            if src == node:
                continue
            read = key in _TS_TPL_READ_KEYS
            flagged += read
            rows.append([node, f"{key} = {kv[key]}", f"[{src}]",
                         ["read by sysmon tabs -- was missed before v6.13.59", "info"] if read else ["not read by those tabs", "pass"]])
            raw.append(f"[{node}] {key} = {kv[key]}   (from [{src}])")
    for node, tpl in scan["missing"]:
        rows.append([node, f"uses template [{tpl}]", "—", ["not found above it in rpt.conf -- Asterisk will refuse this", "fail"]])
        raw.append(f"[{node}] template [{tpl}] not found earlier in the file")
    if not rows:
        return {"cmd": f"{_RPT_CONF} templates", "raw": "No node takes a setting from a template.", "summary": {
            "status": "pass", "headline": "No node takes settings from a template",
            "note": "Every setting is written under its own node, so all tabs already saw it."}}
    bad = sum(1 for r in rows if r[3][1] == "fail")
    head = (f"{bad} missing template{'s' if bad != 1 else ''}" if bad else
            f"{flagged} setting{'s' if flagged != 1 else ''} the tabs used to miss" if flagged else
            "Template settings found -- none the tabs read")
    return {"cmd": f"{_RPT_CONF} templates", "raw": "\n".join(raw), "summary": {
        "status": "fail" if bad else ("info" if flagged else "pass"), "headline": head,
        "table": {"head": ["Node", "Setting", "From", "Note"], "rows": rows},
        "note": ("Since v6.13.59 the ASL-DVS rpt.conf card, Reg, DVSM, M17 and Zello checks and the header read "
                 "these the way Asterisk does: template first, the node's own line wins. Nothing to fix -- "
                 "this list shows what they now see that they didn't before.")}}

def _ts_ab_ports() -> "tuple[dict, str]":
    for f in _DVSWITCH_FILES:
        if f.name != "Analog_Bridge.ini" or not f.exists():
            continue
        try:
            txt = f.read_text(errors="replace")
        except OSError:
            continue
        sec, ports = "", {}
        for raw in txt.splitlines():
            ln = raw.split(";", 1)[0].strip()
            m = re.match(r"^\[([^\]]+)\]", ln)
            if m:
                sec = m.group(1).strip().upper()
                continue
            if sec == "USRP" and "=" in ln:
                k, v = (x.strip() for x in ln.split("=", 1))
                if k.lower() in ("txport", "rxport"):
                    ports[k.lower()] = v.split()[0] if v else ""
        return ports, str(f)
    return {}, ""

def _ts_udp_listeners() -> "tuple[dict, str]":
    out, prob = _ts_cmd(["ss", "-Hlunp"], 6)
    res = {}
    for ln in out.splitlines():
        m = re.search(r"\s(\S+):(\d+)\s+\S+\s*(?:users:\(\(\"([^\"]+)\")?", ln)
        if m:
            res.setdefault(m.group(2), set()).add(m.group(3) or "?")
    return res, prob

@_ts("Bridges", "ts_ports", "Bridge port check")
def _ts_ports():
    secs = _ts_rpt_sections()
    usrp = []
    for name, kv in secs.items():
        m = re.match(r"(?i)^usrp/([^:]+):(\d+):(\d+)", kv.get("rxchannel", ""))
        if m:
            usrp.append((name, m.group(1), m.group(2), m.group(3)))
    if not usrp:
        return {"cmd": "rpt.conf", "raw": "", "summary": {"status": "info", "headline": "No USRP bridge nodes in rpt.conf"}}
    ab, ab_file = _ts_ab_ports()
    m17 = _m17_read_config()
    lis, lprob = _ts_udp_listeners()
    raw = ["rpt.conf: " + ", ".join(f"[{n}] USRP/{h}:{a}:{b}" for n, h, a, b in usrp),
           f"Analog_Bridge.ini ({ab_file or 'not found'}): rxPort={ab.get('rxport', '?')} txPort={ab.get('txport', '?')}",
           f"USRP2M17.ini ({m17.get('ini_path') or 'not found'}): LocalPort={m17.get('usrp_local_port') or '?'} "
           f"DstPort={m17.get('usrp_dst_port') or '?'}",
           "Listening UDP ports: " + (", ".join(f"{p} ({'/'.join(sorted(v))})" for p, v in sorted(lis.items(), key=lambda x: int(x[0])))
                                      if lis else (lprob or "none"))]
    used: dict = {}
    for n, _h, a, b in usrp:
        for p_ in (a, b):
            used.setdefault(p_, []).append(n)
    rows, worst = [], "pass"
    rank = {"pass": 0, "info": 1, "warn": 2, "fail": 3}
    for n, _h, a, b in usrp:
        notes, st = [], "pass"
        partner = ""
        if ab and ab.get("rxport") == a and ab.get("txport") == b:
            partner = "Analog_Bridge"
            if a == "32001" and b == "34001":
                notes.append("order is reversed from the DVSwitch default, but Analog_Bridge matches -- fine")
                st = "info"
        elif m17.get("usrp_local_port") == a and m17.get("usrp_dst_port") == b:
            partner = "USRP2M17"
        else:
            hit = [w for w, ps in (("Analog_Bridge", (ab.get("rxport"), ab.get("txport"))),
                                   ("USRP2M17", (m17.get("usrp_local_port"), m17.get("usrp_dst_port"))))
                   if a in ps or b in ps]
            if hit:
                notes.append(f"{hit[0]} uses these ports the other way round or only one of them -- audio won't flow")
                st = "fail"
            else:
                notes.append("no Analog_Bridge or USRP2M17 setting matches these ports")
                st = "warn"
        clash = [p_ for p_ in (a, b) if len(used.get(p_, [])) > 1]
        if str(_ts_iax_port()) in (a, b):
            notes.append(f"uses the IAX2 port {_ts_iax_port()} that AllStar links need")
            st = "fail"
        if clash:
            notes.append(f"port {', '.join(clash)} is also used by node {', '.join(x for x in used[clash[0]] if x != n)}")
            st = "fail"
        if lis:
            if b not in lis:
                notes.append(f"nothing is listening on {b} (Asterisk should be)")
                st = "fail" if rank[st] < 3 else st
            if partner and a not in lis:
                notes.append(f"{partner} isn't listening on {a} -- is it running?")
                st = "warn" if rank[st] < 2 else st
        rows.append([n, f"sends {a} · listens {b}", partner or "—", ["; ".join(notes) or "ok", st]])
        if rank[st] > rank[worst]:
            worst = st
    return {"cmd": "rpt.conf + Analog_Bridge.ini + USRP2M17.ini + ss -lunp", "raw": "\n".join(raw), "summary": {
        "status": worst, "headline": {"pass": "Bridge ports line up", "info": "Bridge ports line up",
                                      "warn": "Something to look at", "fail": "A bridge port problem"}[worst],
        "table": {"head": ["Node", "Asterisk", "Partner", "Check"], "rows": rows}}}

@_ts("Bridges", "ts_traffic", "Bridge traffic")
def _ts_traffic():
    if not _ph_ast_running():
        return _ts_missing("rpt stats", "Asterisk is not running")
    secs = _ts_rpt_sections()
    nodes = [n for n, kv in secs.items() if kv.get("rxchannel", "").lower().startswith("usrp/")]
    rows, raw = [], []
    for n in nodes:
        out = _ph_cli(f"rpt stats {n}", timeout=8)
        raw += [f"$ rpt stats {n}", out.strip(), ""]
        kv = _con_dots(out)
        links = kv.get("Nodes currently connected to us", "")
        links = "" if links.strip().lower() in ("<none>", "none") else links
        ku = kv.get("Keyups today", "?")
        rows.append([n, links or "not linked", ku, kv.get("TX time today", "?"),
                     ["linked" if links else "idle", "pass" if links else ""]])
    if not rows:
        return {"cmd": "rpt stats", "raw": "", "summary": {"status": "info", "headline": "No USRP bridge nodes"}}
    return {"cmd": "rpt stats (each bridge node)", "raw": "\n".join(raw), "summary": {
        "status": "info", "headline": f"{sum(1 for r in rows if r[1] != 'not linked')} of {len(rows)} bridges linked",
        "table": {"head": ["Bridge node", "Linked to", "Key-ups today", "Transmit today", "Now"], "rows": rows},
        "note": "A bridge is only linked while its tab is in use on the dashboard; key-ups count audio coming from that network"}}

_TS_NC_UNIT = "netcheck.service"

_TS_NC_BRIDGES = (("Analog_Bridge", "analog_bridge.service"), ("MMDVM_Bridge", "mmdvm_bridge.service"),
                  ("STFU", "stfu.service"))

_TS_EXIT_WORDS = {0: "finished OK", 1: "general error", 2: "wrong options", 64: "wrong options",
                  65: "bad input data", 66: "a file it needs is missing", 67: "unknown user",
                  68: "name lookup failed (host name unknown)", 69: "service unavailable",
                  70: "internal error", 71: "system error", 72: "a system file is missing",
                  73: "can't create a file", 74: "input/output error", 75: "temporary failure",
                  76: "remote protocol error", 77: "permission denied", 78: "configuration error",
                  124: "timed out", 126: "can't run (not executable)", 127: "command not found"}

_TS_NOT_HOSTS = re.compile(r"(?i)\.(sh|py|pl|conf|cfg|ini|service|target|log|pid|txt|so|bin|json|lock|d|tmp|out|err)$")

def _ts_unit_props(unit: str, props: list) -> "tuple[dict, str]":
    out, prob = _ts_cmd(["systemctl", "show", unit, "-p", ",".join(props)], 6)
    d: dict = {}
    for ln in out.splitlines():
        k, sep, v = ln.partition("=")
        if sep:
            d[k.strip()] = v.strip()
    return d, prob

def _ts_exit_words(code: str, name: str = "") -> str:
    try:
        n = int(code)
    except (TypeError, ValueError):
        return name or "?"
    w = _TS_EXIT_WORDS.get(n, "")
    return f"exit {n}" + (f"/{name}" if name else "") + (f" -- {w}" if w else "")

def _ts_script_path(execstart: str) -> str:
    m = re.search(r"argv\[\]=([^;]*)", execstart)
    argv = m.group(1).split() if m else []
    if not argv:
        m = re.search(r"path=(\S+)", execstart)
        argv = [m.group(1)] if m else []
    interp = re.compile(r"^(?:.*/)?(?:env|sh|bash|dash|zsh|python[\d.]*|perl|ruby)$")
    for a in argv:
        if a.startswith("-") or interp.match(a) or "=" in a or not Path(a).is_file():
            continue
        return a
    return ""

def _ts_script_hosts(path: str) -> list:
    try:
        data = Path(path).read_bytes()[:400_000]
    except OSError:
        return []
    if data[:4] == b"\x7fELF":
        return []
    txt = "\n".join(ln for ln in data.decode("utf-8", "replace").splitlines()
                    if not ln.lstrip().startswith(("#", "//", ";")))
    found = []
    cands = re.findall(r"(?i)\b(?:https?|ftp)://([A-Za-z0-9.-]+)", txt)
    cands += re.findall(r"(?<![\w./-])((?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,})(?![\w-])", txt)
    for h in cands:
        hl = h.lower().rstrip(".")
        if _TS_NOT_HOSTS.search(hl) or hl in found or re.fullmatch(r"[\d.]+", hl):
            continue
        if hl.split(".")[-1] in ("conf", "service", "local", "sh", "py", "ini", "log"):
            continue
        found.append(hl)
    for ip in re.findall(r"(?<![\d.])((?:\d{1,3}\.){3}\d{1,3})(?![\d.])", txt):
        try:
            if ipaddress.ip_address(ip).is_global and ip not in found:
                found.append(ip)
        except ValueError:
            pass
    return found[:6]

def _ts_nc_state(issue, nc, rows):
    act, sub, res = nc.get("ActiveState", "?"), nc.get("SubState", "?"), nc.get("Result", "?")
    jout, jprob = _ts_cmd(["journalctl", "-u", _TS_NC_UNIT, "-b", "-n", "400", "--no-pager", "-o", "short-iso"], 10)
    jl = [] if jprob else [ln for ln in jout.splitlines() if ln.strip() and not ln.startswith("-- ")]
    tries = sum(1 for ln in jl if re.search(r"Starting netcheck", ln))
    fails = (sum(1 for ln in jl if "Failed with result" in ln)
             or sum(1 for ln in jl if "Failed to start netcheck" in ln))
    nc_ok = act == "active"
    enabled = nc.get("UnitFileState", "?")
    if nc_ok:
        rows.append(["Netcheck", f"{act} ({sub})", ["passed -- internet was found", "pass"]])
    elif act == "activating":
        rows.append(["Netcheck", f"{act} ({sub})", [f"testing now -- try {tries or 1} this boot"
                                                    + (f", {fails} failed" if fails else ""), "warn" if fails else "info"]])
    elif act == "failed":
        rows.append(["Netcheck", f"{act}", [f"failed -- {fails} failed tr{'ies' if fails != 1 else 'y'} this boot", "fail"]])
    else:
        rows.append(["Netcheck", f"{act} ({sub})", ["not run since boot" if not tries else "stopped", "warn"]])
    rows.append(["Turned on at boot", enabled,
                 ["yes" if enabled == "enabled" else "no -- the bridges still start it when they start",
                  "pass" if enabled == "enabled" else "info"]])

    end_re = re.compile(r"(?i)status=\d+|Failed with result|timed out|Deactivated successfully|Finished netcheck")
    tries_l: list = [[]]
    for ln in jl:
        if re.search(r"Starting netcheck", ln) and tries_l[-1]:
            tries_l.append([])
        tries_l[-1].append(ln)
    last_try = next((t for t in reversed(tries_l) if any(end_re.search(x) for x in t)), [])
    last_st = None
    for ln in reversed(last_try):
        m = re.search(r"status=(\d+)/?(\w*)", ln)
        if m:
            last_st = (m.group(1), m.group(2))
            break
    timed_out = any(re.search(r"(?i)start operation timed out|Failed with result 'timeout'", ln) for ln in last_try)
    exit_68 = False
    if timed_out or res == "timeout":
        why = ["took too long and was killed by systemd", "fail"]
        issue = issue or "timeout"
    elif last_st and last_st[0] != "0" and not nc_ok:
        why = [_ts_exit_words(*last_st), "fail"]
        exit_68 = last_st[0] == "68"
        issue = issue or ("dns" if exit_68 else "exit")
    elif res in ("signal", "core-dump"):
        why = [f"killed ({res}, signal {nc.get('ExecMainStatus', '?')})", "fail"]
        issue = issue or "killed"
    elif nc_ok or res == "success":
        why = ["finished OK" if nc_ok else "no failure recorded", "pass" if nc_ok else "info"]
    else:
        why = [f"result {res}", "warn"]
    rows.append(["Last result", (f"status={last_st[0]}/{last_st[1]}" if last_st else f"Result={res}"), why])
    msgs = [_ts_msg(ln) for ln in (last_try or jl) if " systemd[" not in ln]
    if msgs:
        rows.append(["Netcheck said", "last message", [msgs[-1][:140], "info"]])

    typ, rae = nc.get("Type", "?"), nc.get("RemainAfterExit", "?")
    dropins = nc.get("DropInPaths", "").split()
    dtxt = f"Type={typ}, RemainAfterExit={rae}" + (f" · {len(dropins)} override file{'s' if len(dropins) != 1 else ''}"
                                                   if dropins else " · no override file")
    if typ == "oneshot" and rae == "yes":
        rows.append(["Start type", dtxt, ["oneshot and stays up -- the earlier fix is in place", "pass"]])
    elif typ == "notify":
        rows.append(["Start type", dtxt, ["notify -- systemd waits for a ready signal the script never sends, then "
                                          "kills it (the problem fixed before)", "fail"]])
        issue = "notify" if issue in ("", "timeout") else issue
    elif typ == "oneshot":
        rows.append(["Start type", dtxt, ["oneshot but doesn't stay up -- it runs again each time a bridge starts", "info"]])
    else:
        rows.append(["Start type", dtxt, [f"{typ} -- the bridges don't wait for the test to finish", "warn"]])

    tlim = nc.get("TimeoutStartUSec", "?")
    rows.append(["Start time limit", tlim, ["hit -- see Last result", "fail"] if (timed_out or res == "timeout")
                 else ["not hit", "pass" if nc_ok else "info"]])
    return issue, jl, jprob, nc_ok

def _ts_nc_network(issue, nc, raw, rows):
    script = _ts_script_path(nc.get("ExecStart", ""))
    hosts = _ts_script_hosts(script) if script else []
    raw.append(f"ExecStart script: {script or '?'}  hosts found in it: {', '.join(hosts) or 'none'}")
    names = [h for h in hosts if not re.fullmatch(r"[\d.]+", h)]
    if names:
        res_l, bad = [], 0
        for h in names[:3]:
            out, _p = _ts_cmd(["getent", "ahostsv4", h], 6)
            ok = any(ln.split() for ln in out.splitlines())
            bad += 0 if ok else 1
            res_l.append(f"{h} {'found' if ok else 'NOT found'}")
        rows.append(["What it looks up", script, ["; ".join(res_l), "fail" if bad else "pass"]])
        if bad:
            issue = issue if issue in ("notify", "timeout") else "dns"
    elif script:
        rows.append(["What it looks up", script, ["no host name found in it (or it's a compiled program) -- "
                                                  "see its log lines", "info"]])

    nb = _ts_net_basics()
    raw += nb["raw"]
    rows.append(nb["ping"])
    rows.append(nb["dns"])
    if nb["inet"] is False and issue not in ("notify", "timeout"):
        issue = "noinet"
    elif not nb["dns_ok"] and issue not in ("notify", "timeout"):
        issue = "dns"

    after = nc.get("After", "").split()
    if "network-online.target" in after:
        waiter, wst = "", ""
        for mgr, w in (("NetworkManager.service", "NetworkManager-wait-online.service"),
                       ("systemd-networkd.service", "systemd-networkd-wait-online.service")):
            o, _p = _ts_cmd(["systemctl", "is-active", mgr], 4)
            if o.strip() == "active":
                e, _p = _ts_cmd(["systemctl", "is-enabled", w], 4)
                waiter, wst = w, e.strip() or "?"
                break
        if not waiter:
            rows.append(["Waits for network", "network-online.target", ["no known network manager running", "info"]])
        elif wst == "enabled":
            rows.append(["Waits for network", waiter, ["on -- netcheck runs after the network is up", "pass"]])
        else:
            rows.append(["Waits for network", waiter, [f"{wst} -- at boot netcheck can run before the network is up", "warn"]])

    for t in [u for u in after if re.match(r"(wg-quick@\S+|\S*tunnel\S*|wg\S*)\.service$", u)][:2]:
        tp, _p = _ts_unit_props(t, ["LoadState", "ActiveState"])
        ta = tp.get("ActiveState", "?")
        if tp.get("LoadState") == "not-found":
            rows.append(["Waits for tunnel", t, ["not installed -- ignored", "info"]])
        else:
            rows.append(["Waits for tunnel", t, ["up" if ta == "active" else f"{ta} -- netcheck waits for it",
                                                 "pass" if ta == "active" else "warn"]])
    return issue, raw

def _ts_nc_bridges(br_info, jl, jprob, nc_ok, raw, rows):
    blocked = 0
    for name, unit, bp, needs, depf in br_info:
        st, ss = bp.get("ActiveState", "?"), bp.get("SubState", "?")
        if st == "active":
            rows.append([name, f"{st} ({ss})", ["running", "pass"]])
        elif needs and not nc_ok:
            blocked += 1
            rows.append([name, f"{st} ({ss})", ["blocked -- waiting on netcheck"
                                                + (f" ({depf} dependency fail{'s' if depf != 1 else ''} this boot)" if depf else ""),
                                                "fail"]])
        elif st == "activating":
            rows.append([name, f"{st} ({ss})", ["starting", "info"]])
        else:
            rows.append([name, f"{st} ({ss})", [("failed on its own -- see its log" if st == "failed"
                                                 else "stopped") + (" · doesn't need netcheck" if not needs else ""),
                                                "fail" if st == "failed" else "warn"]])
    raw += ["", f"$ journalctl -u netcheck -b (last 15 of {len(jl)})"] + (jl[-15:] if jl else [jprob or "no entries this boot"])
    return blocked, raw

@_ts("Bridges", "ts_netcheck", "Netcheck startup")
def _ts_netcheck():
    props = ["LoadState", "UnitFileState", "ActiveState", "SubState", "Result", "Type", "RemainAfterExit",
             "ExecMainStatus", "ExecMainCode", "TimeoutStartUSec", "FragmentPath", "DropInPaths", "ExecStart",
             "After", "NRestarts"]
    nc, prob = _ts_unit_props(_TS_NC_UNIT, props)
    if prob or not nc.get("LoadState"):
        return _ts_missing("systemctl show netcheck", prob or "systemd didn't answer")
    raw = ["$ systemctl show netcheck"] + [f"{k}={nc.get(k, '')}" for k in props] + [""]
    rows, issue = [], ""
    br_info = []
    for name, unit in _TS_NC_BRIDGES:
        bp, _p = _ts_unit_props(unit, ["LoadState", "ActiveState", "SubState", "Result", "Requires", "After"])
        if bp.get("LoadState", "not-found") == "not-found":
            continue
        needs = _TS_NC_UNIT in bp.get("Requires", "").split()
        jout, _j = _ts_cmd(["journalctl", "-u", unit, "-b", "-n", "300", "--no-pager", "-o", "short-iso"], 10)
        depf = len(re.findall(r"Dependency failed for", jout))
        br_info.append((name, unit, bp, needs, depf))
        raw.append(f"{unit}: {bp.get('ActiveState', '?')}/{bp.get('SubState', '?')} result={bp.get('Result', '?')} "
                   f"needs netcheck={'yes' if needs else 'no'} dependency-failed this boot={depf}")
    any_needs = any(b[3] for b in br_info)

    if nc.get("LoadState") == "not-found":
        rows.append(["Netcheck", "not installed", ["no netcheck.service on this Pi", "fail" if any_needs else "info"]])
        for name, unit, bp, needs, depf in br_info:
            st = bp.get("ActiveState", "?")
            rows.append([name, f"{st}/{bp.get('SubState', '?')}",
                         ["running" if st == "active" else ("can't start -- needs netcheck, which is missing" if needs
                                                           else "not running"),
                          "pass" if st == "active" else ("fail" if needs else "warn")]])
        return {"cmd": "systemctl show netcheck + bridges", "raw": "\n".join(raw), "summary": {
            "status": _ts_worst([r[2][1] for r in rows]),
            "headline": "Netcheck isn't installed but the bridges need it" if any_needs else "No netcheck on this Pi",
            "table": {"head": ["Check", "Found", "Result"], "rows": rows},
            "note": "Reinstall DVSwitch, or remove Requires=netcheck.service from the bridge units" if any_needs else ""}}

    issue, jl, jprob, nc_ok = _ts_nc_state(issue, nc, rows)

    issue, raw = _ts_nc_network(issue, nc, raw, rows)

    blocked, raw = _ts_nc_bridges(br_info, jl, jprob, nc_ok, raw, rows)

    down = [r for r in rows if r[0] in [b[0] for b in br_info] and r[2][1] != "pass"]
    if nc_ok and not down:
        head = "Netcheck OK -- bridges free to start"
    elif nc_ok:
        head = "Netcheck OK -- a bridge is down for another reason"
    elif issue == "notify":
        head = "Netcheck is killed on start -- the earlier fix is missing"
    elif issue == "timeout":
        head = "Netcheck timed out"
    elif issue == "noinet":
        head = "No internet -- netcheck can't pass"
    elif issue == "dns":
        head = "Netcheck can't look up names -- DNS problem"
    else:
        head = "Netcheck failed" + (" -- bridges blocked" if blocked else "")
    notes = {
        "notify": "To fix: sudo systemctl edit netcheck, add [Service] Type=oneshot and RemainAfterExit=yes, "
                  "then sudo systemctl daemon-reload and restart netcheck and the bridges",
        "timeout": "It ran out of time: check Internet by IP and DNS servers above, then restart netcheck",
        "noinet": "Check the Pi's gateway (ip route) -- a static IP needs a gateway as well as DNS servers",
        "dns": "Add DNS servers to the connection (for example nmcli con mod <name> ipv4.dns \"8.8.8.8 1.1.1.1\", "
               "then nmcli con up <name>), then restart netcheck and the bridges",
    }
    note = "" if nc_ok and not down else notes.get(issue, "See Netcheck said and the full output for the reason")
    if not nc_ok and blocked:
        note += (" · " if note else "") + "Restart after fixing: sudo systemctl restart netcheck " + \
            " ".join(u.replace(".service", "") for _n, u, _b, need, _d in br_info if need)
    return {"cmd": "systemctl show netcheck + journalctl -u netcheck -b + bridges", "raw": "\n".join(raw), "summary": {
        "status": "pass" if nc_ok and not down else _ts_worst([r[2][1] for r in rows]),
        "headline": head, "table": {"head": ["Check", "Found", "Result"], "rows": rows}, "note": note}}

@_ts("Phone", "ts_dupreg", "Duplicate sign-in check")
def _ts_dupreg():
    if not _ph_ast_running():
        return _ts_missing("pjsip show registrations", "Asterisk is not running")
    out = _ph_cli("pjsip show registrations", timeout=8)
    regs = re.findall(r"^\s*(\S+?)/sip:\S+\s+\S+\s+(Registered|Unregistered|Rejected|Retry Wait|Stopped)", out, re.M)
    seen: dict = {}
    raw = [out.strip()]
    for name, state in regs:
        det = _ph_cli(f"pjsip show registration {name}", timeout=6)
        m = re.search(r"client_uri\s*:\s*sip:([^@\s]+)@([^:;>\s]+)", det)
        if not m:
            continue
        seen.setdefault((m.group(1), m.group(2).lower()), []).append((name, state))
    rows, dup = [], 0
    for (user, host), accts in seen.items():
        live = [a for a, s in accts if s == "Registered"]
        if len(live) > 1:
            dup += 1
            rows.append([f"{user} @ {host}", ", ".join(live), ["signed in more than once", "warn"]])
        else:
            rows.append([f"{user} @ {host}", ", ".join(a for a, _s in accts), ["ok", "pass"]])
    if not rows:
        return {"cmd": "pjsip show registrations", "raw": "\n".join(raw),
                "summary": {"status": "info", "headline": "No phone accounts sign in"}}
    return {"cmd": "pjsip show registrations + each registration", "raw": "\n".join(raw), "summary": {
        "status": "warn" if dup else "pass",
        "headline": "No duplicate sign-ins" if not dup else f"{dup} number{'s' if dup != 1 else ''} signed in more than once",
        "table": {"head": ["Number", "Accounts", "Check"], "rows": rows},
        "note": "Two sign-ins for one number compete: calls may go to either. On dashboard v9.3.24+ choose "
                "'Sign in: picked network only' on the Edit page" if dup else ""}}

def _ts_patch_nodes() -> list:
    secs = _ts_rpt_sections()
    res = []
    for n, kv in secs.items():
        if not re.fullmatch(r"\d{3,7}", n):
            continue
        table = kv.get("functions") or (secs.get(kv.get("__tmpl", ""), {}).get("functions")) or "functions"
        fsec = secs.get(table, {})
        if not fsec and table == "functions":
            fsec = secs.get("functions-main", {})
        code = next((k for k, v in fsec.items() if k != "__tmpl" and v.split(",")[0].strip() == "autopatchdn"), "")
        res.append((n, code))
    return res

@_ts("Phone", "ts_patch", "Stuck autopatch")
def _ts_patch():
    if not _ph_ast_running():
        return _ts_missing("rpt xnode", "Asterisk is not running")
    calls = _ph_cli("core show channels concise", timeout=8)
    phone_up = [ln.split("!")[0] for ln in calls.splitlines() if ln.lower().startswith(("pjsip/", "sip/"))]
    rows, stuck, raw = [], 0, []
    for n, code in _ts_patch_nodes():
        xn = _ph_cli(f"rpt xnode {n}", timeout=8)
        v = _con_vars(xn)
        if "RPT_AUTOPATCHUP" not in v:
            continue
        up = v.get("RPT_AUTOPATCHUP") == "1"
        raw.append(f"{n}: RPT_AUTOPATCHUP={v.get('RPT_AUTOPATCHUP')}")
        if up and not phone_up:
            stuck += 1
            rows.append([n, "up", ["stuck -- no phone call", "warn"], ("*" + code) if code else "none"])
        else:
            rows.append([n, "up" if up else "down", ["in a call" if up else "ok", "pass" if not up or phone_up else "warn"],
                         ("*" + code) if code else "none"])
    if not rows:
        return {"cmd": "rpt xnode (each node)", "raw": "\n".join(raw),
                "summary": {"status": "info", "headline": "No node reports an autopatch"}}
    return {"cmd": "rpt xnode (each node) + core show channels", "raw": "\n".join(raw + ["", calls.strip()]), "summary": {
        "status": "warn" if stuck else "pass",
        "headline": "No stuck autopatch" if not stuck else f"Autopatch stuck up on {stuck} node{'s' if stuck != 1 else ''}",
        "table": {"head": ["Node", "Autopatch", "Check", "Hang-up code"], "rows": rows},
        "note": "Press Hang up stuck autopatch to send each stuck node its hang-up code" if stuck else ""}}

@_ts("Phone", "ts_patch_hangup", "Hang up stuck autopatch", "act")
def _ts_patch_hangup():
    if not _ph_ast_running():
        return _ts_missing("rpt fun", "Asterisk is not running")
    calls = _ph_cli("core show channels concise", timeout=8)
    phone_up = any(ln.lower().startswith(("pjsip/", "sip/")) for ln in calls.splitlines())
    done, skipped = [], []
    for n, code in _ts_patch_nodes():
        v = _con_vars(_ph_cli(f"rpt xnode {n}", timeout=8))
        if v.get("RPT_AUTOPATCHUP") != "1":
            continue
        if phone_up:
            skipped.append(f"{n} (a phone call is up -- hang that up instead)")
        elif not code:
            skipped.append(f"{n} (no autopatchdn code in its function list)")
        else:
            _ph_cli(f"rpt fun {n} *{code}", timeout=8)
            done.append(f"{n} (*{code})")
    st = "pass" if done and not skipped else ("warn" if skipped else "info")
    return {"cmd": "rpt fun <node> *<autopatchdn code>", "raw": "\n".join(["sent: " + ", ".join(done) if done else "sent: nothing",
                                                                         "skipped: " + "; ".join(skipped) if skipped else ""]),
            "summary": {"status": st, "headline": ("Sent hang-up to " + ", ".join(done)) if done else "Nothing to hang up",
                        "note": "; ".join(skipped)}}

@_ts("Phone", "ts_incoming", "Last incoming calls")
def _ts_incoming():
    if not _ph_ast_running():
        return _ts_missing("pjsip show history", "Asterisk is not running")
    rows_h = _rt_history_rows()
    inv = [r for r in rows_h if r["dir"] == "in" and r["msg"].upper().startswith("INVITE")][-5:]
    rows = []
    for r in reversed(inv):
        ans = [re.sub(r"^SIP/2\.0\s+", "", a["msg"]) for a in rows_h
               if a["dir"] == "out" and a["ts"] >= r["ts"] and a["msg"].startswith("SIP/2.0")][:4]
        ok = any(a.startswith("200") for a in ans)
        rows.append([datetime.fromtimestamp(r["ts"]).strftime("%m-%d %H:%M:%S"), r["addr"],
                     [" → ".join(ans) or "no answer", "pass" if ok else "warn"]])
    if not rows:
        return {"cmd": "pjsip show history", "raw": "", "summary": {
            "status": "info", "headline": "No incoming calls recorded",
            "note": "Asterisk only records these while SIP history is on. Turn it on with Start watching on the "
                    "Phone tab's Router test card, then check again after a call"}}
    return {"cmd": "pjsip show history", "raw": "", "summary": {
        "status": "info", "headline": f"Last {len(rows)} incoming call{'s' if len(rows) != 1 else ''}",
        "table": {"head": ["When", "From", "Pi answered"], "rows": rows}}}

def _ts_dp_globals(ctx: dict) -> dict:
    out = {}
    for s in ctx["conf"]["extensions.conf"]:
        if s["name"].lower() == "globals":
            for k, v, *_ in s["kv"]:
                out[k.strip()] = v.strip()
    return out

_TS_VAR_RE = re.compile(r"\$\{(\w+)(?::(-?\d+)(?::(\d+))?)?\}")

def _ts_dp_set(var: str, entries: list) -> str:
    for e in entries:
        for st in e["steps"]:
            if st["app"].lower() != "set":
                continue
            mm = re.match(r"^\s*" + re.escape(var) + r"\s*=\s*([^,]*)", st["args"])
            if mm and mm.group(1).strip() and "${" not in mm.group(1):
                return mm.group(1).strip()
    return ""

def _ts_expand(s: str, ext: str, entries: list, glb: dict) -> str:
    def sub(m):
        name, off, ln = m.group(1), m.group(2), m.group(3)
        if name == "EXTEN":
            val = ext if ext and not ext.startswith("_") and "${" not in ext else ""
        else:
            val = _ts_dp_set(name, entries) or glb.get(name, "")
        if not val:
            return m.group(0)
        if off:
            val = val[int(off):]
        if ln:
            val = val[:int(ln)]
        return val
    return _TS_VAR_RE.sub(sub, s.strip())

def _ts_pat_prefix(pat: str) -> str:
    if not pat.startswith("_"):
        return ""
    out = ""
    for c in pat[1:]:
        if c.isdigit():
            out += c
        else:
            break
    return out

def _ts_rpt_landing(st: dict, ext: str, entries: list, glb: dict, cname: str, src: str, e: dict) -> dict:
    parts = re.split(r"[,|]", st["args"])
    node = _ts_expand(parts[0], ext, entries, glb)
    opts = _ts_expand(parts[1], ext, entries, glb) if len(parts) > 1 else ""
    mode = "?" if opts.startswith("$") else opts[:1]
    return {"context": cname, "from": src, "node": node, "node_arg": parts[0].strip(), "opts": opts,
            "mode": mode, "voice": mode != "?" and "v" in opts[1:], "raw": st["raw"], "file": e["file"],
            "pattern": e["pattern"], "ext": ext or ""}

_TS_JUMP_GOTO = re.compile(r"\b([A-Za-z][\w\-]*)\s*,\s*([^,()?:]+?)\s*,\s*[^,()?:]+")

_TS_JUMP_LOCAL = re.compile(r"Local/([^@/,&)\s]+)@([\w\-]+)")

_TS_QUIET_APPS = {"answer", "wait", "playback", "noop", "verbose", "set", "ringing", "progress",
                  "hangup", "busy", "congestion", "read", "gotoif", "goto", "saydigits", "background"}

def _ts_phone_routes(ctx: dict) -> "tuple[list, list, list]":
    plan = ctx["dialplan"]
    glb = _ts_dp_globals(ctx)
    try:
        nets = _phone_sec_networks(ctx)["networks"]
    except Exception:
        nets = []
    landings, unrouted, raw, used = [], [], [], set()
    seen_land = set()
    for n in nets:
        start = n.get("context", "")
        if not start:
            unrouted.append({"from": n["name"], "status": "info",
                             "why": "no incoming context on the account -- calls in aren't answered"})
            continue
        queue, visited, apps, found = [(start, "")], set(), [], 0
        while queue and len(visited) < 40:
            cname, ext = queue.pop(0)
            if (cname, ext) in visited:
                continue
            visited.add((cname, ext))
            entries = plan.get(cname, [])
            if ext:
                use = [e for e in entries
                       if _ph_pat_match(_ts_expand(e["pattern"], "", entries, glb), ext)]
            else:
                use = entries
            for e in use:
                used.add(id(e))
                e_ext = ext or (_ts_expand(e["pattern"], "", entries, glb) if not e["pattern"].startswith("_") else "")
                for st in e["steps"]:
                    app = st["app"].lower()
                    apps.append(app)
                    if app == "rpt":
                        ld = _ts_rpt_landing(st, e_ext, entries, glb, cname, n["name"], e)
                        ld["net_id"] = n["id"]
                        key = (n["name"], cname, ld["node"], ld["opts"])
                        if key not in seen_land:
                            seen_land.add(key)
                            landings.append(ld)
                        found += 1
                    elif app in ("goto", "gotoif"):
                        for tc, te in _TS_JUMP_GOTO.findall(st["args"]):
                            te = _ts_expand(te, e_ext, entries, glb)
                            if tc in plan:
                                queue.append((tc, te))
                    elif app == "dial":
                        for te, tc in _TS_JUMP_LOCAL.findall(st["args"]):
                            if tc in plan:
                                queue.append((tc, _ts_expand(te, e_ext, entries, glb)))
        raw.append(f"--- {n['name']} ({n['id']}): answering rules from [{start}]")
        for cname in dict.fromkeys(c for c, _x in sorted(visited)):
            raw.append(f"[{cname}]")
            for e in plan.get(cname, []):
                for st in e["steps"]:
                    raw.append(f"  {e['pattern']}  {_ph_mask(st['raw'])}")
        if start not in plan:
            unrouted.append({"from": n["name"], "why": f"its incoming context [{start}] isn't in the dialplan",
                             "status": "warn"})
        elif not found:
            real = [a for a in dict.fromkeys(apps) if a not in _TS_QUIET_APPS]
            if not real and "hangup" in apps:
                unrouted.append({"from": n["name"], "why": "hangs up -- incoming calls are off", "status": "info"})
            else:
                unrouted.append({"from": n["name"], "status": "info",
                                 "why": "answered without rpt() (" + (", ".join(real) or "no call steps") +
                                        ") -- see Show full output"})
    for cname, entries in plan.items():
        for e in entries:
            if id(e) in used:
                continue
            pat = _ts_expand(e["pattern"], "", entries, glb)
            for st in e["steps"]:
                if st["app"].lower() != "rpt":
                    continue
                ld = _ts_rpt_landing(st, pat if not pat.startswith("_") else "", entries, glb, cname, "", e)
                if ld["mode"] not in ("P", "D", "S", "?"):
                    continue
                pre = _ts_pat_prefix(pat)
                ld["from"] = f"[{cname}]" + (f" numbers starting {pre}" if pre else "")
                key = ("", cname, ld["node"], ld["opts"], pre)
                if key in seen_land:
                    continue
                seen_land.add(key)
                landings.append(ld)
                raw.append(f"[{cname}] {pat}  {st['raw']}   ({e['file']})")
    return landings, unrouted, raw

def _ts_phone_landings(ctx: dict) -> list:
    return _ts_phone_routes(ctx)[0]

def _ts_func_ptt(secs: list, stanza: str) -> "tuple[bool, list]":
    exists = any(s["name"] == stanza for s in secs)
    kv, _m, _f = _ph_resolve(secs, stanza)
    codes = sorted(c for c, v in kv.items() if re.match(r"^\s*cop\s*,\s*6\s*$", v.split(";")[0], re.I))
    return exists, codes

_TS_MODE_TXT = {"P": "phone", "D": "dumb phone", "S": "simplex phone"}

@_ts("Phone", "ts_star99", "*99 keying")
def _ts_star99():
    ctx = _ph_load_ctx()
    if "extensions.conf" not in ctx["files"] or "rpt.conf" not in ctx["files"]:
        return _ts_missing("extensions.conf + rpt.conf", "extensions.conf or rpt.conf could not be read")
    secs = ctx["conf"]["rpt.conf"]
    lands, unrouted, raw = _ts_phone_routes(ctx)
    running = _ph_ast_running()
    local = set()
    if running:
        local = {ln.strip() for ln in _ph_cli("rpt localnodes", 4).splitlines() if ln.strip().isdigit()}
    rows, notes = [], []
    for u in unrouted:
        rows.append([u["from"], "-", "-", "-", "-", [u["why"], u["status"]]])
    for ld in lands:
        node = ld["node"]
        mode_txt = (ld["opts"] or "none") + (" (" + _TS_MODE_TXT[ld["mode"]] + (" + voice keying" if ld["voice"] else "") + ")"
                                             if ld["mode"] in _TS_MODE_TXT else "")
        if ld["mode"] == "?":
            rows.append([ld["from"], node, ld["opts"], "?", "?", ["mode letters are set while the call runs -- can't check", "info"]])
            continue
        if ld["mode"] not in _TS_MODE_TXT:
            rows.append([ld["from"], node, mode_txt, "?", "-",
                         ["handed over without phone mode (P, D or S) -- *99 can't key", "warn"]])
            notes.append(f"{ld['from']}: rpt() needs a P in its options for *99 / # to work ({ld['raw']})")
            continue
        if not node.isdigit():
            if "${EXTEN" in node:
                pre = _ts_pat_prefix(ld["pattern"])
                msg = "the caller picks the node" + (f" (dials {pre} + node number)" if pre else "")
            else:
                msg = "node is set while the call runs -- can't check from files"
            rows.append([ld["from"], node, mode_txt, "?", "?", [msg, "info"]])
            continue
        if not any(s["name"] == node and not s["is_template"] for s in secs):
            rows.append([ld["from"], node, mode_txt, "?", "?", [f"node {node} is not in rpt.conf", "fail"]])
            notes.append(f"Calls go to node {node}, which rpt.conf doesn't have")
            continue
        kv, _m, _f = _ph_resolve(secs, node)
        dup = kv["duplex"].split()[0] if kv.get("duplex") else "2"
        pf = kv["phone_functions"].split()[0] if kv.get("phone_functions") else ""
        own = kv["functions"].split()[0] if kv.get("functions") else "functions"
        if ld["mode"] != "P":
            msg = ("keys for the whole call -- *99 isn't needed" if ld["mode"] == "D"
                   else "simplex phone mode -- *99 isn't used")
            rows.append([ld["from"], node, mode_txt, dup, "n/a", [msg, "info"]])
            continue
        disagree = False
        if pf:
            exists, codes = _ts_func_ptt(secs, pf)
            where = (f"*{', *'.join(codes)} in [{pf}]" if codes else f"none in [{pf}]") if exists else f"[{pf}] missing"
        else:
            e1, c1 = _ts_func_ptt(secs, "functions")
            e2, c2 = _ts_func_ptt(secs, own) if own != "functions" else (e1, c1)
            exists, codes = e1, c1
            where = "no phone_functions line"
            if own != "functions" and bool(c1) != bool(c2):
                has, lacks = (("functions", own) if c1 else (own, "functions"))
                disagree = True
                notes.append(f"Node {node}: *99 is in [{has}] but not in [{lacks}] -- add "
                             f"phone_functions = {has} under [{node}] so phone calls use the list that has it")
        if dup in ("0", "1"):
            res = [f"duplex {dup} uses voice keying -- *99 does nothing", "warn"]
            notes.append(f"Node {node} is duplex {dup}: phone callers key it by talking (VOX). "
                         "*99 / # only work on duplex 2 or higher")
        elif ld["voice"]:
            res = ["the v letter turns on voice keying -- *99 isn't used", "info"]
        elif not pf:
            res = ["no phone_functions line -- callers may get no keypad commands", "warn"]
            if not disagree:
                notes.append(f"Add phone_functions = functions under [{node}] (the ASL3 default) and reload app_rpt")
        elif not exists:
            res = [f"phone_functions points at [{pf}], which rpt.conf doesn't have", "fail"]
        elif not codes:
            res = ["no *99 line", "fail"]
            notes.append(f"Add 99 = cop,6 under [{pf}], then: asterisk -rx \"module reload app_rpt\"")
        elif "99" not in codes:
            res = [f"push-to-talk is *{codes[0]}, not *99", "warn"]
            notes.append(f"Node {node}'s push-to-talk code is *{codes[0]}: the dashboard's *99 button won't key it")
        else:
            res = ["*99 keys, # unkeys", "pass"]
        if res[1] == "pass" and running and local and node not in local:
            res = ["rpt.conf has it but Asterisk isn't running it -- reload app_rpt", "warn"]
        rows.append([ld["from"], node, mode_txt, dup, where, res])
    if not rows:
        return {"cmd": "extensions.conf rpt() steps + rpt.conf", "raw": "\n".join(raw), "summary": {
            "status": "info", "headline": "No answering rule sends calls to a node in phone mode",
            "note": "Incoming calls reach a node through rpt(node|P) in the dialplan. Set up incoming calls "
                    "on the dashboard's Phone page first"}}
    st = _ts_worst([r[5][1] for r in rows])
    bad = sum(1 for r in rows if r[5][1] in ("fail", "warn"))
    head = ("*99 will key the transmitter" if st == "pass" else
            f"{bad} answering rule{'s' if bad != 1 else ''} where *99 won't key" if bad else
            "*99 isn't used by these answering rules")
    return {"cmd": "extensions.conf (each phone network's answering rules) + rpt.conf", "raw": "\n".join(raw),
            "summary": {
        "status": st, "headline": head,
        "table": {"head": ["Calls from", "Node", "Mode", "Duplex", "Push-to-talk line", "Result"], "rows": rows},
        "note": " · ".join(dict.fromkeys(notes))}}

def _ts_radio_node(ctx: dict) -> str:
    if ctx["dash"].get("asl_node"):
        return ctx["dash"]["asl_node"]
    secs = ctx["conf"]["rpt.conf"]
    radios = []
    for name in dict.fromkeys(s["name"] for s in secs if s["name"].isdigit() and not s["is_template"]):
        kv, _m, _f = _ph_resolve(secs, name)
        rx = kv.get("rxchannel", "").split()[0].lower() if kv.get("rxchannel") else ""
        if rx and not rx.startswith(("dahdi/pseudo", "local/pseudo", "usrp/")) and "pseudo" not in rx:
            radios.append(name)
    return radios[0] if len(radios) == 1 else ""

_TS_LINK_MODE = {"talk + listen": "pass", "listen only": "warn", "local monitor": "warn"}

@_ts("Phone", "ts_phpath", "Repeater path")
def _ts_phpath():
    ctx = _ph_load_ctx()
    dash = ctx["dash"]
    radio = _ts_radio_node(ctx)
    if not radio:
        return _ts_missing("asl_dvs.conf + rpt.conf", "Can't tell which node is the radio: no asl_node in "
                           "asl_dvs.conf and rpt.conf has more than one radio node")
    nodes: dict = {}
    for ld in _ts_phone_landings(ctx):
        if ld["node"].isdigit():
            prev, was = nodes.get(ld["node"], ("", False))
            need = not ld.get("net_id") or ld["net_id"] == dash.get("active", "")
            nodes[ld["node"]] = ((prev + ", " if prev else "") + ld["from"], was or need)
    live = dash.get("live_phone_node", "")
    for nd, nm in (dash.get("phone_nodes") or {}).items():
        if nd not in nodes:
            nodes[nd] = (f"{nm} (phone node)", nd == live)
    if live and live not in nodes:
        nodes[live] = ("Phone Bridge", True)
    if not nodes:
        return {"cmd": "phone.json + extensions.conf", "raw": "", "summary": {
            "status": "info", "headline": "No phone node set up",
            "note": "Set up a phone network on the dashboard's Phone page first"}}
    if not _ph_ast_running():
        return _ts_missing("rpt xnode", "Asterisk is not running")
    rad_raw = _ph_cli(f"rpt xnode {radio}", timeout=8)
    rad_links = {n: (mode, keyed) for n, mode, keyed in _con_alinks(_con_vars(rad_raw).get("RPT_ALINKS", ""))}
    raw = [f"$ rpt xnode {radio}", rad_raw.strip(), ""]
    rows, notes = [], []
    for nd, (src, expected) in nodes.items():
        if nd == radio:
            rows.append([src, nd, "is the radio node", "-", ["calls key the radio directly", "pass"]])
            continue
        xn = _ph_cli(f"rpt xnode {nd}", timeout=8)
        raw += [f"$ rpt xnode {nd}", xn.strip(), ""]
        if "RPT_" not in xn:
            rows.append([src, nd, "?", "?", ["Asterisk isn't running this node", "fail" if expected else "info"]])
            if expected:
                notes.append(f"Node {nd} isn't running: check rpt.conf, then asterisk -rx \"module reload app_rpt\"")
            continue
        mine = {n: (mode, keyed) for n, mode, keyed in _con_alinks(_con_vars(xn).get("RPT_ALINKS", ""))}
        a = mine.get(radio, ("", False))[0]
        b = rad_links.get(nd, ("", False))[0]
        view_a, view_b = a or "not linked", b or "not linked"
        if not a and not b:
            if expected:
                res = [f"not linked to {radio} -- calls won't reach the repeater", "warn"]
                notes.append(f"Link {nd} to {radio} in talk + listen: asterisk -rx \"rpt cmd {radio} ilink 3 {nd}\"")
            else:
                res = ["not linked (not the picked network -- expected)", "info"]
        else:
            worst = _ts_worst([_TS_LINK_MODE.get(x, "warn") for x in (a, b) if x])
            if worst == "pass":
                res = ["linked, talk + listen", "pass"]
            else:
                res = ["linked, but listen-only on one side -- talk may only go one way", "warn"]
                notes.append(f"Reconnect {nd} and {radio} in talk + listen mode (ilink 3, not 2 or 8)")
            if not expected:
                res = [res[0] + " -- but this isn't the picked network's node", "warn"]
                notes.append("Only the picked network's phone node should be linked to the radio")
        rows.append([src, nd, view_a, view_b, res])
    st = _ts_worst([r[4][1] for r in rows])
    ok = sum(1 for r in rows if r[4][1] == "pass")
    return {"cmd": "rpt xnode (radio node + each phone node)", "raw": "\n".join(raw), "summary": {
        "status": st,
        "headline": (f"Phone calls reach radio node {radio}" if st in ("pass", "info") and ok else
                     f"Phone calls may not reach radio node {radio}" if st in ("warn", "fail") else
                     "No phone node is linked to the radio (none needs to be right now)"),
        "table": {"head": ["Calls from", "Phone node", f"Its link to {radio}", f"{radio}'s link to it", "Result"],
                  "rows": rows},
        "note": " · ".join(dict.fromkeys(notes))}}

_TS_VOX_DEFAULTS = (("voxtimeout", "10000", "most the phone can hold the transmitter", "ms"),
                    ("voxrecover", "2000", "pause after that so radio users can break in", "ms"),
                    ("simplexpatchdelay", "25", "delay before phone audio goes out", "× 20 ms"),
                    ("simplexphonedelay", "25", "delay on audio sent to the phone", "× 20 ms"))

@_ts("Phone", "ts_patchset", "Autopatch settings")
def _ts_patchset():
    ctx = _ph_load_ctx()
    if "rpt.conf" not in ctx["files"]:
        return _ts_missing("rpt.conf", "rpt.conf could not be read")
    secs = ctx["conf"]["rpt.conf"]
    rows, kv_rows, notes, raw = [], [], [], []
    for name in dict.fromkeys(s["name"] for s in secs if s["name"].isdigit() and not s["is_template"]):
        kv, _m, _f = _ph_resolve(secs, name)
        lists = [kv[k].split()[0] for k in ("functions", "phone_functions", "link_functions") if kv.get(k)]
        ap, table_name, table = None, "", {}
        for st_name in dict.fromkeys(lists or ["functions"]):
            table, _m2, _f2 = _ph_resolve(secs, st_name)
            hit = next(((c, v) for c, v in sorted(table.items()) if v.strip().lower().startswith("autopatchup")), None)
            if hit:
                ap, table_name = hit, st_name
                break
        if not ap:
            continue
        code, value = ap
        raw.append(f"[{name}] uses [{table_name}]: {code} = {value}")
        opts = _ph_parse_autopatch(value)
        dup = kv["duplex"].split()[0] if kv.get("duplex") else "2"
        simplex = dup in ("0", "1")
        on = lambda k: opts.get(k, "0").strip() == "1"
        hang = next((c for c, v in sorted(table.items()) if v.split(",")[0].strip().lower() == "autopatchdn"), "")
        holder = next((s for s in reversed(secs) if any(k.strip() == code and v.strip() == value.strip()
                                                         for k, v, *_ in s["kv"])), None)
        where = f"[{holder['name']}] in {holder['file']}" if holder else f"[{table_name}]"
        issues = []
        if simplex and not on("quiet"):
            issues.append(["simplex node without quiet=1", "warn"])
            notes.append(f"Node {name}: add quiet=1 to the autopatch line in {where}: "
                         f"{code} = {value.rstrip(',')},quiet=1 -- then asterisk -rx \"module reload app_rpt\"")
        if not hang:
            issues.append(["no hang-up code (autopatchdn)", "warn"])
            notes.append(f"Node {name}: [{table_name}] has no autopatchdn line, so radio users can't hang up")
        if not on("farenddisconnect"):
            issues.append(["stays up after the far end hangs up", "info"])
            notes.append(f"Node {name}: without farenddisconnect=1 the patch keeps sending a busy tone "
                         "until someone sends the hang-up code")
        res = ([" · ".join(i[0] for i in issues), _ts_worst([i[1] for i in issues])] if issues else ["ok", "pass"])
        rows.append([name, dup + (" (simplex, voice keying)" if simplex else " (full duplex)"), "*" + code,
                     "*" + hang if hang else "none", "yes" if on("quiet") else "no",
                     "yes" if on("farenddisconnect") else "no", "yes" if on("noct") else "no", res])
        if simplex:
            parts = []
            for k, dflt, what, unit in _TS_VOX_DEFAULTS:
                v = kv[k].split()[0] if kv.get(k) else ""
                parts.append(f"{k} {v or dflt} {unit}" + ("" if v else " (default)"))
            kv_rows.append([f"Node {name} voice keying", " · ".join(parts)])
    if not rows:
        return {"cmd": "rpt.conf function lists", "raw": "\n".join(raw), "summary": {
            "status": "info", "headline": "No node has an autopatch code",
            "note": "An autopatch code is an autopatchup line in a node's function list"}}
    st = _ts_worst([r[7][1] for r in rows])
    bad = sum(1 for r in rows if r[7][1] == "warn")
    return {"cmd": "rpt.conf function lists (with templates)", "raw": "\n".join(raw), "summary": {
        "status": st,
        "headline": (f"Autopatch settings to fix on {bad} node{'s' if bad != 1 else ''}" if bad else
                     f"Autopatch settings look right on {len(rows)} node{'s' if len(rows) != 1 else ''}"),
        "rows": kv_rows,
        "table": {"head": ["Node", "Duplex", "Patch code", "Hang-up code", "quiet", "farenddisconnect", "noct", "Result"],
                  "rows": rows},
        "note": " · ".join(dict.fromkeys(notes))}}

_TS_DTMF = {
    "rfc4733": ("pass", "standard tone messages -- what most providers send"),
    "auto": ("pass", "tone messages when the provider offers them, else listens in the audio"),
    "auto_info": ("pass", "tone messages when offered, else SIP INFO"),
    "inband": ("warn", "read from the audio -- needs ulaw/alaw and a clean line; tones can be missed"),
    "info": ("warn", "SIP INFO messages only -- works only if the provider sends them that way"),
    "none": ("fail", "tones are switched off"),
}

def _ts_pjsip_ep_kv(ctx: dict, name: str) -> dict:
    secs = ctx["conf"]["pjsip.conf"]
    out: dict = {}
    for s in secs:
        if s["name"] != name or s["is_template"]:
            continue
        if _ph_last([s]).get("type", "").lower() != "endpoint":
            continue
        for tpl in s["templates"]:
            o2, _m, _f = _ph_resolve(secs, tpl)
            out.update(o2)
        for k, v, *_ in s["kv"]:
            out[k.strip().lower()] = v.strip()
    return out

def _ts_pjsip_ep_allow(ctx: dict, name: str, _depth: int = 0) -> list:
    secs = ctx["conf"]["pjsip.conf"]
    out: list = []
    if _depth > 5:
        return out
    for s_ in secs:
        if s_["name"] != name or (s_["is_template"] and _depth == 0):
            continue
        for tpl in s_["templates"]:
            out = _ts_pjsip_ep_allow(ctx, tpl, _depth + 1) or out
        for k, v, *_ in s_["kv"]:
            k = k.strip().lower()
            vals = [c.strip().lower() for c in re.split(r"[,&|\s]+", str(v)) if c.strip()]
            if k == "disallow" and "all" in vals:
                out = []
            elif k == "disallow":
                out = [c for c in out if c not in vals]
            elif k == "allow":
                out += [c for c in vals if c not in out]
    return out

@_ts("Phone", "ts_dtmfin", "Tone method")
def _ts_dtmfin():
    ctx = _ph_load_ctx()
    nets = _phone_sec_networks(ctx)["networks"]
    if not nets:
        return {"cmd": "pjsip.conf + iax.conf", "raw": "", "summary": {
            "status": "info", "headline": "No phone networks set up"}}
    running = _ph_ast_running()
    active = ctx["dash"].get("active", "")
    rows, notes, raw, need_info = [], [], [], False
    for n in nets:
        label = n["name"] + (" (picked)" if n["id"] == active else "")
        hoip = "hamsoverip" in str(n.get("host", "")).lower()
        if n["type"] == "iax2":
            rows.append([label, "IAX2", "-", "-", ["IAX2 carries the tones itself -- nothing to set", "pass"]])
            continue
        kv = _ts_pjsip_ep_kv(ctx, n["id"])
        conf = kv.get("dtmf_mode", "").split()[0].lower() if kv.get("dtmf_mode") else ""
        live, codecs = "", []
        conf_c = _ts_pjsip_ep_allow(ctx, n["id"])
        if running:
            out = _ph_cli(f"pjsip show endpoint {n['id']}", timeout=6)
            m = re.search(r"^\s*dtmf_mode\s*:\s*(\S+)", out, re.M)
            if m:
                live = m.group(1).lower()
            m = re.search(r"^\s*allow\s*:\s*\(?([^)\n]*)\)?", out, re.M)
            if m:
                codecs = [c.strip().lower() for c in re.split(r"[|,\s]+", m.group(1)) if c.strip()]
            raw.append(f"{n['id']}: pjsip.conf dtmf_mode={conf or '(not set)'}, Asterisk dtmf_mode={live or '?'}, "
                       f"codecs={'|'.join(codecs) or '?'}" + (" [Hams Over IP]" if hoip else ""))
        else:
            raw.append(f"{n['id']}: pjsip.conf dtmf_mode={conf or '(not set)'} allow={'|'.join(conf_c) or '(not set)'}")
        codecs = codecs or [c for c in conf_c if c != "all"]
        mode = live or conf or "rfc4733"
        shown = mode + ("" if live or conf else " (default)")
        st, txt = _TS_DTMF.get(mode, ("info", "unusual setting"))
        base_st = st
        stale = bool(live and conf and live != conf)
        if stale:
            txt += f" -- pjsip.conf says {conf}: Asterisk hasn't loaded it yet"
            st = _ts_worst([st, "warn"])
            notes.append(f"{n['name']}: pjsip.conf was changed but not loaded -- "
                         "asterisk -rx \"module reload res_pjsip.so\"")
        if mode in ("info", "auto_info"):
            need_info = True
        if hoip and mode != "rfc4733":
            txt += " -- Hams Over IP recommends rfc4733 (RFC 2833)"
            st = _ts_worst([st, "warn"])
            notes.append(f"{n['name']}: Hams Over IP wants rfc4733 -- set Tone mode to rfc4733 on the dashboard's Edit page")
        ctxt = "|".join(codecs[:4]) or "?"
        if codecs and "ulaw" not in codecs and "alaw" not in codecs:
            if mode in ("inband", "auto"):
                txt += " -- no ulaw/alaw, so tones in the audio get distorted"
                st = _ts_worst([st, "fail" if mode == "inband" else "warn"])
            if hoip:
                st = _ts_worst([st, "warn"])
                notes.append(f"{n['name']}: Hams Over IP pairs rfc4733 with ulaw -- allow=ulaw on its endpoint")
        elif hoip and codecs and codecs[0] != "ulaw":
            txt += f" -- {codecs[0]} is tried first; Hams Over IP pairs rfc4733 with ulaw"
            st = _ts_worst([st, "info"]) if st == "pass" else st
        rows.append([label, "SIP", shown, ctxt, [txt, st]])
        if base_st in ("warn", "fail") and not stale and not (hoip and mode != "rfc4733"):
            notes.append(f"{n['name']}: set its Tone mode on the dashboard's Edit page (rfc4733 suits most "
                         "providers), Save, then try *99 again")
    if need_info and running:
        if not _ph_module_running(_ph_cli("module show like res_pjsip_dtmf_info", 6), "res_pjsip_dtmf_info.so"):
            for r in rows:
                if r[2].startswith(("info", "auto_info")):
                    r[4] = [r[4][0] + " -- but res_pjsip_dtmf_info isn't running", "fail"]
            notes.append("Load res_pjsip_dtmf_info.so (modules.conf: load = res_pjsip_dtmf_info.so), then restart Asterisk")
    st = _ts_worst([r[4][1] for r in rows])
    if any("hamsoverip" in str(n.get("host", "")).lower() for n in nets):
        notes.append("To test Hams Over IP tones: call 3191 through the autopatch, wait for the beep, key some digits "
                     "then # -- it reads them back")
    return {"cmd": "pjsip show endpoint (each SIP network) + pjsip.conf", "raw": "\n".join(raw), "summary": {
        "status": st,
        "headline": ("Every network is set to pass keypad tones" if st == "pass" else
                     "Keypad tones may not reach Asterisk on some networks"),
        "table": {"head": ["Network", "Type", "Tone setting", "Codecs", "Result"], "rows": rows},
        "note": " · ".join(dict.fromkeys(notes)) or
                "This checks the setting only. If *99 still fails, the provider may not be sending tones the same way"}}

_TS_TX_READS, _TS_TX_GAP = 3, 4.0

@_ts("Phone", "ts_txstuck", "Transmitter stuck on")
def _ts_txstuck():
    if not _ph_ast_running():
        return _ts_missing("rpt xnode", "Asterisk is not running")
    nodes = [ln.strip() for ln in _ph_cli("rpt localnodes", 4).splitlines() if ln.strip().isdigit()]
    if not nodes:
        return {"cmd": "rpt localnodes", "raw": "", "summary": {"status": "info", "headline": "Asterisk runs no nodes"}}
    codes = dict(_ts_patch_nodes())
    reads: dict = {n: [] for n in nodes}
    raw = []
    for i in range(_TS_TX_READS):
        if i:
            time.sleep(_TS_TX_GAP)
        for n in nodes:
            v = _con_vars(_ph_cli(f"rpt xnode {n}", timeout=8))
            al = _con_alinks(v.get("RPT_ALINKS", ""))
            links_keyed = [x for x, _m, k in al if k]
            reads[n].append({"tx": v.get("RPT_TXKEYED") == "1", "rx": v.get("RPT_RXKEYED") == "1",
                             "ap": v.get("RPT_AUTOPATCHUP") == "1", "lk": links_keyed,
                             "links": [x for x, _m, _k in al], "ok": bool(v)})
            raw.append(f"read {i + 1} node {n}: TXKEYED={v.get('RPT_TXKEYED', '?')} RXKEYED={v.get('RPT_RXKEYED', '?')} "
                       f"AUTOPATCHUP={v.get('RPT_AUTOPATCHUP', '?')} keyed links={','.join(links_keyed) or 'none'}")
    calls = _ph_cli("core show channels concise", timeout=8)
    phone_up = any(ln.lower().startswith(("pjsip/", "sip/")) for ln in calls.splitlines())
    in_call = {n for n in nodes if phone_up and any(r["ap"] for r in reads[n])}
    rows, notes = [], []
    for n in nodes:
        rs = [r for r in reads[n] if r["ok"]]
        if not rs:
            rows.append([n, "?", "?", ["couldn't read this node", "info"]])
            continue
        on = sum(1 for r in rs if r["tx"])
        busy = any(r["rx"] or r["lk"] for r in rs)
        ap = any(r["ap"] for r in rs)
        came = sorted({x for r in rs for x in r["lk"]} | ({"its receiver"} if any(r["rx"] for r in rs) else set()))
        fed = sorted(in_call & {x for r in rs for x in r["links"]}) if n not in in_call else []
        if fed and not came:
            came = [f"phone call via {', '.join(fed)}"]
        tx_txt = f"{on} of {len(rs)} reads"
        if not on:
            res = ["not transmitting", "pass"]
        elif on < len(rs):
            res = ["on and off -- normal traffic", "pass"]
        elif busy:
            res = ["transmitting what's coming in", "pass"]
        elif ap and phone_up:
            res = ["transmitting for a phone call", "pass"]
        elif fed:
            res = [f"transmitting the phone call from {', '.join(fed)}", "pass"]
        elif ap:
            res = ["stuck on -- autopatch up with no phone call", "warn"]
            c = codes.get(n, "")
            notes.append(f"Node {n}: press Hang up stuck autopatch" + (f" (sends *{c})" if c else "") +
                         "; if it won't clear, restart Asterisk")
        else:
            res = ["stuck on -- nothing coming in for 8 seconds", "warn"]
            notes.append(f"Node {n}: run this again to be sure (a long ID can hold it); if it's still on, "
                         "sudo systemctl restart asterisk")
        rows.append([n, tx_txt, ", ".join(came) or ("autopatch" if ap else "nothing"), res])
    st = _ts_worst([r[3][1] for r in rows])
    stuck = sum(1 for r in rows if r[3][1] == "warn")
    notes.append("If a radio is on the air while this says it isn't, Asterisk doesn't know: the USB sound "
                 "card is holding the PTT line. Check its settings in the node's tune menu")
    return {"cmd": f"rpt xnode (each node, {_TS_TX_READS} reads {int(_TS_TX_GAP)} s apart) + core show channels",
            "raw": "\n".join(raw), "summary": {
                "status": st,
                "headline": (f"Transmitter stuck on at {stuck} node{'s' if stuck != 1 else ''}" if stuck else
                             "No transmitter stuck on"),
                "table": {"head": ["Node", "Transmitting", "Coming in", "Result"], "rows": rows},
                "note": " · ".join(dict.fromkeys(notes))}}

_DPX_SAMPLES = (("10 digits", "5135551234"), ("11 digits", "15135551234"), ("7 digits", "5551234"))

_DPX_DEAD_APPS = {"answer", "wait", "playback", "background", "noop", "verbose", "log", "hangup", "busy",
                  "congestion", "progress", "ringing", "set", "saydigits", "playtones", "stopplaytones"}

def _dpx_best(model: dict, ctx: str, ext: str) -> str:
    hits = _dpx_ext_match(model, ctx, ext)
    if not hits:
        return ""
    exact = [h for h in hits if not h.startswith("_")]
    if exact:
        return exact[0]

    def score(p):
        body = p[1:].split("/")[0]
        return (body.count(".") + body.count("!"), sum(1 for ch in body if ch in "XNZxnz["), -len(body))
    return sorted(hits, key=score)[0]

def _dpx_route(model: dict, ctx: str, num: str, accounts: dict, depth: int = 0, seen=None) -> dict:
    seen = seen or set()
    if (ctx, num) in seen or depth > 6:
        return {"status": "info", "path": [], "end": "goes round in a loop"}
    seen.add((ctx, num))
    if ctx not in model["ctxs"]:
        return {"status": "fail", "path": [], "end": f"[{ctx}] doesn't exist"}
    ext = _dpx_best(model, ctx, num)
    if not ext:
        return {"status": "none", "path": [], "end": f"no extension in [{ctx}] takes {num}"}
    here = f"[{ctx}] {ext}"
    steps = [s for s in model["steps"] if s["ctx"] == ctx and s["ext"] == ext]
    steps.sort(key=lambda s: (s["prio"] if s["prio"] is not None else 999))
    apps = []
    for s in steps:
        app = s["app"].lower()
        apps.append(app)
        args = _ts_expand(s["args"], num, [], model["globals"])
        if app == "dial":
            if "Local/" in args:
                m = re.search(r"Local/([^@/,&)\s]+)@([\w\-]+)", args)
                if m and "$" not in m.group(0):
                    sub = _dpx_route(model, m.group(2), m.group(1), accounts, depth + 1, seen)
                    if sub["status"] == "none":
                        sub = {"status": "fail", "path": [], "end": sub["end"] + " -- the call fails there"}
                    sub["path"] = [here] + sub["path"]
                    return sub
                return {"status": "info", "path": [here], "end": "dials a Local channel built at call time"}
            m = re.search(r"\b(PJSIP|IAX2|SIP)/([^,)&]+)", args, re.I)
            if not m:
                return {"status": "info", "path": [here], "end": f"Dial({args[:40]})"}
            tech, target = m.group(1).upper(), m.group(2)
            if tech == "PJSIP":
                acct = target.split("@")[1] if "@" in target else target.split("/")[0]
                ok = acct in accounts["pjsip"]
            elif tech == "IAX2":
                first = target.split("/")[0]
                acct = first.split("@")[-1] if "@" in first else first
                ok = acct in accounts["iax2"] or "@" in first or "." in acct
            else:
                acct, ok = target.split("/")[0], True
            if "$" in acct:
                return {"status": "info", "path": [here], "end": f"Dial {tech} to an account set at call time"}
            if not ok:
                return {"status": "fail", "path": [here],
                        "end": f"Dial {tech}/{acct} -- no such account in {'pjsip.conf' if tech == 'PJSIP' else 'iax.conf'}"}
            return {"status": "pass", "path": [here], "end": f"Dial {tech} via {acct}"}
        if app == "rpt":
            return {"status": "info", "path": [here], "end": "hands the call to a node (rpt)"}
        if app in ("goto", "gotoif", "gosub", "gosubif"):
            targets = _dpx_jumps({"app": s["app"], "args": args})
            results = []
            for tctx, text, _tp in targets:
                if "$" in tctx + text:
                    results.append({"status": "info", "path": [here], "end": f"{s['app']} to a place set at call time"})
                    continue
                if not tctx and not text:
                    continue
                sub = _dpx_route(model, tctx or ctx, text or num, accounts, depth + 1, set(seen))
                if sub["status"] == "none":
                    sub = {"status": "fail", "path": [], "end": sub["end"] + " -- the call fails there"}
                sub["path"] = [here] + sub["path"]
                results.append(sub)
            if results:
                rank = {"pass": 0, "fail": 1, "warn": 2, "info": 3, "none": 4}
                best = sorted(results, key=lambda r: rank.get(r["status"], 5))[0]
                if app in ("goto", "gosub") or best["status"] == "pass":
                    return best
    if apps and all(a in _DPX_DEAD_APPS for a in apps):
        played = "plays a message and hangs up" if any(a in ("playback", "background") for a in apps) else "hangs up"
        return {"status": "warn", "path": [here], "end": played + " -- no call is placed"}
    return {"status": "info", "path": [here], "end": "ends without a Dial (" + ", ".join(dict.fromkeys(apps)) + ")"}

@_ts("Phone", "ts_aproutes", "Autopatch routes")
def _ts_aproutes():
    scan = _dpx_scan()
    if "extensions.conf" not in scan["files"]:
        return _ts_missing("extensions.conf", "extensions.conf could not be read")
    model = _dpx_model(scan)
    ctx = _ph_load_ctx()
    refs = [r for r in _dpx_conf_refs(ctx) if r[4].startswith("autopatch")]
    if not refs:
        return {"cmd": "rpt.conf autopatch lines", "raw": "", "summary": {
            "status": "info", "headline": "No node has an autopatch code"}}
    accounts = {"pjsip": {s["name"] for s in ctx["conf"]["pjsip.conf"] if s["name"] and not s["is_template"]},
                "iax2": {s["name"] for s in ctx["conf"]["iax.conf"] if s["name"] and not s["is_template"]}}
    by_ctx: dict = {}
    for _f, _l, sec, cname, _w in refs:
        by_ctx.setdefault(cname, []).append(sec.split()[0])
    rows, raw, notes = [], [], []
    for cname, nodes in by_ctx.items():
        who = f"[{cname}] (node{'s' if len(nodes) != 1 else ''} {', '.join(nodes)})"
        if cname not in model["ctxs"]:
            rows.append([who, "-", f"[{cname}] doesn't exist", ["no calls can be placed", "fail"]])
            notes.append(f"Add [{cname}] to extensions.conf (or fix the autopatch context=)")
            continue
        results = []
        for label, num in _DPX_SAMPLES:
            r = _dpx_route(model, cname, num, accounts)
            results.append((label, num, r))
            raw.append(f"{cname} {num}: " + " -> ".join(r["path"] + [r["end"]]))
        taken = [x for x in results if x[2]["status"] != "none"]
        if not taken:
            rows.append([who, "all three", "no extension takes any of them", ["calls get 'invalid number'", "fail"]])
            notes.append(f"[{cname}] needs a pattern for the numbers you dial, e.g. _1NXXNXXXXXX and _NXXNXXXXXX")
            continue
        for label, num, r in results:
            if r["status"] == "none":
                rows.append([who, f"{label} ({num})", "not taken", ["fine if you never dial this length", "info"]])
                continue
            path = " → ".join(r["path"][1:] + [r["end"]]) if len(r["path"]) > 1 else r["end"]
            res_txt = {"pass": "places the call", "fail": "call fails", "warn": "no call is placed",
                       "info": "can't tell from the file"}[r["status"]]
            rows.append([who, f"{label} ({num})", path, [res_txt, r["status"]]])
            if r["status"] == "warn":
                notes.append(f"[{cname}]: the route ends in a message, like ASL3's stock 'no service' "
                             "[pstn-out] -- point it at a Dial() to your phone network")
            if r["status"] == "fail":
                notes.append(f"[{cname}]: {r['end']}")
    st = _ts_worst([r[3][1] for r in rows])
    ok = sum(1 for r in rows if r[3][1] == "pass")
    return {"cmd": "rpt.conf autopatch context + extensions.conf (sample numbers)", "raw": "\n".join(raw), "summary": {
        "status": st,
        "headline": ("Autopatch calls reach a phone network" if st == "pass" else
                     "Some autopatch calls won't go out" if st in ("fail", "warn") else
                     f"{ok} sample number{'s' if ok != 1 else ''} reach a phone network"),
        "table": {"head": ["Autopatch context", "Number tried", "Where it goes", "Result"], "rows": rows},
        "note": " · ".join(dict.fromkeys(notes))}}

def _ts_norm(msg: str) -> str:
    s = re.sub(r"0x[0-9a-fA-F]+", "#", msg)
    s = re.sub(r"\d+(\.\d+)*", "#", s)
    s = re.sub(r"'[^']{0,60}'", "'…'", s)
    return re.sub(r"\s+", " ", s).strip()[:140]

@_ts("Asterisk", "ts_errors", "Recent errors")
def _ts_errors():
    txt, where, prob = _ts_ast_log(60)
    if prob:
        return _ts_missing("Asterisk log, last hour", prob)
    groups: dict = {}
    for ln in txt.splitlines():
        m = re.search(r"\b(ERROR|WARNING)\[\d+\][^:]*:\s*(?:\S+\.c:\d+\s+\S+:\s*)?(.*)$", ln)
        if not m:
            continue
        key = (m.group(1), _ts_norm(m.group(2)))
        g = groups.setdefault(key, {"n": 0, "last": "", "ex": m.group(2).strip()[:160]})
        g["n"] += 1
        g["last"] = _ts_time(ln)
    if not groups:
        return {"cmd": where, "raw": txt[-3000:], "summary": {"status": "pass", "headline": "No warnings or errors in the last hour"}}
    items = sorted(groups.items(), key=lambda kv: (kv[0][0] != "ERROR", -kv[1]["n"]))
    rows = [[[lvl.lower(), "fail" if lvl == "ERROR" else "warn"], str(g["n"]), g["last"], g["ex"]] for (lvl, _k), g in items[:15]]
    errs = sum(g["n"] for (lvl, _k), g in groups.items() if lvl == "ERROR")
    warns = sum(g["n"] for (lvl, _k), g in groups.items() if lvl == "WARNING")
    return {"cmd": where, "raw": "\n".join(f"{g['n']:5d}x {lvl}: {g['ex']}" for (lvl, _k), g in items),
            "summary": {"status": "fail" if errs else "warn",
                        "headline": f"{errs} error{'s' if errs != 1 else ''}, {warns} warning{'s' if warns != 1 else ''} "
                                    f"({len(groups)} different message{'s' if len(groups) != 1 else ''})",
                        "table": {"head": ["Level", "Times", "Last", "Message (example)"], "rows": rows},
                        "note": "Repeated identical warnings are often harmless noise; look at errors and anything new first"}}

@_ts("Asterisk", "ts_restarts", "Restarts and crashes")
def _ts_restarts():
    out, prob = _ts_journal("asterisk", "24 hours ago", 50000)
    if prob:
        return _ts_missing("journalctl -u asterisk", prob)
    if not out.strip() or "-- No entries --" in out:
        return {"cmd": "journalctl -u asterisk --since '24 hours ago'", "raw": out,
                "summary": {"status": "info", "headline": "No Asterisk entries in the journal for 24 hours",
                            "note": "Asterisk may not run as a systemd service named asterisk here"}}
    rows, crash = [], 0
    for ln in out.splitlines():
        msg = _ts_msg(ln)
        ev, st = "", ""
        if re.search(r"(?i)core-dump|code=(killed|dumped)|signal=(SEGV|ABRT|BUS|ILL|FPE)|segfault", msg):
            ev, st = "crashed", "fail"
        elif re.search(r"(?i)Failed with result|failed\.$", msg):
            ev, st = "failed", "fail"
        elif re.search(r"(?i)^Started |Asterisk Ready|Asterisk .* Ready", msg):
            ev, st = "started", "pass"
        elif re.search(r"(?i)^Stopped |^Stopping |Asterisk cleanly ending|Executing last minute cleanups", msg):
            ev, st = "stopped", ""
        elif re.search(r"(?i)Scheduled restart job", msg):
            ev, st = "auto-restarted", "warn"
        if ev:
            if st == "fail":
                crash += 1
            rows.append([_ts_time(ln), [ev, st], msg[:120]])
    if not rows:
        return {"cmd": "journalctl -u asterisk --since '24 hours ago'", "raw": out[-3000:],
                "summary": {"status": "pass", "headline": "No restarts or crashes in 24 hours"}}
    starts = sum(1 for r in rows if r[1][0] == "started")
    return {"cmd": "journalctl -u asterisk --since '24 hours ago'", "raw": "\n".join(r[2] for r in rows), "summary": {
        "status": "fail" if crash else ("warn" if starts > 3 else "info"),
        "headline": (f"{crash} crash{'es' if crash != 1 else ''} · " if crash else "") + f"{starts} start{'s' if starts != 1 else ''} in 24 h",
        "table": {"head": ["Time", "Event", "Log line"], "rows": rows[::-1][:30]},
        "note": "A crash means Asterisk died and was restarted by systemd; Recent errors around that time may show why" if crash else ""}}

@_ts("Asterisk", "ts_logging", "Logging check")
def _ts_logging():
    p_ = Path("/etc/asterisk/logger.conf")
    try:
        txt = p_.read_text(errors="replace")
    except OSError:
        return _ts_missing(str(p_), "logger.conf not found")
    chans = {}
    in_logfiles = False
    for raw in txt.splitlines():
        ln = raw.split(";", 1)[0].strip()
        m = re.match(r"^\[([^\]]+)\]", ln)
        if m:
            in_logfiles = m.group(1).strip().lower() == "logfiles"
            continue
        if in_logfiles and "=>" in ln:
            k, v = (x.strip() for x in ln.split("=>", 1))
            chans[k] = [x.strip().lower() for x in v.split(",")]
    live = _ph_cli("logger show channels", timeout=6) if _ph_ast_running() else ""
    rows = [[k, ", ".join(v)] for k, v in chans.items()]
    full = chans.get("full", [])
    ok = "verbose" in full or "*" in full
    return {"cmd": f"{p_} + logger show channels", "raw": "\n".join([txt.strip()[-2500:], "", live.strip()]), "summary": {
        "status": "pass" if ok else "warn",
        "headline": "Call history logging is on" if ok else "Call history logging is off",
        "rows": rows,
        "note": "" if ok else ("Add or change this line under [logfiles] in /etc/asterisk/logger.conf:  "
                               "full => notice,warning,error,verbose  -- then run: asterisk -rx \"logger reload\". "
                               "It grows quickly on an SD card, so turn it off again after testing")}}

def _dpx_where(st: dict) -> str:
    return f"{st['file']}:{st['line']}" + (" (dashboard)" if st.get("managed") else "")

@_ts("Asterisk", "ts_dpfile", "Dialplan file")
def _ts_dpfile():
    scan = _dpx_scan()
    if "extensions.conf" not in scan["files"]:
        return _ts_missing("extensions.conf", "extensions.conf could not be read")
    model = _dpx_model(scan)
    issues = list(model["issues"])
    ctxs = model["ctxs"]
    for miss in scan["missing"]:
        st = {"file": miss["where"].split(":")[0], "line": int(miss["where"].split(":")[1]), "ctx": "",
              "managed": False}
        if miss["optional"]:
            issues.append((st, f"#tryinclude {miss['file']} -- file isn't there (optional, skipped)", "info"))
        else:
            issues.append((st, f"#include {miss['file']} -- file isn't there; use #tryinclude if it's optional",
                           "fail"))
    for name, c in ctxs.items():
        if len(c["places"]) > 1:
            st = c["places"][1]
            issues.append((st, f"[{name}] is also written at {_dpx_where(c['places'][0])} -- Asterisk joins "
                               "them; a repeated extension + priority is dropped", "info"))
        for pat, e in c["exts"].items():
            if e["prios"] and 1 not in e["prios"]:
                issues.append((e["first"], f"'{pat}' starts at priority {min(e['prios'])}, not 1 -- calls to "
                                           "it do nothing", "warn"))
            bare = pat.split("/")[0]
            if bare == "_.":
                issues.append((e["first"], "'_.' also catches Asterisk's special h, i and t extensions -- "
                                           "Asterisk suggests _X.", "info"))
            elif (not bare.startswith("_") and "${" not in bare and len(bare) >= 3
                  and re.fullmatch(r"[0-9XNZxnz.!\[\]\-*#+]+", bare) and re.search(r"[XNZxnz.!\[]", bare)):
                issues.append((e["first"], f"pattern '{bare}' has no leading _ -- it only matches those exact "
                                           f"letters; write _{bare}", "warn"))
    for step in model["steps"]:
        st = step["stmt"]
        args = step["args"]
        bal = []
        body = re.sub(r"\\.", "", args)
        for a, b in (("(", ")"), ("{", "}"), ("[", "]")):
            if body.count(a) != body.count(b):
                bal.append(f"{a} {b}")
        if body.count('"') % 2:
            bal.append("quotes")
        if bal:
            issues.append((st, f"{step['app']}(): unbalanced " + ", ".join(bal), "warn"))
        for tctx, text, tpri in _dpx_jumps(step):
            if any("$" in x for x in (tctx, text, tpri)):
                continue
            c_name = tctx or step["ctx"]
            if c_name not in ctxs:
                issues.append((st, f"{step['app']} goes to context [{c_name}], which doesn't exist", "fail"))
                continue
            if text:
                hits = _dpx_ext_match(model, c_name, text)
                if not hits:
                    issues.append((st, f"{step['app']} goes to '{text}' in [{c_name}] -- no extension there "
                                       "takes it", "warn"))
                    continue
            else:
                hits = [step["ext"]]
            if tpri and not tpri.isdigit():
                if not any(tpri in ctxs[c_name]["exts"].get(h, {}).get("labels", {}) for h in hits):
                    issues.append((st, f"{step['app']} goes to label '{tpri}', which isn't in "
                                       f"'{hits[0]}' of [{c_name}]", "warn"))
    for st, name in model["includes"]:
        if "$" not in name and name not in ctxs:
            issues.append((st, f"include => {name} -- context doesn't exist", "fail"))
    order = {"fail": 0, "warn": 1, "info": 2}
    issues.sort(key=lambda x: (order.get(x[2], 3), x[0]["file"], x[0]["line"]))
    rows = [[_dpx_where(st), st.get("ctx") or "", msg, [{"fail": "error", "warn": "check", "info": "note"}[s], s]]
            for st, msg, s in issues]
    raw = [f"files read: {', '.join(scan['files'])}"] + [f"{s.upper():5} {_dpx_where(st)} [{st.get('ctx') or ''}] "
                                                         f"{msg}" for st, msg, s in issues] + scan["errors"]
    nfail = sum(1 for i in issues if i[2] == "fail")
    nwarn = sum(1 for i in issues if i[2] == "warn")
    nsteps = len(model["steps"])
    if not issues:
        return {"cmd": "extensions.conf + #includes", "raw": "\n".join(raw), "summary": {
            "status": "pass", "headline": f"No mistakes found ({len(ctxs)} contexts, {nsteps} steps, "
                                          f"{len(scan['files'])} file{'s' if len(scan['files']) != 1 else ''})"}}
    st = "fail" if nfail else "warn" if nwarn else "info"
    head = (f"{nfail} error{'s' if nfail != 1 else ''}, {nwarn} to check" if nfail or nwarn else
            f"{len(issues)} note{'s' if len(issues) != 1 else ''}, nothing wrong")
    return {"cmd": "extensions.conf + #includes", "raw": "\n".join(raw), "summary": {
        "status": st, "headline": head,
        "table": {"head": ["Where", "Context", "Problem", "Level"], "rows": rows[:40]},
        "note": ("Lines marked (dashboard) are written by the dashboard -- change them there, not by hand. "
                 if any(i[0].get("managed") for i in issues) else "") +
                (f"Showing 40 of {len(rows)}; Show full output has the rest. " if len(rows) > 40 else "") +
                "After fixing a line: asterisk -rx \"dialplan reload\""}}

@_ts("Asterisk", "ts_dplinks", "Dialplan links")
def _ts_dplinks():
    scan = _dpx_scan()
    if "extensions.conf" not in scan["files"]:
        return _ts_missing("extensions.conf", "extensions.conf could not be read")
    model = _dpx_model(scan)
    ctxs = model["ctxs"]
    ctx = _ph_load_ctx()
    refs = _dpx_conf_refs(ctx)
    rows, missing = [], {}
    for fname, line, sec, cname, what in refs:
        where = f"{fname}:{line}" if line else fname
        if not cname:
            res = ["context= is empty", "warn"]
        elif cname not in ctxs:
            res = ["doesn't exist -- calls here go nowhere", "fail"]
            missing.setdefault(cname, []).append(f"{fname} [{sec}]")
        elif not ctxs[cname]["exts"] and not any(s["ctx"] == cname for s, _n in model["includes"]):
            res = ["exists but has no extensions", "warn"]
        else:
            res = [f"ok ({len(ctxs[cname]['exts'])} extension{'s' if len(ctxs[cname]['exts']) != 1 else ''})", "pass"]
        rows.append([where, f"{what}: [{sec}]", cname or "-", res])
    used = {r[3] for r in refs if r[3]}
    prefixes = []
    for st, name in model["includes"]:
        used.add(name)
    for step in model["steps"]:
        for tctx, _e, _p in _dpx_jumps(step):
            if not tctx:
                continue
            if "$" in tctx:
                prefixes.append(tctx.split("$")[0])
            else:
                used.add(tctx)
    unused = sorted(c for c in ctxs if c not in used and c.lower() not in ("general", "globals", "default")
                    and not any(p and c.startswith(p) for p in prefixes))
    kv_rows = []
    if unused:
        kv_rows.append(["Contexts nothing points at", ", ".join(unused[:30]) + (" …" if len(unused) > 30 else "")])
    notes = [f"[{c}] is named by {', '.join(w)} -- add it to extensions.conf or fix those context= lines"
             for c, w in missing.items()]
    raw = [f"{r[0]}  {r[1]}  -> [{r[2]}]  {r[3][0]}" for r in rows]
    if unused:
        raw.append("not pointed at: " + ", ".join(unused))
    if not rows:
        return {"cmd": "pjsip.conf, iax.conf, rpt.conf context= vs extensions.conf", "raw": "\n".join(raw),
                "summary": {"status": "info", "headline": "No other file names a dialplan context", "rows": kv_rows}}
    st = _ts_worst([r[3][1] for r in rows])
    bad = sum(1 for r in rows if r[3][1] in ("fail", "warn"))
    return {"cmd": "pjsip.conf, iax.conf, echolink.conf, rpt.conf context= vs extensions.conf",
            "raw": "\n".join(raw), "summary": {
        "status": st,
        "headline": (f"{bad} of {len(rows)} context= lines point at a missing or empty context" if bad else
                     f"All {len(rows)} context= lines point at a real context"),
        "rows": kv_rows,
        "table": {"head": ["Where", "Named by", "Context", "Result"], "rows": rows},
        "note": " · ".join(dict.fromkeys(notes)) or
                ("Contexts nothing points at are usually leftovers or stock examples -- harmless" if unused else "")}}

_DPX_APP_MOD = {"senddtmf": "app_senddtmf.so", "rpt": "app_rpt.so", "dial": "app_dial.so",
                "playback": "app_playback.so", "read": "app_read.so", "echo": "app_echo.so",
                "voicemail": "app_voicemail.so", "voicemailmain": "app_voicemail.so", "record": "app_record.so",
                "verbose": "app_verbose.so", "log": "app_verbose.so", "gosub": "app_stack.so",
                "return": "app_stack.so", "system": "app_system.so", "exec": "app_exec.so",
                "execif": "app_exec.so", "authenticate": "app_authenticate.so", "confbridge": "app_confbridge.so",
                "page": "app_page.so", "morsecode": "app_morsecode.so", "while": "app_while.so",
                "endwhile": "app_while.so", "saycountedadj": "app_saycounted.so", "milliwatt": "app_milliwatt.so",
                "sayunixtime": "app_sayunixtime.so", "originate": "app_originate.so", "mixmonitor": "app_mixmonitor.so"}

_DPX_FUNC_MOD = {"DB": "func_db.so", "DB_EXISTS": "func_db.so", "DB_KEYCOUNT": "func_db.so",
                 "DB_DELETE": "func_db.so", "DB_KEYS": "func_db.so", "CALLERID": "func_callerid.so",
                 "CURL": "func_curl.so", "LEN": "func_strings.so", "ISNULL": "func_logic.so",
                 "IF": "func_logic.so", "IFTIME": "func_logic.so", "EXISTS": "func_logic.so",
                 "CUT": "func_cut.so", "SHELL": "func_shell.so", "STRFTIME": "func_strings.so",
                 "REGEX": "func_strings.so", "FILTER": "func_strings.so", "ENV": "func_env.so",
                 "GLOBAL": "func_global.so", "RAND": "func_rand.so", "CHANNEL": "func_channel.so",
                 "PJSIP_HEADER": "res_pjsip_header_funcs.so", "PJSIP_ENDPOINT": "res_pjsip.so"}

_DPX_LOG_RE = re.compile(r"(?i)(invalid priority|label missing trailing|unable to register extension|"
                         r"can't use '(?:next|same)' priority|no application '|function \S+ not registered|"
                         r"sent to invalid extension|cannot find specified system node|"
                         r"found no matching peer or user|unable to include|strongly discouraged|"
                         r"no such extension|is not a valid extension)")

def _dpx_funcs_used(step: dict) -> set:
    out = set(re.findall(r"\$\{([A-Z][A-Z0-9_]*)\(", step["args"]))
    if step["app"].lower() in ("set", "mset"):
        for m in re.finditer(r"(?:^|,)\s*([A-Z][A-Z0-9_]*)\([^=]*\)\s*=", step["args"]):
            out.add(m.group(1))
    return out

def _dpx_loaded(text: str) -> dict:
    out, cur = {}, None
    for ln in text.splitlines():
        m = re.match(r"^\[ Context '([^']+)' created by '([^']+)' \]", ln)
        if m:
            cur = m.group(1) if m.group(2) == "pbx_config" else None
            if cur is not None:
                out.setdefault(cur, set())
            continue
        if cur is None:
            continue
        m = re.match(r"^\s*'([^']+)'\s*(?:\(CID match '[^']*'\))?\s*=>", ln)
        if m:
            out[cur].add(m.group(1))
    return out

@_ts("Asterisk", "ts_dploaded", "Dialplan loaded")
def _ts_dploaded():
    scan = _dpx_scan()
    if "extensions.conf" not in scan["files"]:
        return _ts_missing("extensions.conf", "extensions.conf could not be read")
    if not _ph_ast_running():
        return _ts_missing("core show applications / dialplan show", "Asterisk is not running")
    model = _dpx_model(scan)
    rows, notes, raw = [], [], []
    apps_out = _ph_cli("core show applications", 10)
    have_apps = {m.group(1).lower() for m in re.finditer(r"^\s*([A-Za-z_]\w*):\s", apps_out, re.M)}
    funcs_out = _ph_cli("core show functions", 10)
    have_funcs = {m.group(1) for m in re.finditer(r"^\s*([A-Z][A-Z0-9_]*)\s{2,}\S", funcs_out, re.M)}
    used_apps: dict = {}
    used_funcs: dict = {}
    for step in model["steps"]:
        used_apps.setdefault(step["app"].lower(), (step["app"], step["stmt"]))
        for f in _dpx_funcs_used(step):
            used_funcs.setdefault(f, step["stmt"])
    raw.append(f"apps used: {', '.join(sorted(a for a, _s in used_apps.values()))}")
    raw.append(f"functions used: {', '.join(sorted(used_funcs))}")
    if len(have_apps) < 10:
        rows.append(["Apps", "couldn't read core show applications", ["not checked", "info"]])
    else:
        miss = [(name, st) for low, (name, st) in sorted(used_apps.items()) if low not in have_apps]
        for name, st in miss:
            mod = _DPX_APP_MOD.get(name.lower(), "")
            rows.append([f"App {name}", f"first used at {_dpx_where(st)}",
                         ["not loaded -- calls stop at this step", "fail"]])
            notes.append(f"Load {mod or 'the module that provides ' + name} (modules.conf: load = "
                         f"{mod or 'app_' + name.lower() + '.so'}), then restart Asterisk")
        if not miss:
            rows.append(["Apps", f"all {len(used_apps)} used are loaded", ["ok", "pass"]])
    if len(have_funcs) < 10:
        rows.append(["Functions", "couldn't read core show functions", ["not checked", "info"]])
    else:
        missf = [(f, st) for f, st in sorted(used_funcs.items()) if f not in have_funcs]
        for f, st in missf:
            mod = _DPX_FUNC_MOD.get(f, "")
            rows.append([f"Function {f}()", f"first used at {_dpx_where(st)}",
                         ["not loaded -- it returns nothing", "fail"]])
            notes.append(f"Load {mod or 'the module that provides ' + f + '()'}" +
                         (f" (modules.conf: load = {mod})" if mod else "") + ", then restart Asterisk")
        if not missf:
            rows.append(["Functions", f"all {len(used_funcs)} used are loaded", ["ok", "pass"]])
    shown = _ph_cli("dialplan show", 15)
    loaded = _dpx_loaded(shown)
    glb = model["globals"]
    diffs = 0
    if not loaded:
        rows.append(["Loaded dialplan", "couldn't read dialplan show", ["not checked", "info"]])
    else:
        for cname, c in model["ctxs"].items():
            if cname.lower() in ("general", "globals"):
                continue
            want = {_dpx_glb_expand(p, glb).split("/")[0] for p in c["exts"]}
            want = {w for w in want if "${" not in w}
            if not want:
                continue
            if cname not in loaded:
                diffs += 1
                where = _dpx_where(c["places"][0]) if c["places"] else ""
                rows.append([f"[{cname}]", f"in the file ({where}) but not loaded",
                             ["not loaded -- reload, or a line above it broke the file", "warn"]])
                continue
            got = loaded[cname]
            gone = sorted(want - got)
            extra = sorted(got - want)
            if gone:
                diffs += 1
                rows.append([f"[{cname}]", "in the file, not loaded: " + ", ".join(gone[:8]),
                             ["not loaded -- bad line, or changed and not reloaded", "warn"]])
            if extra:
                diffs += 1
                rows.append([f"[{cname}]", "loaded, no longer in the file: " + ", ".join(extra[:8]),
                             ["file changed since the last reload", "info"]])
        if not diffs:
            rows.append(["Loaded dialplan", f"matches the file ({len(loaded)} contexts loaded)", ["ok", "pass"]])
    up = _ph_cli("core show uptime seconds", 5)
    m = re.search(r"Last reload:\s*(\d+)", up)
    if m:
        last = time.time() - int(m.group(1))
        newer = []
        for fname in scan["files"]:
            p = Path(fname) if fname.startswith("/") else scan["base"] / fname
            try:
                if p.stat().st_mtime > last + 2:
                    newer.append(fname)
            except OSError:
                pass
        if newer:
            rows.append(["Saved after last reload", ", ".join(newer),
                         ["loaded copy matches anyway" if not diffs else "reload to use the changes",
                          "info" if not diffs else "warn"]])
            if diffs:
                notes.append("Load the saved file: asterisk -rx \"dialplan reload\"")
        raw.append(f"last reload {int(m.group(1))} s ago")
    txt, where, prob = _ts_ast_log(1440)
    groups: dict = {}
    for ln in (txt or "").splitlines():
        if not _DPX_LOG_RE.search(ln):
            continue
        msg = re.sub(r"^\S+\.c:\d+\s+\S+:\s*", "", _ts_msg(ln))
        g = groups.setdefault(_ts_norm(msg), {"n": 0, "last": "", "ex": msg.strip()[:160]})
        g["n"] += 1
        g["last"] = _ts_time(ln)
    for k, g in sorted(groups.items(), key=lambda kv: -kv[1]["n"])[:10]:
        rows.append([f"Log: {g['n']}× (last {g['last']})", g["ex"], ["dialplan warning in the log", "warn"]])
    if prob:
        rows.append(["Log", prob, ["not checked", "info"]])
    elif not groups:
        rows.append(["Log", "no dialplan warnings in the last 24 hours", ["ok", "pass"]])
    raw.append(f"log: {where or prob}")
    st = _ts_worst([r[2][1] for r in rows])
    bad = sum(1 for r in rows if r[2][1] in ("fail", "warn"))
    return {"cmd": "core show applications / functions, dialplan show, core show uptime, Asterisk log (24 h)",
            "raw": "\n".join(raw), "summary": {
        "status": st,
        "headline": "Couldn't read what Asterisk has loaded" if st == "info" else
                    "What Asterisk loaded matches the file and everything it uses is there" if not bad else
                    f"{bad} problem{'s' if bad != 1 else ''} between the file and what Asterisk is running",
        "table": {"head": ["What", "Details", "Result"], "rows": rows},
        "note": " · ".join(dict.fromkeys(notes))}}

def _dpx_db_reads(args: str) -> list:
    out, i = [], 0
    while True:
        i = args.find("${DB(", i)
        if i < 0:
            return out
        j, depth = i + 5, 1
        while j < len(args) and depth:
            if args[j] == "(":
                depth += 1
            elif args[j] == ")":
                depth -= 1
            j += 1
        out.append(args[i + 5:j - 1].strip())
        i = j

@_ts("Asterisk", "ts_dbvals", "Saved values")
def _ts_dbvals():
    scan = _dpx_scan()
    if "extensions.conf" not in scan["files"]:
        return _ts_missing("extensions.conf", "extensions.conf could not be read")
    model = _dpx_model(scan)
    reads: dict = {}
    for step in model["steps"]:
        for key in _dpx_db_reads(step["args"]):
            k = _dpx_glb_expand(key, model["globals"]).strip("/")
            reads.setdefault(k, []).append(step["stmt"])
    running = _ph_ast_running()
    stored: set = set()
    raw = []
    if running:
        fams = sorted({k.split("/")[0] for k in reads if "/" in k and "$" not in k.split("/")[0]})
        for fam in fams:
            out = _ph_cli(f"database show {fam}", 6)
            stored |= {m.group(1).strip("/") for m in re.finditer(r"^(/\S+?)\s*:", out, re.M)}
            raw.append(f"database show {fam}: {sum(1 for s in stored if s.startswith(fam + '/'))} keys")
    txt, _where, _prob = _ts_ast_log(1440)
    logmiss: dict = {}
    for ln in (txt or "").splitlines():
        m = re.search(r"AstDB key (/\S+) does not exist", ln)
        if m:
            k = m.group(1).strip("/")
            logmiss[k] = logmiss.get(k, 0) + 1
    rows, notes = [], []
    for k, sts in sorted(reads.items()):
        where = _dpx_where(sts[0]) + (f" +{len(sts) - 1} more" if len(sts) > 1 else "")
        n = logmiss.get(k, 0)
        logtxt = f"{n}× in 24 h" if n else "-"
        if "$" in k:
            fixed = k.split("$")[0]
            cnt = sum(1 for s in stored if s.startswith(fixed)) if running else None
            rows.append([where, "/" + k, logtxt, [("built at call time -- " + (f"{cnt} stored under /{fixed}"
                         if cnt is not None else "can't check")), "info"]])
        elif not running:
            rows.append([where, "/" + k, logtxt, ["can't check -- Asterisk isn't running", "info"]])
        elif k in stored:
            rows.append([where, "/" + k, logtxt, ["stored", "pass"]])
        else:
            rows.append([where, "/" + k, logtxt, ["read but not stored -- Asterisk logs a warning each time", "warn"]])
            dash = any(s.get("managed") for s in sts)
            notes.append(f"/{k} is read at {_dpx_where(sts[0])} but never stored" +
                         (" -- that line is the dashboard's: it should store a blank value or check DB_EXISTS "
                          "first (dashboard fix)" if dash else
                          f" -- wrap it as ${{IF(${{DB_EXISTS({k})}}?${{DB_RESULT}})}} or store a value"))
    for k, n in sorted(logmiss.items()):
        if k not in reads and not any("$" in r and k.startswith(r.split("$")[0]) for r in reads):
            rows.append(["(not in the dialplan)", "/" + k, f"{n}× in 24 h",
                         ["read by something outside the dialplan", "info"]])
    if not rows:
        return {"cmd": "extensions.conf ${DB()} reads + database show", "raw": "\n".join(raw), "summary": {
            "status": "pass", "headline": "The dialplan reads no saved values"}}
    st = _ts_worst([r[3][1] for r in rows])
    bad = sum(1 for r in rows if r[3][1] == "warn")
    return {"cmd": "extensions.conf ${DB()} reads + database show + Asterisk log (24 h)", "raw": "\n".join(raw),
            "summary": {
        "status": st,
        "headline": ("Can't check the stored values -- Asterisk isn't running" if not running else
                     f"{bad} saved value{'s' if bad != 1 else ''} read but never stored" if bad else
                     f"All {len(rows)} saved values the dialplan reads are there"),
        "table": {"head": ["Read at", "Key", "Log warnings", "Result"], "rows": rows},
        "note": " · ".join(dict.fromkeys(notes)) or "Values aren't shown -- some hold PINs"}}

_TS_THROTTLE_BITS = ((0, "Low voltage right now", "fail"), (1, "CPU speed capped right now", "warn"),
                     (2, "Throttled right now", "warn"), (3, "Temperature limit right now", "warn"),
                     (16, "Low voltage has happened since boot", "warn"), (17, "CPU speed was capped since boot", "info"),
                     (18, "Was throttled since boot", "info"), (19, "Hit the temperature limit since boot", "info"))

def _ts_throttle(val: int) -> list:
    return [(txt, st) for bit, txt, st in _TS_THROTTLE_BITS if val & (1 << bit)]

@_ts("Pi health", "ts_power", "Power and heat")
def _ts_power():
    raw, rows = [], []
    temp = None
    try:
        temp = int(Path("/sys/class/thermal/thermal_zone0/temp").read_text().strip()) / 1000.0
    except (OSError, ValueError):
        pass
    out, prob = _ts_cmd(["vcgencmd", "get_throttled"], 5)
    raw.append(f"$ vcgencmd get_throttled\n{out.strip() or prob}")
    worst = "pass"
    rank = {"pass": 0, "info": 1, "warn": 2, "fail": 3}
    flags = []
    if not prob:
        m = re.search(r"throttled=(0x[0-9a-fA-F]+)", out)
        if m:
            val = int(m.group(1), 16)
            flags = _ts_throttle(val)
            rows.append(["Flags", f"{m.group(1)}" + (" (all clear)" if not val else "")])
            for txt, st in flags:
                rows.append(["", txt])
                if rank[st] > rank[worst]:
                    worst = st
    v, _p = _ts_cmd(["vcgencmd", "measure_volts", "core"], 5)
    if v.strip():
        raw.append(f"$ vcgencmd measure_volts core\n{v.strip()}")
        rows.append(["Core voltage", v.strip().split("=", 1)[-1]])
    if temp is not None:
        rows.append(["Temperature", f"{temp:.1f} °C"])
        if temp >= 80 and rank[worst] < 2:
            worst = "warn"
    headline = ("Low voltage right now -- the power supply or cable is too weak" if any(s == "fail" for _t, s in flags) else
                "Low voltage has happened since boot" if any("Low voltage has" in t_ for t_, _s in flags) else
                "Power and temperature look fine" if not flags else
                "Throttled right now" if any("right now" in t_ for t_, _s in flags) else "Throttling has happened")
    note = ""
    if any("Low voltage" in t_ for t_, _s in flags):
        note = ("Low voltage is a top cause of random shutdowns and USB radio resets: use the official supply, a short "
                "thick cable, and power USB devices from a powered hub")
    elif temp is not None and temp >= 80:
        note = "Hot: add a heatsink or fan; the Pi slows itself down above about 80 °C"
    if prob:
        rows.append(["Voltage flags", "can't read"])
        if not flags:
            headline = "Can't read the voltage flags" + (" -- temperature only" if temp is not None else "")
        note = (note + " " if note else "") + prob
        worst = "info" if worst == "pass" else worst
    return {"cmd": "vcgencmd get_throttled + temperature", "raw": "\n".join(raw),
            "summary": {"status": worst, "headline": headline, "rows": rows, "note": note}}

@_ts("Pi health", "ts_lastshut", "Last shutdown")
def _ts_lastshut():
    out, prob = _ts_cmd(["journalctl", "-b", "-1", "-n", "40", "--no-pager", "-o", "short-iso"], 15)
    if prob:
        return _ts_missing("journalctl -b -1", prob)
    if "Specify boot ID" in out or "No journal boot entry" in out or "-- No entries --" in out or not out.strip():
        return {"cmd": "journalctl -b -1 -n 40", "raw": out, "summary": {
            "status": "info", "headline": "No record of the previous boot",
            "note": "The journal isn't kept across reboots on this Pi. To keep it: sudo mkdir -p /var/log/journal "
                    "&& sudo systemctl restart systemd-journald. If a setting says Storage=volatile (check: "
                    "systemd-analyze cat-config systemd/journald.conf | grep -i storage), that keeps it in memory "
                    "only -- change it to Storage=persistent. Keeping it adds some SD card writes"}}
    lines = [ln for ln in out.splitlines() if ln.strip() and not ln.startswith("--")]
    tail = "\n".join(lines)
    uv, _p = _ts_cmd(["journalctl", "-b", "-1", "-k", "--no-pager", "-g", "(?i)under-?voltage"], 15)
    uv_n = len([x for x in uv.splitlines() if "voltage" in x.lower()])
    last = lines[-1] if lines else ""
    end = "\n".join(lines[-12:])
    if re.search(r"Reached target .*Reboot|systemd-reboot\.service|Rebooting\.?$|reboot: Restarting system", end, re.M):
        verdict, st = "Clean reboot", "pass"
    elif re.search(r"Reached target .*Power-?Off|systemd-poweroff\.service|Powering off|reboot: Power down|System halted", end, re.I):
        verdict, st = "Clean shutdown (powered off)", "pass"
    elif re.search(r"Reached target .*(?:Shutdown|System Shutdown|Final Step)|systemd-shutdown\[|Journal stopped", end):
        verdict, st = "Clean shutdown", "pass"
    else:
        verdict, st = "Ended suddenly -- power was lost or the Pi froze", "fail"
    rows = [["Last line before it stopped", f"{_ts_time(last)}  {_ts_msg(last)[:110]}"],
            ["Low-voltage warnings that boot", str(uv_n)]]
    if uv_n and st == "fail":
        verdict += " (low voltage was logged)"
    return {"cmd": "journalctl -b -1 -n 40 (+ kernel voltage lines)", "raw": tail + ("\n\n" + uv.strip() if uv_n else ""),
            "summary": {"status": st if not (uv_n and st == "pass") else "warn", "headline": verdict, "rows": rows,
                        "note": "Sudden ends with low-voltage warnings point at the power supply" if uv_n else ""}}

@_ts("Pi health", "ts_mem", "Memory and load")
def _ts_mem():
    try:
        mi = {ln.split(":")[0]: int(ln.split()[1]) for ln in Path("/proc/meminfo").read_text().splitlines()
              if ln.split()[1:2] and ln.split()[1].isdigit()}
        la = Path("/proc/loadavg").read_text().split()[:3]
    except (OSError, ValueError, IndexError) as exc:
        return _ts_missing("/proc/meminfo + /proc/loadavg", str(exc))
    cpus = os.cpu_count() or 1
    tot, av = mi.get("MemTotal", 0), mi.get("MemAvailable", 0)
    st_, sf = mi.get("SwapTotal", 0), mi.get("SwapFree", 0)
    used_swap = (st_ - sf) / st_ * 100 if st_ else 0.0
    free_pct = av / tot * 100 if tot else 0.0
    l1, l5, l15 = (float(x) for x in la)
    st = "pass"
    notes = []
    if free_pct < 10:
        st = "warn"
        notes.append("Short on memory -- audio can stutter and services can be killed")
    if used_swap > 50:
        st = "warn"
        notes.append("Using a lot of swap -- slow on an SD card")
    if l5 / cpus > 1.5:
        st = "warn"
        notes.append("CPU busy for minutes at a time -- can cause choppy audio")
    top, _p = _ts_cmd(["ps", "-eo", "pcpu,pmem,comm", "--sort=-pcpu"], 5)
    tops = [ln.split(None, 2) for ln in top.splitlines()[1:6] if len(ln.split()) >= 3]
    return {"cmd": "/proc/meminfo + /proc/loadavg + ps", "raw": top, "summary": {
        "status": st, "headline": "Memory and CPU look fine" if st == "pass" else "Something is running short",
        "rows": [["Memory free", f"{av // 1024} of {tot // 1024} MB ({free_pct:.0f}%)"],
                 ["Swap used", f"{(st_ - sf) // 1024} of {st_ // 1024} MB" if st_ else "no swap"],
                 ["CPU load (1 / 5 / 15 min)", f"{l1:.2f} / {l5:.2f} / {l15:.2f} on {cpus} cores"]],
        "table": {"head": ["CPU %", "Memory %", "Program"], "rows": [[a, b, c] for a, b, c in tops]} if tops else None,
        "note": "; ".join(notes)}}

@_ts("Network", "ts_fw", "Firewall check")
def _ts_fw():
    rules = _ph_fw_udp_rules()
    zones = _firewalld_active_zones() if rules.get("backend") == "firewalld" else []
    lo, hi = _rt_rtp_range()
    iaxp = _ts_iax_port()
    try:
        sipp = _ph_sip_port(_ph_load_ctx())
    except Exception:
        sipp = 5060
    want = [("AllStar links (IAX2)", iaxp, iaxp), ("Phone sign-in (SIP)", sipp, sipp), ("Call audio (RTP)", lo, hi)]
    rows, worst = [], "pass"
    rank = {"pass": 0, "info": 1, "warn": 2, "fail": 3}
    for what, a, b in want:
        c = _ph_fw_cover(rules, a, b)
        span = f"UDP {a}" if a == b else f"UDP {a}-{b}"
        if c["state"] == "nofilter":
            st, txt = "info", "no firewall filtering"
        elif c["state"] == "unknown":
            st, txt = "info", "can't tell"
        elif c["state"] == "open":
            st, txt = "pass", "open"
        elif c["state"] == "partial":
            st, txt = "warn", "partly open (missing " + ", ".join(f"{x}-{y}" if x != y else str(x) for x, y in c["gaps"][:3]) + ")"
        else:
            st, txt = ("fail" if a == iaxp else "warn"), "closed"
        rows.append([what, span, [txt, st]])
        if rank[st] > rank[worst]:
            worst = st
    head = {"pass": "Needed ports are open", "info": "No firewall filtering on this Pi" if rules.get("filtering") is False
            else "Firewall state unclear", "warn": "Some ports are closed", "fail": "AllStar port is closed"}[worst]
    return {"cmd": f"{rules.get('backend') or 'firewall'} rules" + (f" (zone {', '.join(zones)})" if zones else ""),
            "raw": json.dumps({"backend": rules.get("backend"), "zones": zones, "allowed_udp": rules.get("allowed")}, indent=1),
            "summary": {"status": worst, "headline": head,
                        "rows": [["Firewall", rules.get("backend") or "none"]] + ([["Active zone", ", ".join(zones)]] if zones else []),
                        "table": {"head": ["For", "Port", "State"], "rows": rows},
                        "note": "Open closed ports on the Ports/Firewall tab. The router needs its own forwards too"
                                if rank[worst] >= 2 else ""}}

def _ts_dmr_master() -> str:
    for f in ("/opt/MMDVM_Bridge/MMDVM_Bridge.ini", "/etc/MMDVM_Bridge/MMDVM_Bridge.ini", "/etc/dvswitch/MMDVM_Bridge.ini"):
        try:
            txt = Path(f).read_text(errors="replace")
        except OSError:
            continue
        sec = ""
        for raw in txt.splitlines():
            ln = raw.split(";", 1)[0].strip()
            m = re.match(r"^\[([^\]]+)\]", ln)
            if m:
                sec = m.group(1).strip().lower()
            elif sec == "dmr network" and ln.lower().startswith("address") and "=" in ln:
                v = ln.split("=", 1)[1].strip()
                if v and not re.fullmatch(r"[\d.]+", v):
                    return v
    return ""

@_ts("Network", "ts_dns", "Name lookups")
def _ts_dns():
    hosts = [("AllStarLink sign-in", "register.allstarlink.org"), ("AllStarLink stats", "stats.allstarlink.org")]
    try:
        doc = json.loads(_PH_PHONE_JSON.read_text())
        for n in doc.get("networks") or []:
            h = str(n.get("host", "")).strip()
            if h and not re.fullmatch(r"[\d.]+", h) and h not in [x[1] for x in hosts]:
                hosts.append((f"Phone: {n.get('name', h)}", h))
    except (OSError, ValueError, AttributeError):
        pass
    dmr = _ts_dmr_master()
    if dmr:
        hosts.append(("DMR master (MMDVM_Bridge)", dmr))
    nb = _ts_net_basics()
    rows, bad, raw = [nb["ping"], nb["dns"]], 0, list(nb["raw"])
    for what, h in hosts[:10]:
        out, prob = _ts_cmd(["getent", "ahostsv4", h], 6)
        ips = sorted({ln.split()[0] for ln in out.splitlines() if ln.split()})
        raw.append(f"{h}: {', '.join(ips) or prob or 'not found'}")
        if ips:
            rows.append([what, h, [", ".join(ips[:2]), "pass"]])
        else:
            bad += 1
            rows.append([what, h, [prob or "not found", "fail"]])
    found = len(hosts[:10]) - bad
    if found and not bad and not nb["dns_ok"]:
        rows[1] = [rows[1][0], rows[1][1], [rows[1][2][0] + " -- yet names are found, so something else answers", "warn"]]
        nb["dns_ok"] = True
    nf = f"{bad} name{'s' if bad != 1 else ''} can't be found"
    if nb["inet"] is False:
        head = "No internet by IP" + (f" · {nf}" if bad else "")
        note = "The Pi can't reach the internet at all: check its gateway (ip route) -- a static IP needs one"
    elif not nb["dns_ok"]:
        head = "No usable DNS server" + (f" · {nf}" if bad else "")
        note = ("Add DNS servers to the connection (for example nmcli con mod <name> ipv4.dns \"8.8.8.8 1.1.1.1\", "
                "then nmcli con up <name>)")
    elif bad and not found:
        head = ("Internet works but no names can be found -- DNS problem" if nb["inet"]
                else "No names can be found -- DNS or internet problem")
        note = "The DNS servers listed aren't answering: try 8.8.8.8 and 1.1.1.1, then nmcli con up <name>"
    elif bad:
        head = nf
        note = "Others are found, so DNS works: check the spelling of the ones that fail"
    else:
        head, note = "All names found", ""
    return {"cmd": "ping + resolv.conf + getent ahostsv4 <name>", "raw": "\n".join(raw), "summary": {
        "status": _ts_worst([r[2][1] for r in rows]),
        "headline": head,
        "table": {"head": ["For", "Name", "Address"], "rows": rows},
        "note": note}}

@_ts("Network", "ts_clock", "Clock check")
def _ts_clock():
    out, prob = _ts_cmd(["timedatectl", "show", "-p", "NTPSynchronized", "-p", "NTP", "-p", "Timezone"], 6)
    if prob:
        return _ts_missing("timedatectl", prob)
    kv = dict(ln.split("=", 1) for ln in out.splitlines() if "=" in ln)
    synced, ntp = kv.get("NTPSynchronized") == "yes", kv.get("NTP") == "yes"
    st = "pass" if synced else "warn"
    return {"cmd": "timedatectl show", "raw": out, "summary": {
        "status": st, "headline": "Clock is in sync" if synced else ("Clock is NOT in sync" if ntp else "Time sync is turned off"),
        "rows": [["Now", datetime.now().strftime("%Y-%m-%d %H:%M:%S")], ["Time zone", kv.get("Timezone", "?")],
                 ["Time sync", "on" if ntp else "off"], ["Synced", "yes" if synced else "no"]],
        "note": "" if synced else ("A wrong clock makes sign-ins and secure connections fail. "
                                   + ("Turn it on: sudo timedatectl set-ntp true" if not ntp else
                                      "Sync is on but hasn't worked -- check internet and that UDP 123 isn't blocked"))}}

@_ts("Network", "ts_wifi", "WiFi signal")
def _ts_wifi():
    rt, prob = _ts_cmd(["ip", "route", "show", "default"], 5)
    m = re.search(r"\bdev\s+(\S+)", rt)
    dev = m.group(1) if m else ""
    if not dev:
        return _ts_missing("ip route", prob or "No default route -- the Pi may be offline")
    wireless = Path(f"/sys/class/net/{dev}/wireless").exists()
    stats = {}
    for k in ("rx_dropped", "tx_dropped", "rx_errors", "tx_errors", "rx_packets", "tx_packets"):
        try:
            stats[k] = int(Path(f"/sys/class/net/{dev}/statistics/{k}").read_text().strip())
        except (OSError, ValueError):
            pass
    err_rows = [["Dropped (in / out)", f"{stats.get('rx_dropped', '?')} / {stats.get('tx_dropped', '?')}"],
                ["Errors (in / out)", f"{stats.get('rx_errors', '?')} / {stats.get('tx_errors', '?')}"]]
    if not wireless:
        return {"cmd": f"ip route + /sys/class/net/{dev}", "raw": rt, "summary": {
            "status": "info", "headline": f"Wired ({dev}) -- no WiFi to check", "rows": [["Interface", dev]] + err_rows}}
    out, prob = _ts_cmd(["iw", "dev", dev, "link"], 6)
    sig = re.search(r"signal:\s*(-?\d+)\s*dBm", out)
    rate = re.search(r"tx bitrate:\s*([\d.]+\s*\S+)", out)
    ssid = re.search(r"SSID:\s*(.+)", out)
    if not sig:
        try:
            for ln in Path("/proc/net/wireless").read_text().splitlines():
                if ln.strip().startswith(dev + ":"):
                    lv = ln.split()[3].rstrip(".")
                    sig = re.match(r"(-?\d+)", lv)
        except OSError:
            pass
    dbm = int(sig.group(1)) if sig else None
    if dbm is None:
        word, st = "can't read", "info"
    elif dbm >= -60:
        word, st = "good", "pass"
    elif dbm >= -70:
        word, st = "fair", "warn"
    else:
        word, st = "poor", "fail"
    drops = stats.get("rx_dropped", 0) + stats.get("tx_dropped", 0)
    pk = stats.get("rx_packets", 0) + stats.get("tx_packets", 0)
    if pk and drops / pk > 0.01 and st == "pass":
        st = "warn"
    return {"cmd": f"iw dev {dev} link + interface counters", "raw": out or prob, "summary": {
        "status": st, "headline": f"WiFi signal {word}" + (f" ({dbm} dBm)" if dbm is not None else ""),
        "rows": [["Interface", dev], ["Network", ssid.group(1).strip() if ssid else "?"],
                 ["Signal", f"{dbm} dBm" if dbm is not None else "?"], ["Speed", rate.group(1) if rate else "?"]] + err_rows,
        "note": "" if st == "pass" else ("Weak WiFi causes link drops and choppy audio: move the Pi or access point closer, "
                                         "or use a cable" if dbm is not None and dbm < -60 else prob)}}

_TS_DASH_MIN = "9.3.69"
_TS_JS_NOT_FUNCS = frozenset((
    "if", "for", "while", "switch", "return", "typeof", "new", "function", "void", "delete",
    "alert", "confirm", "prompt", "encodeURIComponent", "decodeURIComponent", "parseInt",
    "parseFloat", "setTimeout", "clearTimeout", "setInterval", "clearInterval", "String",
    "Number", "Boolean", "Array", "Object", "JSON", "Math", "Date", "isNaN", "fetch"))
_TS_JS_FUNC_RE = re.compile(r"(?:^|[^\w$.])function\s+([A-Za-z_$][\w$]*)\s*\(")
_TS_JS_ARROW_RE = re.compile(r"(?:^|[^\w$.])(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*"
                             r"(?:async\s+)?(?:function\b|\([^)]*\)\s*=>|[A-Za-z_$][\w$]*\s*=>)")
_TS_JS_WIN_RE = re.compile(r"window\.([A-Za-z_$][\w$]*)\s*=")
_TS_ON_ATTR_RE = re.compile(r"""\bon[a-z]+\s*=\s*(?:"([^"]*)"|'([^']*)')""")
_TS_JS_CALL_RE = re.compile(r"(?<![\w$.])([A-Za-z_$][\w$]*)\s*\(")

def _ts_dash_file() -> "tuple[str, str]":
    tried = []
    for f in _ts_dash_paths():
        try:
            with open(f, encoding="utf-8", errors="replace") as fh:
                return f, fh.read()
        except OSError:
            tried.append(f)
    return "", "asl_dvs_dashboard.py not found (looked in " + ", ".join(tried) + " and systemctl)"

def _ts_vnum(v: str) -> tuple:
    try:
        return tuple(int(x) for x in v.split("."))
    except ValueError:
        return ()

def _ts_dash_page_check(tree) -> "tuple[list, list, int, int]":
    html = ""
    for node in tree.body:
        if (isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == "HTML" for t in node.targets)
                and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str)):
            html = node.value.value
    js = "\n".join(re.findall(r"<script[^>]*>(.*?)</script>", html, re.S | re.I))
    names = _TS_JS_FUNC_RE.findall(js)
    defined = set(names) | set(_TS_JS_ARROW_RE.findall(js)) | set(_TS_JS_WIN_RE.findall(js))
    seen, twice = set(), []
    for n in names:
        if n in seen and n not in twice:
            twice.append(n)
        seen.add(n)
    markup = re.sub(r"(?m)(^|[\s;{}])//[^\n]*", r"\1", re.sub(r"/\*.*?\*/", "", html, flags=re.S))
    called = set()
    for a, b in _TS_ON_ATTR_RE.findall(markup):
        code = re.sub(r"\$\{[^}]*\}", "", a or b)
        called.update(n for n in _TS_JS_CALL_RE.findall(code) if n not in _TS_JS_NOT_FUNCS)
    return sorted(called - defined), twice, len(called), len(defined)

@_ts("Dashboard", "ts_dashfile", "Dashboard file check")
def _ts_dashfile():
    path, text = _ts_dash_file()
    if not path:
        return _ts_missing("asl_dvs_dashboard.py", text + ". Normal if the dashboard isn't installed on this Pi.")
    cmd = f"read {path} (no connection to port {DASHBOARD_PORT})"
    ver = _ts_dash_version_of(text[:4000])
    rows, raw = [], [f"file: {path}", f"version: {ver or '?'}"]
    old = bool(ver) and _ts_vnum(ver) < _ts_vnum(_TS_DASH_MIN)
    rows.append(["Version", (ver or "not found in the file", "warn" if old or not ver else "pass")])
    try:
        tree = ast.parse(text, path)
        compile(tree, path, "exec")
    except SyntaxError as exc:
        rows.append(["Python", (f"does not compile: line {exc.lineno}: {exc.msg}", "fail")])
        raw.append(f"SyntaxError line {exc.lineno}: {exc.msg}")
        return {"cmd": cmd, "raw": "\n".join(raw), "summary": {
            "status": "fail", "headline": "The dashboard file is broken", "rows": rows,
            "note": "The dashboard won't start with this file. Reinstall the last build that worked."}}
    rows.append(["Python", ("compiles", "pass")])
    defs = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))]
    dup_py = sorted({n for n in defs if defs.count(n) > 1})
    rows.append(["Python functions", (f"{len(defs)} defined" + (", twice: " + ", ".join(dup_py) if dup_py else ", none twice"),
                                      "warn" if dup_py else "pass")])
    missing, dup_js, n_called, n_def = _ts_dash_page_check(tree)
    rows.append(["Page functions", (f"{n_def} defined" + (", twice: " + ", ".join(dup_js) if dup_js else ", none twice"),
                                    "warn" if dup_js else "pass")])
    rows.append(["Page buttons and boxes", (f"{n_called} functions used, all found" if not missing else
                                            "no function for: " + ", ".join(missing), "fail" if missing else "pass")])
    raw += [f"python functions: {len(defs)}  defined twice: {', '.join(dup_py) or 'none'}",
            f"page functions: {n_def}  defined twice: {', '.join(dup_js) or 'none'}",
            f"page handlers use {n_called} functions  missing: {', '.join(missing) or 'none'}"]
    worst = _ts_worst([r[1][1] for r in rows])
    head = ("A button on the dashboard page calls a function that isn't there" if missing else
            f"Dashboard {ver} is older than {_TS_DASH_MIN}" if old else
            "Dashboard file looks fine" if worst == "pass" else "Dashboard file has warnings")
    return {"cmd": cmd, "raw": "\n".join(raw), "summary": {
        "status": worst, "headline": head, "rows": rows,
        "note": ("Reads the file only. A missing function means that button or box does nothing -- send the raw "
                 "text. A function defined twice means only the last copy runs.")}}

_TS_ASTDB = Path("/var/lib/asterisk/astdb.txt")
_TS_ASTDB_OLD_DAYS = 30

def _ts_dash_bridges() -> "set[str]":
    info = _ph_dash_info()
    out = {n for n in info.get("bridge_nodes") or [] if n}
    out.update(n for n in (info.get("phone_nodes") or {}) if n)
    if info.get("phone_node"):
        out.add(info["phone_node"])
    return out

def _ts_node_key(v: str) -> str:
    v = str(v).strip()
    return str(int(v)) if v.isdigit() and len(v) <= 7 else ""

def _ts_echo_as_asl(node: str) -> str:
    return "3" + str(node).strip().zfill(6)

@_ts("Dashboard", "ts_nodelists", "Node search lists")
def _ts_nodelists():
    bridges = _ts_dash_bridges()
    rows, raw = [], []
    try:
        st_ = _TS_ASTDB.stat()
        nodes: set = set()
        with open(_TS_ASTDB, encoding="utf-8", errors="replace") as fh:
            for ln in fh:
                ln = ln.strip()
                if not ln or ln.startswith(("#", ";")):
                    continue
                k = _ts_node_key(ln.split("|", 1)[0])
                if k:
                    nodes.add(k)
        age = (time.time() - st_.st_mtime) / 86400
        dated = datetime.fromtimestamp(st_.st_mtime).strftime("%Y-%m-%d")
        left = len(nodes & bridges)
        if not nodes:
            rows.append(["ASL node list", ("found but empty -- run: sudo asl3-update-astdb", "warn")])
        else:
            rows.append(["ASL node list", (f"{len(nodes) - left:,} node{'s' if len(nodes) - left != 1 else ''} to search, dated {dated}",
                                           "warn" if age > _TS_ASTDB_OLD_DAYS else "pass")])
            if age > _TS_ASTDB_OLD_DAYS:
                rows.append(["", (f"{int(age)} days old -- asl3-update-astdb may be turned off", "warn")])
        raw.append(f"{_TS_ASTDB}: {len(nodes)} nodes, modified {dated} ({age:.1f} days), {left} bridge/phone left out")
    except OSError as exc:
        rows.append(["ASL node list", ("not found -- turn on asl3-update-astdb", "warn")])
        raw.append(f"{_TS_ASTDB}: {exc}")
    out, prob = _ts_cmd(["asterisk", "-rx", "echolink dbdump"], timeout=10)
    if prob:
        rows.append(["EchoLink list", (prob, "info")])
        raw.append(f"echolink dbdump: {prob}")
    elif "no such command" in out.lower():
        rows.append(["EchoLink list", ("EchoLink isn't loaded in Asterisk -- fine if you don't use the Echo tab", "info")])
        raw.append("echolink dbdump: no such command (chan_echolink not loaded)")
    else:
        stations = set()
        for ln in out.splitlines():
            k = _ts_node_key(ln.split("|", 1)[0]) if "|" in ln else ""
            if k and k != "0":
                stations.add(k)
        left = sum(1 for k in stations if _ts_echo_as_asl(k) in bridges)
        rows.append(["EchoLink list", (f"{len(stations) - left:,} station{'s' if len(stations) - left != 1 else ''} logged in now" if stations else
                                       "empty -- EchoLink may still be logging in; try again in a few minutes",
                                       "pass" if stations else "warn")])
        raw.append(f"echolink dbdump: {len(stations)} stations, {left} bridge/phone left out")
    rows.append(["Left out of both", (", ".join(sorted(bridges, key=int)) if bridges else "none", "info")])
    raw.append("bridge + phone nodes: " + (", ".join(sorted(bridges, key=int)) or "none"))
    worst = _ts_worst([r[1][1] for r in rows])
    head = ("Both search lists are ready" if worst in ("pass", "info") and all(
                r[1][1] == "pass" for r in rows if r[0] in ("ASL node list", "EchoLink list")) else
            "A search list needs attention" if worst == "warn" else "Search lists checked")
    return {"cmd": f"{_TS_ASTDB} + asterisk -rx \"echolink dbdump\"", "raw": "\n".join(raw), "summary": {
        "status": worst, "headline": head, "rows": rows,
        "note": ("These are what the dashboard's ASL and Echo search cards look through. Bridge and phone "
                 "nodes are left out on purpose. Reads only -- nothing is changed.")}}

_TS_FAV_SECS = ("ASL", "ECHO", "DSTAR", "XLX")
_TS_FAV_SLOTS = 10
_TS_DSTAR_RE = re.compile(r"^([A-Z0-9 ]{6})([A-Z])L$")
_TS_DSTAR_BASE_RE = re.compile(r"^(REF|XRF|DCS)\d{3}$")
_TS_DSTAR_GW_RE = re.compile(r"^(?=[A-Z0-9]*\d)[A-Z0-9]{3,6}$")
_TS_XLX_RE = re.compile(r"^XLX[A-Z0-9]{3}[A-Z]L$")

def _ts_fav_rows(text: str) -> "dict[str, list]":
    out: dict = {k: [] for k in _TS_FAV_SECS}
    sec = None
    for ln in text.splitlines():
        ln = ln.strip()
        if not ln or ln.startswith("#"):
            continue
        if ln.startswith("[") and "]" in ln:
            sec = ln[1:ln.index("]")].strip().upper()
            continue
        if sec not in out or "|" not in ln:
            continue
        parts = [x.strip() for x in ln.split("|")]
        if not parts[0] or not parts[1]:
            continue
        out[sec].append((len(out[sec]) + 1, parts[0], parts[1], len(parts)))
    return out

def _ts_fav_is_blank(name: str, val: str) -> bool:
    return val == "000000" or name.lower() == "blank"

def _ts_fav_node(sec: str, name: str, val: str, slot: int, seen: set, bridges: set) -> "tuple[str, str]":
    k = _ts_node_key(val)
    if not k or k == "0":
        return "fail", "not a node number (1-7 digits)"
    if slot > _TS_FAV_SLOTS:
        return "warn", f"past slot {_TS_FAV_SLOTS} -- the dashboard doesn't load it"
    if (_ts_echo_as_asl(k) if sec == "ECHO" else k) in bridges:
        return "warn", "a bridge or phone node -- remove it in Edit (the dashboard won't re-save it)"
    if k in seen:
        return "warn", "saved twice"
    seen.add(k)
    return "pass", "ok"

def _ts_fav_ref(sec: str, val: str, nfields: int, seen: set) -> "tuple[str, str]":
    tg = val.upper()
    if sec == "XLX":
        if nfields >= 4:
            return "warn", "old 4-field row -- skipped when the dashboard loads; save it again in Edit"
        if not _TS_XLX_RE.match(tg):
            return "fail", "not XLX + 3 characters + module + L -- won't tune"
        st, note = "pass", "ok"
    else:
        if tg.strip() == "U":
            return "info", "unlink row -- left out when the dashboard loads"
        m = _TS_DSTAR_RE.match(tg)
        if not m:
            if (re.match(r"^[A-Z0-9]{3,6} [A-Z]$", tg) or re.match(r"^[A-Z0-9 ]{6}[A-Z]$", tg)
                    or re.match(r"^[A-Z0-9]{3,5}[A-Z]L$", tg)):
                return "info", "old form -- the dashboard fixes it when it loads; Save in Edit to rewrite it"
            return "fail", "not a 6-character base + module + L -- won't tune"
        base = m.group(1)
        if _TS_DSTAR_BASE_RE.match(base.strip()):
            st, note = "pass", "ok"
        elif base == base.strip().ljust(6) and _TS_DSTAR_GW_RE.match(base.strip()):
            st, note = "pass", "gateway callsign -- linked through ircDDB (see the ASL-DVS tab's D-Star card)"
        else:
            st, note = "info", "not a REF/XRF/DCS name or gateway callsign -- tunes only if DVSwitch knows it"
    if tg in seen:
        return "warn", "saved twice"
    seen.add(tg)
    return st, note

@_ts("Dashboard", "ts_favs", "Saved favorites")
def _ts_favs():
    conf = Path(_ASL_DVS_CONF)
    try:
        text = conf.read_text(errors="replace")
    except OSError as exc:
        return _ts_missing(str(conf), f"Can't read it: {exc}. Normal if the dashboard isn't installed on this Pi.")
    bridges = _ts_dash_bridges()
    rows, raw = [], []
    for sec, items in _ts_fav_rows(text).items():
        seen: set = set()
        used = 0
        for slot, name, val, nf in items:
            if _ts_fav_is_blank(name, val):
                continue
            used += 1
            st, note = (_ts_fav_node(sec, name, val, slot, seen, bridges) if sec in ("ASL", "ECHO")
                        else _ts_fav_ref(sec, val, nf, seen))
            rows.append([sec, str(slot), f"{name} · {val}", [note, st]])
            raw.append(f"[{sec}] slot {slot:>2}  {name}|{val}  -> {st.upper()}: {note}")
        raw.append(f"[{sec}] {used} saved")
    if not rows:
        return {"cmd": str(conf), "raw": "\n".join(raw) or "no favorite sections", "summary": {
            "status": "info", "headline": "No ASL, Echo, D-STAR or XLX favorites saved yet",
            "note": "Save one on the dashboard, then run this again."}}
    fails = sum(1 for r in rows if r[3][1] == "fail")
    warns = sum(1 for r in rows if r[3][1] == "warn")
    worst = _ts_worst([r[3][1] for r in rows])
    head = (f"{fails} favorite{'s' if fails != 1 else ''} won't work" if fails else
            f"{warns} favorite{'s' if warns != 1 else ''} to look at" if warns else
            f"All {len(rows)} saved favorites look right")
    return {"cmd": str(conf), "raw": "\n".join(raw), "summary": {
        "status": worst, "headline": head,
        "table": {"head": ["Tab", "Slot", "Saved", "Check"], "rows": rows},
        "note": ("Reads asl_dvs.conf only. Run it after tapping Save on the dashboard (search card, quick bar "
                 "or Edit tab) to see the row landed in the right form.")}}

_SELFCHECK_ROUTES = (
    ("Overview", "/api/overview"), ("Services", "/api/services"), ("Ports", "/api/ports"),
    ("Firewall", "/api/firewall"), ("Journal", "/api/journal/list"), ("ASL-DVS", "/api/status"),
    ("Reg", "/api/reg/iax"), ("Phone", "/api/phone"), ("Tune", "/api/simpleusb/tune"),
    ("Tune", "/api/rpt/nodesettings"), ("Hardware", "/api/hardware"), ("Net", "/api/net"),
    ("DVSM", "/api/dvsm"), ("STFU", "/api/stfu"), ("M17", "/api/m17"), ("Zello", "/api/zello"),
    ("ASL-DVS", "/api/dstar-gw"),
    ("SD Card", "/api/sdcard"), ("Security", "/api/security/checks"), ("Console", "/api/console/tcatalog"),
    ("Edit", "/api/asterisk/files"),
)

_SELFCHECK_TIMEOUT = 25

def _selfcheck_one(route: str) -> "tuple[str, str, float]":
    fn = _GET_ROUTES.get(route)
    if fn is None:
        return "fail", "route missing", 0.0
    h = _SelfCheckHandler(route)
    box: dict = {}

    def run():
        try:
            fn(h)
        except Exception as exc:
            box["err"] = f"{type(exc).__name__}: {exc}"

    t0 = time.monotonic()
    th = threading.Thread(target=run, daemon=True)
    th.start()
    th.join(_SELFCHECK_TIMEOUT)
    took = time.monotonic() - t0
    if th.is_alive():
        return "fail", f"no answer in {_SELFCHECK_TIMEOUT} s", took
    if "err" in box:
        return "fail", box["err"][:160], took
    if h.result is None:
        return "fail", "sent no answer", took
    status, data = h.result
    if status >= 500:
        return "fail", f"error {status}", took
    if not isinstance(data, dict):
        return "warn", "answer is not JSON", took
    if data.get("ok") is False:
        return "warn", str(data.get("message") or data.get("error") or "ok=false")[:160], took
    return "pass", "ok", took

@_ts("Sysmon", "ts_selfcheck", "Page self-check")
def _ts_selfcheck():
    rows, raw, worst = [], [], "pass"
    rank = {"pass": 0, "warn": 1, "fail": 2}
    for tab, route in _SELFCHECK_ROUTES:
        st, msg, took = _selfcheck_one(route)
        worst = max(worst, st, key=rank.get)
        rows.append([f"{tab} ({route})", (f"{msg} · {took:.1f} s", st)])
        raw.append(f"{st.upper():4} {route:26} {took:5.1f}s  {msg}")
    fails = sum(1 for r in rows if r[1][1] == "fail")
    warns = sum(1 for r in rows if r[1][1] == "warn")
    head = ("Every tab answered" if worst == "pass" else
            f"{fails} tab(s) failed, {warns} with warnings" if fails else f"{warns} tab(s) answered with warnings")
    return {"cmd": f"sysmon {VERSION}: read every tab's data route", "raw": "\n".join(raw), "summary": {
        "status": worst, "headline": head, "rows": rows,
        "note": ("Reads only -- nothing is changed. A warning usually means a part isn't installed "
                 "on this Pi (normal). A failure means that tab's code broke -- send the raw text.")}}

def serialize_pinned_services(pinned: list) -> str:
    lines = []
    for entry in pinned:
        if "group" in entry:
            lines.append(f"__GROUP__:{entry['group']}")
        else:
            lines.append(
                f"{entry['unit']} | {entry.get('desc','')} "
                f"| {entry.get('config','-')} "
                f"| {entry.get('port','-')} "
                f"| {entry.get('proto','-')}"
            )
    return "\n".join(lines)

def pin_service(unit: str, group: str, desc: str = "",
                config: str = "-", port: str = "-", proto: str = "-") -> bool:
    if any(e.get("unit") == unit for e in _pinned):
        return False
    if not _validate_unit(unit):
        return False

    new_entry = {"unit": unit, "desc": desc, "config": config,
                 "port": port, "proto": proto}
    result    = list(_pinned)
    in_group  = False
    insert_at = len(result)

    for i, e in enumerate(result):
        if "group" in e and e["group"] == group:
            in_group = True
            continue
        if in_group and "group" in e:
            insert_at = i
            break

    if not in_group:
        result.append({"group": group})
        result.append(new_entry)
    else:
        result.insert(insert_at, new_entry)

    ok = save_config({"services.pinned": serialize_pinned_services(result)})
    if ok:
        reload_config()
    return ok

def unpin_service(unit: str) -> bool:
    if not any(e.get("unit") == unit for e in _pinned):
        return False

    new_list = [e for e in _pinned if e.get("unit") != unit]

    pruned = []
    for i, e in enumerate(new_list):
        if "group" in e:
            found_svc = False
            for r in new_list[i + 1:]:
                if "group" in r:
                    break
                if "unit" in r:
                    found_svc = True
                    break
            if found_svc:
                pruned.append(e)
        else:
            pruned.append(e)

    ok = save_config({"services.pinned": serialize_pinned_services(pruned)})
    if ok:
        reload_config()
    return ok

_ALL_TABS = ("overview", "services", "ports", "firewall", "journal",
             "asldvs", "reg", "phone", "tune", "hardware", "net", "dvsm", "stfu", "m17", "zello", "sdcard",
             "security", "console", "edit")

_LOCKED_TABS = ("overview", "edit")

def _sanitize_enabled_tabs(raw) -> list:
    if isinstance(raw, str):
        items = raw.split(",")
    elif isinstance(raw, (list, tuple)):
        items = raw
    else:
        items = []
    wanted = {str(t).strip().lower() for t in items}
    wanted.update(_LOCKED_TABS)
    return [t for t in _ALL_TABS if t in wanted]

def _get_enabled_tabs() -> list:
    raw = _cfg.get("ui", "enabled_tabs",
                   fallback=_DEFAULT_CONFIG["ui"]["enabled_tabs"])
    return _sanitize_enabled_tabs(raw)

def validate_config(updates: dict) -> list:
    errors = []
    if "identity.callsign" in updates:
        cs = str(updates["identity.callsign"]).strip().upper()
        if not re.fullmatch(r"[A-Z0-9 /.\-]{1,9}", cs):
            errors.append(f"callsign '{cs}' invalid — use A-Z 0-9 - / . (max 9 chars)")
    if "identity.node" in updates:
        node = str(updates["identity.node"]).strip()
        if not re.fullmatch(r"\d{1,7}", node):
            errors.append(f"node '{node}' invalid — numeric only, 1-7 digits")
    for key in ("server.port",):
        if key in updates:
            try:
                p = int(updates[key])
                if not (1024 <= p <= 65535):
                    raise ValueError
            except (ValueError, TypeError):
                errors.append(f"{key} must be an integer 1024–65535")
    if "server.host" in updates:
        if not str(updates["server.host"]).strip():
            errors.append("server.host must not be empty")
    return errors

def reload_config() -> None:
    global _cfg, _pinned
    _cfg    = load_config()
    _pinned = parse_pinned_services(_get_pinned_raw())

_APPCONF_FILES: "list[Path]" = [
    Path("/etc/asl_dvs/asl_dvs.conf"),
    Path("/etc/sysmon/sysmon.conf"),
]

def _route_config_get(h: Handler) -> None:
    h.send_json({
        "ok":           True,
        "server": {
            "port": _cfg.get("server",   "port", fallback=str(DEFAULT_PORT)),
            "host": _cfg.get("server",   "host", fallback="0.0.0.0"),
        },
        "identity": {
            "callsign": _cfg.get("identity", "callsign", fallback=""),
            "node":     _cfg.get("identity", "node",     fallback=""),
            "label":    _cfg.get("identity", "label",    fallback=""),
        },
        "thresholds": {
            "cpu_warn_pct": _cfg.get("thresholds", "cpu_warn_pct", fallback="50"),
            "rss_warn_mb":  _cfg.get("thresholds", "rss_warn_mb",  fallback="200"),
            "nr_warn":      _cfg.get("thresholds", "nr_warn",      fallback="3"),
            "nr_crit":      _cfg.get("thresholds", "nr_crit",      fallback="10"),
        },
        "services": {
            "pinned": _get_pinned_raw(),
        },
        "asldvs": {
            "hidden_files": _cfg.get("asldvs", "hidden_files", fallback=""),
        },
        "ui": {

            "enabled_tabs": _get_enabled_tabs(),
        },
    })

def _route_pinned_get(h: Handler) -> None:
    groups       = [e["group"] for e in _pinned if "group" in e]
    pinned_units = [e["unit"]  for e in _pinned if "unit"  in e]
    h.send_json({"ok": True, "groups": groups, "pinned_units": pinned_units})

def _route_pinned_post(h: Handler, data: dict) -> None:
    if os.geteuid() != 0:
        h.send_json({"ok": False, "message": "root required"}); return

    action = str(data.get("action", "")).strip().lower()
    unit   = str(data.get("unit",   "")).strip()

    if not _validate_unit(unit):
        h.send_json({"ok": False, "message": f"Invalid unit: {unit!r}"}, 400)
        return

    if action == "pin":
        group  = str(data.get("group",  "Services")).strip() or "Services"
        desc   = str(data.get("desc",   "")).strip()
        config = str(data.get("config", "-")).strip() or "-"
        port   = str(data.get("port",   "-")).strip() or "-"
        proto  = str(data.get("proto",  "-")).strip() or "-"
        if any(e.get("unit") == unit for e in _pinned):
            h.send_json({"ok": False, "message": f"{unit} is already pinned"})
            return
        ok = pin_service(unit, group, desc, config, port, proto)
        msg = f"Pinned {unit} to '{group}'" if ok else "Save failed"
        _log(msg)
        h.send_json({"ok": ok, "message": msg})

    elif action == "unpin":
        if not any(e.get("unit") == unit for e in _pinned):
            h.send_json({"ok": False, "message": f"{unit} is not pinned"})
            return
        ok = unpin_service(unit)
        msg = f"Unpinned {unit}" if ok else "Save failed"
        _log(msg)
        h.send_json({"ok": ok, "message": msg})

    else:
        h.send_json({"ok": False, "message": f"Unknown action: {action!r}"}, 400)

def _route_config_post(h: Handler, data: dict) -> None:
    if os.geteuid() != 0:
        h.send_json({"ok": False, "message": "root required"}); return

    errors = validate_config(data)
    if errors:
        h.send_json({"ok": False, "errors": errors}, 400)
        return

    if "ui.enabled_tabs" in data:
        data["ui.enabled_tabs"] = ",".join(_sanitize_enabled_tabs(data["ui.enabled_tabs"]))

    old_port = _cfg.get("server", "port", fallback=str(DEFAULT_PORT))
    old_host = _cfg.get("server", "host", fallback="0.0.0.0")

    ok = save_config(data)
    if not ok:
        h.send_json({"ok": False, "message": "Disk write failed — check log"}); return

    new_port = _cfg.get("server", "port", fallback=str(DEFAULT_PORT))
    new_host = _cfg.get("server", "host", fallback="0.0.0.0")
    if new_port != old_port or new_host != old_host:
        _update_state(needs_restart=True)
        _log("WARN — server address changed; restart required", stderr=True)

    reload_config()
    h.send_json({"ok": True, "message": "Config saved"})

